SELECT rc.loan_id, rc.as_of_date FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code WHERE g.grade_name_zh = '次级' ORDER BY rc.loan_id;	bankreg_main
SELECT loan_id, principal_overdue_days, overdue_principal FROM delinquency_snapshot WHERE principal_overdue_days > 360 ORDER BY principal_overdue_days DESC, loan_id;	bankreg_main
SELECT account_id, ledger_balance FROM account_balance_snapshot WHERE ledger_balance > 5000000 ORDER BY ledger_balance DESC, account_id;	bankreg_main
SELECT a.account_id, i.institution_name FROM account a JOIN institution i ON i.institution_id = a.institution_id JOIN status_catalog s ON s.entity = 'account' AND s.status_code = a.status WHERE s.name_zh = '久悬' ORDER BY a.account_id;	bankreg_main
SELECT p.party_id, p.display_name FROM party p JOIN organization_profile op ON op.party_id = p.party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE s.sector_name_zh = '房地产业' ORDER BY p.party_id;	bankreg_main
SELECT product_id, product_name, planned_raise_amount FROM wealth_product WHERE risk_level = 'R5' AND status = 'ON_SALE' ORDER BY product_id;	bankreg_main
SELECT ld.loan_id, ld.disbursed_amount FROM loan_drawdown ld JOIN status_catalog s ON s.entity = 'loan_drawdown' AND s.status_code = ld.status WHERE s.name_zh = '已核销' ORDER BY ld.loan_id;	bankreg_main
SELECT pe.payment_id, pe.business_date, pe.amount FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE t.name_zh = '现金支取' AND pe.amount > 5000000 ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT product_id, inception_on, actual_termination_on FROM wealth_product WHERE actual_termination_on IS NOT NULL ORDER BY product_id;	bankreg_main
SELECT agreement_id, contract_amount FROM credit_agreement WHERE security_type = 'CREDIT' ORDER BY agreement_id;	bankreg_main
SELECT ca.collateral_id, ca.asset_label, cv.valuation_amount FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valued_on = (SELECT MAX(cv2.valued_on) FROM collateral_valuation cv2                       WHERE cv2.collateral_id = ca.collateral_id) ORDER BY cv.valuation_amount DESC, ca.collateral_id;	bankreg_main
SELECT party_id, annual_income FROM person_profile WHERE annual_income > 1000000 ORDER BY annual_income DESC, party_id;	bankreg_main
SELECT card_id, issued_on, expires_on FROM payment_card WHERE card_type = 'CREDIT' ORDER BY issued_on, card_id;	bankreg_main
SELECT p.party_id, p.display_name, op.operating_status FROM party p JOIN organization_profile op ON op.party_id = p.party_id WHERE op.registered_region IN (SELECT region_code FROM organization_unit WHERE unit_name = '上海分行') ORDER BY p.party_id;	bankreg_main
SELECT agreement_id, maturity_on, contract_amount FROM credit_agreement WHERE status = 'MATURED' ORDER BY maturity_on, agreement_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS loan_count FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY loan_count DESC, i.institution_name;	bankreg_main
SELECT ou.org_unit_id, ou.unit_name, COUNT(*) AS account_count FROM account a JOIN organization_unit ou ON ou.org_unit_id = a.org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY account_count DESC, ou.org_unit_id;	bankreg_main
SELECT s.sector_name_zh, COUNT(*) AS customer_count FROM organization_profile op JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY s.sector_code, s.sector_name_zh ORDER BY customer_count DESC, s.sector_name_zh;	bankreg_main
SELECT sm.staff_id, COUNT(*) AS agreement_count FROM credit_agreement a JOIN organization_unit ou ON ou.org_unit_id = a.managing_org_unit_id JOIN staff_assignment sa ON sa.org_unit_id = ou.org_unit_id JOIN staff_member sm ON sm.staff_id = sa.staff_id GROUP BY sm.staff_id ORDER BY agreement_count DESC, sm.staff_id LIMIT 10;	bankreg_main
SELECT i.institution_name, ROUND(SUM(ld.disbursed_amount), 2) AS total_disbursed FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY total_disbursed DESC, i.institution_name;	bankreg_main
SELECT lp.product_name_zh, COUNT(*) AS loan_count,        ROUND(AVG(ld.disbursed_amount), 2) AS avg_amount FROM loan_drawdown ld JOIN loan_product_catalog lp ON lp.product_code = ld.drawdown_type GROUP BY lp.product_code, lp.product_name_zh ORDER BY loan_count DESC, lp.product_name_zh;	bankreg_main
SELECT s.sector_name_zh, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY s.sector_code, s.sector_name_zh ORDER BY total_contract DESC, s.sector_name_zh;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(*) AS account_count FROM account_holder ah JOIN party p ON p.party_id = ah.party_id GROUP BY p.party_id, p.display_name HAVING COUNT(*) >= 3 ORDER BY account_count DESC, p.party_id;	bankreg_main
SELECT security_type, COUNT(*) AS agreement_count FROM credit_agreement GROUP BY security_type ORDER BY agreement_count DESC, security_type;	bankreg_main
SELECT wp.product_name, ROUND(SUM(phs.fair_value), 2) AS total_fair_value FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id GROUP BY wp.product_id, wp.product_name ORDER BY total_fair_value DESC, wp.product_name LIMIT 10;	bankreg_main
SELECT ou.org_unit_id, ou.unit_name, COUNT(*) AS relation_count FROM party_relation pr JOIN party p ON p.party_id = pr.source_party_id JOIN organization_unit ou ON ou.org_unit_id = p.home_org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY relation_count DESC, ou.org_unit_id;	bankreg_main
SELECT i.institution_name, cs.net_capital, cs.risk_weighted_assets FROM capital_snapshot cs JOIN institution i ON i.institution_id = cs.institution_id ORDER BY cs.net_capital DESC, i.institution_name;	bankreg_main
SELECT s.sector_name_zh, ROUND(SUM(lbs.principal_balance), 2) AS total_balance FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY s.sector_code, s.sector_name_zh ORDER BY total_balance DESC, s.sector_name_zh;	bankreg_main
SELECT pc.card_id, COUNT(*) AS txn_count FROM payment_card pc JOIN payment_event pe ON pe.from_account_id = pc.settlement_account_id JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE pc.card_type = 'CREDIT' AND t.name_zh = '卡消费' GROUP BY pc.card_id ORDER BY txn_count DESC, pc.card_id;	bankreg_main
SELECT i.institution_name, ROUND(SUM(abs.ledger_balance), 2) AS total_deposit FROM account_balance_snapshot abs JOIN account a ON a.account_id = abs.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE a.account_kind = 'SAVINGS' GROUP BY i.institution_id, i.institution_name ORDER BY total_deposit DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, ROUND(SUM(lbs.principal_balance), 2) AS total_balance FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name HAVING SUM(lbs.principal_balance) > 1000000000 ORDER BY total_balance DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, ROUND(AVG(d.principal_overdue_days), 2) AS avg_overdue_days FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id = d.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name HAVING AVG(d.principal_overdue_days) > 90 ORDER BY avg_overdue_days DESC, i.institution_name;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN g.is_nonperforming = 1 THEN lbs.principal_balance ELSE 0 END)              * 1.0 / SUM(lbs.principal_balance), 6) AS npl_ratio FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id JOIN risk_classification rc ON rc.loan_id = ld.loan_id JOIN classification_grade g ON g.grade_code = rc.grade_code GROUP BY i.institution_id, i.institution_name ORDER BY npl_ratio DESC, i.institution_name;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(ps.recognized_amount) * 1.0 / SUM(ps.required_amount), 6) AS coverage FROM provision_snapshot ps JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name HAVING SUM(ps.recognized_amount) * 1.0 / SUM(ps.required_amount) < 1.5 ORDER BY coverage, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS under_provisioned FROM provision_snapshot ps JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ps.recognized_amount < ps.required_amount GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) >= 100 ORDER BY under_provisioned DESC, i.institution_name;	bankreg_main
SELECT p.party_id, p.display_name, ROUND(SUM(lbs.principal_balance), 2) AS total_balance,        i.institution_name,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS exposure_ratio FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id WHERE p.party_type = 'CORPORATE' GROUP BY p.party_id, p.display_name, i.institution_id, i.institution_name, cs.net_capital ORDER BY exposure_ratio DESC, p.party_id LIMIT 10;	bankreg_main
SELECT eg.exposure_group_id, eg.group_name,        ROUND(SUM(lbs.principal_balance), 2) AS exposure_amount,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS exposure_ratio FROM exposure_group_member egm JOIN exposure_group eg ON eg.exposure_group_id = egm.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN capital_snapshot cs ON cs.institution_id = eg.institution_id GROUP BY eg.exposure_group_id, eg.group_name, cs.net_capital ORDER BY exposure_ratio DESC, eg.exposure_group_id;	bankreg_main
SELECT i.institution_name,        ROUND((SELECT SUM(lbs.principal_balance)               FROM loan_balance_snapshot lbs               JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id               JOIN credit_agreement a2 ON a2.agreement_id = ld.agreement_id               WHERE a2.institution_id = i.institution_id) * 1.0              / NULLIF((SELECT SUM(abs.ledger_balance)                        FROM account_balance_snapshot abs                        JOIN account ac ON ac.account_id = abs.account_id                        WHERE ac.institution_id = i.institution_id                          AND ac.account_kind = 'SAVINGS'), 0), 6) AS loan_to_deposit FROM institution i ORDER BY loan_to_deposit DESC, i.institution_name;	bankreg_main
WITH loan_base AS (     SELECT ld.loan_id, a.institution_id, lbs.principal_balance,            COALESCE(d.principal_overdue_days, 0) AS overdue_days,            g.is_nonperforming     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     LEFT JOIN delinquency_snapshot d ON d.loan_id = ld.loan_id     JOIN risk_classification rc ON rc.loan_id = ld.loan_id     JOIN classification_grade g ON g.grade_code = rc.grade_code ) SELECT i.institution_name,        ROUND(SUM(CASE WHEN overdue_days > 90 THEN principal_balance ELSE 0 END), 2) AS overdue90_balance,        ROUND(SUM(CASE WHEN is_nonperforming = 1 THEN principal_balance ELSE 0 END), 2) AS npl_balance,        ROUND(SUM(CASE WHEN overdue_days > 90 THEN principal_balance ELSE 0 END) * 1.0              / NULLIF(SUM(CASE WHEN is_nonperforming = 1 THEN principal_balance ELSE 0 END), 0), 6) AS deviation FROM loan_base lb JOIN institution i ON i.institution_id = lb.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY deviation DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cash_txn_count FROM payment_event pe JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id) JOIN institution i ON i.institution_id = ac.institution_id JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE pe.is_cash = 1 GROUP BY i.institution_id, i.institution_name ORDER BY cash_txn_count DESC, i.institution_name;	bankreg_main
SELECT pe.from_account_id AS account_id, ROUND(SUM(pe.amount), 2) AS cash_out FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE t.name_zh = '现金支取' AND pe.status = 'SETTLED' GROUP BY pe.from_account_id HAVING SUM(pe.amount) > 10000000 ORDER BY cash_out DESC, account_id LIMIT 20;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN pi.payment_mode = 'ENTRUSTED_PAYMENT' THEN pi.instruction_amount ELSE 0 END)              * 1.0 / SUM(pi.instruction_amount), 6) AS entrusted_ratio FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY entrusted_ratio, i.institution_name;	bankreg_main
SELECT s.sector_name_zh, COUNT(*) AS loan_count,        SUM(CASE WHEN g.is_nonperforming = 1 THEN 1 ELSE 0 END) AS npl_count,        ROUND(SUM(CASE WHEN g.is_nonperforming = 1 THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 6) AS npl_ratio FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code JOIN loan_drawdown ld ON ld.loan_id = rc.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY s.sector_code, s.sector_name_zh HAVING COUNT(*) >= 20 ORDER BY npl_ratio DESC, s.sector_name_zh;	bankreg_main
SELECT p.party_id, p.display_name, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id GROUP BY p.party_id, p.display_name ORDER BY total_contract DESC, p.party_id LIMIT 15;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(DISTINCT a.institution_id) AS inst_count FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id GROUP BY p.party_id, p.display_name HAVING COUNT(DISTINCT a.institution_id) >= 2 ORDER BY inst_count DESC, p.party_id;	bankreg_main
SELECT lp.product_name_zh, COUNT(*) AS loan_count,        ROUND(AVG(a.annual_interest_rate), 4) AS avg_rate FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN loan_product_catalog lp ON lp.product_code = ld.drawdown_type GROUP BY lp.product_code, lp.product_name_zh HAVING COUNT(*) >= 50 ORDER BY avg_rate DESC, lp.product_name_zh;	bankreg_main
SELECT i.institution_name, ROUND(SUM(wp.actual_raise_amount), 2) AS actual_total,        ROUND(SUM(wp.planned_raise_amount), 2) AS planned_total,        ROUND(SUM(wp.actual_raise_amount) * 1.0 / SUM(wp.planned_raise_amount), 6) AS completion_rate FROM wealth_product wp JOIN institution i ON i.institution_id = wp.issuer_institution_id GROUP BY i.institution_id, i.institution_name ORDER BY completion_rate, i.institution_name;	bankreg_main
SELECT risk_level, COUNT(*) AS product_count,        ROUND(AVG(management_fee_rate), 6) AS avg_fee_rate FROM wealth_product GROUP BY risk_level ORDER BY risk_level;	bankreg_main
SELECT gc.guarantor_party_id, p.display_name,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE' GROUP BY gc.guarantor_party_id, p.display_name HAVING SUM(gc.guaranteed_amount) > 500000000 ORDER BY total_guaranteed DESC, gc.guarantor_party_id;	bankreg_main
SELECT ca.collateral_type, COUNT(DISTINCT ca.collateral_id) AS collateral_count,        ROUND(SUM(cv.valuation_amount), 2) AS total_valuation FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valued_on = (SELECT MAX(cv2.valued_on) FROM collateral_valuation cv2                       WHERE cv2.collateral_id = ca.collateral_id) GROUP BY ca.collateral_type ORDER BY total_valuation DESC, ca.collateral_type;	bankreg_main
WITH loan_side AS (     SELECT a.institution_id, SUM(lbs.principal_balance) AS loan_balance     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     GROUP BY a.institution_id ), deposit_side AS (     SELECT ac.institution_id, SUM(abs.ledger_balance) AS deposit_balance     FROM account_balance_snapshot abs     JOIN account ac ON ac.account_id = abs.account_id     WHERE ac.account_kind = 'SAVINGS'     GROUP BY ac.institution_id ) SELECT i.institution_name,        ROUND(l.loan_balance * 1.0 / d.deposit_balance, 6) AS loan_to_deposit,        ROUND(l.loan_balance * 1.0 / d.deposit_balance - 0.75, 6) AS gap_over_limit FROM loan_side l JOIN deposit_side d ON d.institution_id = l.institution_id JOIN institution i ON i.institution_id = l.institution_id WHERE l.loan_balance * 1.0 / d.deposit_balance > 0.75 ORDER BY loan_to_deposit DESC, i.institution_name;	bankreg_main
SELECT channel, COUNT(*) AS txn_count, ROUND(SUM(amount), 2) AS total_amount FROM payment_event GROUP BY channel ORDER BY total_amount DESC, channel;	bankreg_main
SELECT i.institution_name, COUNT(*) AS overdue_installments,        ROUND(SUM(rs.principal_due), 2) AS principal_due FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE rs.status = 'OVERDUE' GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) >= 150 ORDER BY principal_due DESC, i.institution_name;	bankreg_main
SELECT s.sector_name_zh, COUNT(*) AS abnormal_count FROM organization_profile op JOIN industry_sector s ON s.sector_code = op.industry_code WHERE op.operating_status <> 'OPERATING' GROUP BY s.sector_code, s.sector_name_zh ORDER BY abnormal_count DESC, s.sector_name_zh;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN ma.asset_scope = 'NON_STANDARDIZED' THEN phs.fair_value ELSE 0 END), 2) AS nonstd_value,        ROUND(SUM(phs.fair_value), 2) AS total_value,        ROUND(SUM(CASE WHEN ma.asset_scope = 'NON_STANDARDIZED' THEN phs.fair_value ELSE 0 END)              * 1.0 / SUM(phs.fair_value), 6) AS nonstd_ratio FROM product_holding_snapshot phs JOIN managed_asset ma ON ma.asset_id = phs.asset_id JOIN wealth_product wp ON wp.product_id = phs.product_id JOIN institution i ON i.institution_id = wp.issuer_institution_id GROUP BY i.institution_id, i.institution_name ORDER BY nonstd_ratio DESC, i.institution_name;	bankreg_main
SELECT so.staff_id, COUNT(*) AS cash_txn_count FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id WHERE pe.is_cash = 1 GROUP BY so.staff_id ORDER BY cash_txn_count DESC, so.staff_id LIMIT 10;	bankreg_main
SELECT p.party_id, p.display_name, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE EXISTS (     SELECT 1 FROM party_relation pr     JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type     WHERE pr.source_party_id = p.party_id       AND rt.relation_name_zh <> '非关联方' ) GROUP BY p.party_id, p.display_name HAVING SUM(a.contract_amount) > 300000000 ORDER BY total_contract DESC, p.party_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS record_count,        ROUND(SUM(r.observed_value), 4) AS total_observed FROM data_security_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.exception_flag = 1 GROUP BY i.institution_id, i.institution_name ORDER BY total_observed DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS overdue_records FROM regulatory_submission_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) >= 20 ORDER BY overdue_records DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, ROUND(cs.net_capital * 1.0 / cs.risk_weighted_assets, 6) AS car FROM capital_snapshot cs JOIN institution i ON i.institution_id = cs.institution_id ORDER BY car, i.institution_name;	bankreg_main
SELECT d.loan_id, d.principal_overdue_days, g.grade_name_zh, rc.as_of_date FROM delinquency_snapshot d JOIN risk_classification rc ON rc.loan_id = d.loan_id JOIN classification_grade g ON g.grade_code = rc.grade_code WHERE d.principal_overdue_days > 90   AND g.is_nonperforming = 0 ORDER BY d.principal_overdue_days DESC, d.loan_id;	bankreg_main
SELECT ps.loan_id, ps.required_amount, ps.recognized_amount,        ROUND(ps.required_amount - ps.recognized_amount, 2) AS shortfall FROM provision_snapshot ps WHERE ps.recognized_amount < ps.required_amount * 0.8 ORDER BY shortfall DESC, ps.loan_id;	bankreg_main
SELECT i.institution_name, ROUND(SUM(lbs.principal_balance), 2) AS under_prov_balance FROM provision_snapshot ps JOIN loan_balance_snapshot lbs ON lbs.loan_id = ps.loan_id JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ps.recognized_amount < ps.required_amount GROUP BY i.institution_id, i.institution_name HAVING SUM(lbs.principal_balance) > 100000000 ORDER BY under_prov_balance DESC, i.institution_name;	bankreg_main
SELECT pi.instruction_id, pi.loan_id, p.display_name, s.sector_name_zh, pi.instruction_amount FROM payment_instruction pi JOIN organization_profile op ON op.party_id = pi.intended_payee_party_id JOIN industry_sector s ON s.sector_code = op.industry_code JOIN party p ON p.party_id = pi.intended_payee_party_id WHERE s.risk_category IN ('RESTRICTED', 'EXIT')   AND pi.status = 'EXECUTED' ORDER BY pi.instruction_amount DESC, pi.instruction_id;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN s.risk_category IN ('RESTRICTED','EXIT')                       THEN pi.instruction_amount ELSE 0 END), 2) AS restricted_amount,        ROUND(SUM(pi.instruction_amount), 2) AS total_amount,        ROUND(SUM(CASE WHEN s.risk_category IN ('RESTRICTED','EXIT')                       THEN pi.instruction_amount ELSE 0 END) * 1.0              / SUM(pi.instruction_amount), 6) AS restricted_ratio FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id LEFT JOIN organization_profile op ON op.party_id = pi.intended_payee_party_id LEFT JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY i.institution_id, i.institution_name ORDER BY restricted_ratio DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, p.display_name,        ROUND(SUM(lbs.principal_balance), 2) AS total_balance,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS concentration FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id WHERE p.party_type = 'CORPORATE' GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.10 ORDER BY concentration DESC, p.display_name;	bankreg_main
SELECT i.institution_name, eg.group_name,        ROUND(SUM(lbs.principal_balance), 2) AS exposure_amount,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS concentration FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN institution i ON i.institution_id = eg.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id GROUP BY i.institution_id, i.institution_name, eg.exposure_group_id, eg.group_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.15 ORDER BY concentration DESC, eg.group_name;	bankreg_main
SELECT wp.product_id, wp.product_name, ma.asset_id, ma.maturity_on, wp.actual_termination_on FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id JOIN managed_asset ma ON ma.asset_id = phs.asset_id WHERE ma.maturity_on > wp.actual_termination_on ORDER BY ma.maturity_on DESC, wp.product_id, ma.asset_id;	bankreg_main
SELECT wp.product_id, wp.product_name, COUNT(*) AS nested_holdings FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id WHERE phs.lookthrough_depth >= 2 GROUP BY wp.product_id, wp.product_name ORDER BY nested_holdings DESC, wp.product_id;	bankreg_main
SELECT i.institution_name, ROUND(SUM(phs.fair_value), 2) AS spv_value FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id JOIN institution i ON i.institution_id = wp.issuer_institution_id WHERE phs.investment_path IN ('SPV', 'NESTED_SPV') GROUP BY i.institution_id, i.institution_name ORDER BY spv_value DESC, i.institution_name;	bankreg_main
SELECT pe.payment_id, pe.business_date, so.staff_id, ah.account_id, pe.amount FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id JOIN staff_member sm ON sm.staff_id = so.staff_id JOIN account_holder ah ON ah.account_id IN (pe.from_account_id, pe.to_account_id) WHERE pe.is_cash = 1   AND ah.party_id = sm.person_party_id ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT so.staff_id, COUNT(*) AS txn_count, ROUND(SUM(pe.amount), 2) AS total_amount FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id WHERE pe.is_cash = 1 GROUP BY so.staff_id HAVING SUM(pe.amount) > 50000000 ORDER BY total_amount DESC, so.staff_id;	bankreg_main
SELECT sa.security_id, sa.secured_amount, cl.collateral_id, cv.valuation_amount,        ROUND(sa.secured_amount - cv.valuation_amount, 2) AS shortfall FROM security_agreement sa JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN collateral_valuation cv ON cv.collateral_id = cl.collateral_id WHERE cv.valued_on = (SELECT MAX(cv2.valued_on) FROM collateral_valuation cv2                       WHERE cv2.collateral_id = cl.collateral_id)   AND sa.secured_amount > cv.valuation_amount ORDER BY shortfall DESC, sa.security_id;	bankreg_main
SELECT p.party_id, p.display_name, g.guarantee_count, b.agreement_count FROM party p JOIN (SELECT guarantor_party_id AS pid, COUNT(*) AS guarantee_count       FROM guarantor_commitment GROUP BY guarantor_party_id) g ON g.pid = p.party_id JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count       FROM credit_agreement GROUP BY borrower_party_id) b ON b.pid = p.party_id ORDER BY g.guarantee_count DESC, p.party_id;	bankreg_main
SELECT pe.payment_id, pe.business_date, t.name_zh, pe.amount, ou.unit_name FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type JOIN organization_unit ou ON ou.org_unit_id = pe.origin_org_unit_id WHERE pe.is_cash = 1 AND pe.amount > 5000000 AND pe.status = 'SETTLED' ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT product_id, product_name, risk_level, target_investor_type FROM wealth_product WHERE risk_level IN ('R4', 'R5') AND target_investor_type = 'GENERAL' ORDER BY product_id;	bankreg_main
SELECT a.agreement_id, p.display_name, s1.sector_name_zh AS borrower_sector,        s2.sector_name_zh AS target_sector, a.contract_amount FROM credit_agreement a JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s1 ON s1.sector_code = op.industry_code JOIN industry_sector s2 ON s2.sector_code = a.target_industry_code JOIN party p ON p.party_id = a.borrower_party_id WHERE a.target_industry_code <> op.industry_code ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT a.agreement_id, a.maturity_on, ld.loan_id, ld.disbursed_amount FROM credit_agreement a JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id WHERE a.status = 'MATURED' AND ld.status = 'ACTIVE' ORDER BY a.maturity_on, a.agreement_id, ld.loan_id;	bankreg_main
SELECT ac.account_id, pe.payment_id, pe.business_date, pe.amount FROM payment_event pe JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id) WHERE ac.status = 'DORMANT' AND pe.amount > 1000000 ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT p.party_id, p.display_name, op.operating_status, COUNT(*) AS active_loans FROM organization_profile op JOIN party p ON p.party_id = op.party_id JOIN credit_agreement a ON a.borrower_party_id = op.party_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id WHERE op.operating_status <> 'OPERATING' AND ld.status = 'ACTIVE' GROUP BY p.party_id, p.display_name, op.operating_status ORDER BY active_loans DESC, p.party_id;	bankreg_main
SELECT pe.payment_id, pe.business_date, pe.amount,        ah1.party_id AS payer_party_id, ah2.party_id AS payee_party_id FROM payment_event pe JOIN account_holder ah1 ON ah1.account_id = pe.from_account_id AND ah1.holder_role = 'PRIMARY' JOIN account_holder ah2 ON ah2.account_id = pe.to_account_id AND ah2.holder_role = 'PRIMARY' JOIN party_relation pr ON pr.source_party_id = ah1.party_id AND pr.target_party_id = ah2.party_id WHERE pe.status = 'SETTLED' AND pr.relation_type <> 'NON_RELATED' ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT p.party_id, p.display_name, i.institution_name,        COUNT(DISTINCT d.loan_id) AS overdue_loans,        COUNT(DISTINCT ld2.loan_id) AS active_loans FROM delinquency_snapshot d JOIN loan_drawdown ld1 ON ld1.loan_id = d.loan_id JOIN credit_agreement a1 ON a1.agreement_id = ld1.agreement_id JOIN institution i ON i.institution_id = a1.institution_id JOIN party p ON p.party_id = a1.borrower_party_id JOIN credit_agreement a2 ON a2.borrower_party_id = a1.borrower_party_id                         AND a2.institution_id = a1.institution_id JOIN loan_drawdown ld2 ON ld2.agreement_id = a2.agreement_id                       AND ld2.loan_id <> ld1.loan_id WHERE d.principal_overdue_days > 90   AND ld2.status = 'ACTIVE' GROUP BY p.party_id, p.display_name, i.institution_id, i.institution_name ORDER BY overdue_loans DESC, p.party_id;	bankreg_main
SELECT a.agreement_id, p.display_name, COUNT(*) AS loan_count FROM credit_agreement a JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN party p ON p.party_id = a.borrower_party_id GROUP BY a.agreement_id, p.display_name HAVING COUNT(*) >= 3 ORDER BY loan_count DESC, a.agreement_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS large_cash_count,        ROUND(SUM(pe.amount), 2) AS total_amount FROM payment_event pe JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id) JOIN institution i ON i.institution_id = ac.institution_id WHERE pe.is_cash = 1 AND pe.amount > 5000000 GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) >= 50 ORDER BY total_amount DESC, i.institution_name;	bankreg_main
SELECT pi.loan_id, p1.display_name AS borrower, p2.display_name AS payee,        s.sector_name_zh, pi.instruction_amount FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p1 ON p1.party_id = a.borrower_party_id JOIN party p2 ON p2.party_id = pi.intended_payee_party_id JOIN organization_profile op ON op.party_id = pi.intended_payee_party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE pi.payment_mode = 'ENTRUSTED_PAYMENT'   AND op.industry_code <> a.target_industry_code   AND s.risk_category IN ('RESTRICTED', 'EXIT') ORDER BY pi.instruction_amount DESC, pi.loan_id;	bankreg_main
SELECT so.staff_id, COUNT(*) AS restricted_txn_count FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id JOIN account_holder ah ON ah.account_id = pe.to_account_id AND ah.holder_role = 'PRIMARY' JOIN organization_profile op ON op.party_id = ah.party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE s.risk_category IN ('RESTRICTED', 'EXIT') GROUP BY so.staff_id ORDER BY restricted_txn_count DESC, so.staff_id LIMIT 10;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN EXISTS (            SELECT 1 FROM party_relation pr            JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type            WHERE pr.source_party_id = a.borrower_party_id              AND rt.relation_name_zh <> '非关联方'        ) THEN a.contract_amount ELSE 0 END), 2) AS related_amount,        ROUND(SUM(a.contract_amount), 2) AS total_amount,        ROUND(SUM(CASE WHEN EXISTS (            SELECT 1 FROM party_relation pr            JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type            WHERE pr.source_party_id = a.borrower_party_id              AND rt.relation_name_zh <> '非关联方'        ) THEN a.contract_amount ELSE 0 END) * 1.0 / SUM(a.contract_amount), 6) AS related_ratio FROM credit_agreement a JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY related_ratio DESC, i.institution_name;	bankreg_main
SELECT ca.collateral_id, ca.asset_label, COUNT(*) AS link_count,        ROUND(SUM(sa.secured_amount), 2) AS total_secured FROM collateral_asset ca JOIN collateral_link cl ON cl.collateral_id = ca.collateral_id JOIN security_agreement sa ON sa.security_id = cl.security_id WHERE cl.status = 'ACTIVE' GROUP BY ca.collateral_id, ca.asset_label HAVING COUNT(*) >= 2 ORDER BY link_count DESC, ca.collateral_id;	bankreg_main
SELECT i.institution_name, ROUND(SUM(r.observed_value), 4) AS total_observed FROM lending_control_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_id, i.institution_name ORDER BY total_observed DESC, i.institution_name LIMIT 5;	bankreg_main
SELECT product_id, product_name, scheduled_maturity_on, actual_termination_on,        CAST(julianday(actual_termination_on) - julianday(scheduled_maturity_on) AS INTEGER) AS delay_days FROM wealth_product WHERE julianday(actual_termination_on) - julianday(scheduled_maturity_on) > 30 ORDER BY delay_days DESC, product_id;	bankreg_main
SELECT r.record_id, i.institution_name, r.event_date, r.deadline_date,        CAST(julianday('2026-06-30') - julianday(r.deadline_date) AS INTEGER) AS overdue_days FROM customer_due_diligence_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL ORDER BY overdue_days DESC, r.record_id LIMIT 20;	bankreg_main
SELECT i.institution_name, ROUND(SUM(ld.disbursed_amount), 2) AS total_disbursed FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ld.disbursed_on BETWEEN '2026-01-01' AND '2026-06-30' GROUP BY i.institution_id, i.institution_name HAVING SUM(ld.disbursed_amount) > 5000000000 ORDER BY total_disbursed DESC, i.institution_name;	bankreg_main
SELECT sa.security_id, cl.collateral_id, ca.status AS collateral_status, sa.status AS security_status FROM security_agreement sa JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN collateral_asset ca ON ca.collateral_id = cl.collateral_id WHERE ca.status = 'RELEASED' AND sa.status = 'ACTIVE' ORDER BY sa.security_id;	bankreg_main
SELECT i.institution_name, s.sector_name_zh, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN institution i ON i.institution_id = a.institution_id JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE s.risk_category IN ('RESTRICTED', 'EXIT') GROUP BY i.institution_id, i.institution_name, s.sector_code, s.sector_name_zh ORDER BY total_contract DESC, i.institution_name, s.sector_name_zh;	bankreg_main
SELECT ld.loan_id, a.agreement_id, sa.security_id, sa.secured_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN secured_obligation so ON so.agreement_id = a.agreement_id JOIN security_agreement sa ON sa.security_id = so.security_id WHERE ld.status = 'WRITTEN_OFF' AND sa.status = 'ACTIVE' ORDER BY sa.secured_amount DESC, ld.loan_id;	bankreg_main
WITH ranked AS (     SELECT i.institution_name, lbs.loan_id, lbs.principal_balance,            ROW_NUMBER() OVER (PARTITION BY i.institution_id                               ORDER BY lbs.principal_balance DESC, lbs.loan_id) AS rn     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id ) SELECT institution_name, loan_id, principal_balance, rn FROM ranked WHERE rn = 1 ORDER BY institution_name;	bankreg_main
WITH ranked AS (     SELECT s.sector_name_zh, lbs.loan_id, lbs.principal_balance,            RANK() OVER (PARTITION BY s.sector_code ORDER BY lbs.principal_balance DESC) AS rnk     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN organization_profile op ON op.party_id = a.borrower_party_id     JOIN industry_sector s ON s.sector_code = op.industry_code ) SELECT sector_name_zh, loan_id, principal_balance, rnk FROM ranked WHERE rnk <= 3 ORDER BY sector_name_zh, rnk, loan_id;	bankreg_main
WITH base AS (     SELECT i.institution_name, i.institution_id, lbs.loan_id,            lbs.principal_balance,            SUM(lbs.principal_balance) OVER (PARTITION BY i.institution_id) AS inst_total     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id ) SELECT institution_name, loan_id, principal_balance,        ROUND(principal_balance * 1.0 / inst_total, 6) AS share FROM base WHERE principal_balance * 1.0 / inst_total > 0.004 ORDER BY share DESC, loan_id;	bankreg_main
WITH daily AS (     SELECT pe.business_date, SUM(pe.amount) AS day_amount     FROM payment_event pe     JOIN payment_type_catalog t ON t.payment_type = pe.payment_type     WHERE t.name_zh = '现金支取' AND pe.status = 'SETTLED'     GROUP BY pe.business_date ), running AS (     SELECT business_date, day_amount,            SUM(day_amount) OVER (ORDER BY business_date) AS cumulative     FROM daily ) SELECT business_date, ROUND(day_amount, 2) AS day_amount, ROUND(cumulative, 2) AS cumulative FROM running WHERE business_date <= (SELECT MIN(business_date) FROM running WHERE cumulative > 500000000) ORDER BY business_date;	bankreg_main
WITH daily AS (     SELECT business_date, COUNT(*) AS txn_count     FROM payment_event     GROUP BY business_date ) SELECT business_date, txn_count,        txn_count - LAG(txn_count) OVER (ORDER BY business_date) AS delta FROM daily ORDER BY business_date;	bankreg_main
SELECT i.institution_name, lbs.loan_id, lbs.principal_balance,        ROUND((SELECT AVG(lbs2.principal_balance)               FROM loan_balance_snapshot lbs2               JOIN loan_drawdown ld2 ON ld2.loan_id = lbs2.loan_id               JOIN credit_agreement a2 ON a2.agreement_id = ld2.agreement_id               WHERE a2.institution_id = a.institution_id), 2) AS inst_avg,        ROUND(lbs.principal_balance - (SELECT AVG(lbs3.principal_balance)               FROM loan_balance_snapshot lbs3               JOIN loan_drawdown ld3 ON ld3.loan_id = lbs3.loan_id               JOIN credit_agreement a3 ON a3.agreement_id = ld3.agreement_id               WHERE a3.institution_id = a.institution_id), 2) AS excess FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE lbs.principal_balance > (SELECT AVG(lbs4.principal_balance)                               FROM loan_balance_snapshot lbs4                               JOIN loan_drawdown ld4 ON ld4.loan_id = lbs4.loan_id                               JOIN credit_agreement a4 ON a4.agreement_id = ld4.agreement_id                               WHERE a4.institution_id = a.institution_id) ORDER BY excess DESC, lbs.loan_id;	bankreg_main
SELECT a.agreement_id, p.display_name, a.contract_amount FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE EXISTS (SELECT 1 FROM secured_obligation so               JOIN security_agreement sa ON sa.security_id = so.security_id               JOIN collateral_link cl ON cl.security_id = sa.security_id               WHERE so.agreement_id = a.agreement_id)   AND EXISTS (SELECT 1 FROM secured_obligation so2               JOIN security_agreement sa2 ON sa2.security_id = so2.security_id               JOIN guarantor_commitment gc ON gc.security_id = sa2.security_id               WHERE so2.agreement_id = a.agreement_id) ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT sa.security_id, sa.secured_amount,        (SELECT COUNT(*) FROM guarantor_commitment gc WHERE gc.security_id = sa.security_id) AS guarantor_count FROM security_agreement sa WHERE NOT EXISTS (SELECT 1 FROM collateral_link cl WHERE cl.security_id = sa.security_id)   AND EXISTS (SELECT 1 FROM guarantor_commitment gc WHERE gc.security_id = sa.security_id) ORDER BY sa.secured_amount DESC, sa.security_id;	bankreg_main
SELECT i.institution_name, '信贷控制' AS source, COUNT(*) AS overdue_count FROM lending_control_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_id, i.institution_name UNION ALL SELECT i.institution_name, '治理控制' AS source, COUNT(*) AS overdue_count FROM governance_control_record_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_id, i.institution_name ORDER BY institution_name, source;	bankreg_main
SELECT DISTINCT p.party_id, p.display_name FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE NOT EXISTS (SELECT 1 FROM loan_drawdown ld2                   JOIN credit_agreement a2 ON a2.agreement_id = ld2.agreement_id                   WHERE a2.borrower_party_id = a.borrower_party_id) ORDER BY p.party_id;	bankreg_main
SELECT ac.account_id FROM account ac JOIN payment_event pe ON pe.from_account_id = ac.account_id JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE t.name_zh = '现金支取' INTERSECT SELECT ac.account_id FROM account ac JOIN payment_event pe ON pe.from_account_id = ac.account_id JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE t.name_zh = '转账' ORDER BY account_id;	bankreg_main
WITH per_customer AS (     SELECT p.party_id, p.display_name, SUM(lbs.principal_balance) AS total_balance     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN party p ON p.party_id = a.borrower_party_id     WHERE p.party_type = 'CORPORATE'     GROUP BY p.party_id, p.display_name ), threshold AS (     SELECT total_balance AS cut     FROM per_customer     ORDER BY total_balance DESC     LIMIT 1 OFFSET (SELECT CAST(COUNT(*) * 0.1 AS INTEGER) FROM per_customer) ) SELECT party_id, display_name, ROUND(total_balance, 2) AS total_balance FROM per_customer, threshold WHERE total_balance >= cut ORDER BY total_balance DESC, party_id;	bankreg_main
SELECT CASE          WHEN d.principal_overdue_days IS NULL THEN '未逾期'          WHEN d.principal_overdue_days <= 30 THEN '1-30天'          WHEN d.principal_overdue_days <= 90 THEN '31-90天'          WHEN d.principal_overdue_days <= 180 THEN '91-180天'          WHEN d.principal_overdue_days <= 360 THEN '181-360天'          ELSE '360天以上' END AS bucket,        COUNT(*) AS loan_count FROM loan_drawdown ld LEFT JOIN delinquency_snapshot d ON d.loan_id = ld.loan_id GROUP BY bucket ORDER BY CASE bucket          WHEN '未逾期' THEN 0 WHEN '1-30天' THEN 1 WHEN '31-90天' THEN 2          WHEN '91-180天' THEN 3 WHEN '181-360天' THEN 4 ELSE 5 END;	bankreg_main
WITH inst_npl AS (     SELECT i.institution_name,            SUM(CASE WHEN g.is_nonperforming = 1 THEN lbs.principal_balance ELSE 0 END) * 1.0            / SUM(lbs.principal_balance) AS npl_ratio     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN risk_classification rc ON rc.loan_id = ld.loan_id     JOIN classification_grade g ON g.grade_code = rc.grade_code     GROUP BY i.institution_id, i.institution_name ), med AS (     SELECT AVG(npl_ratio) AS median_ratio FROM (         SELECT npl_ratio FROM inst_npl ORDER BY npl_ratio         LIMIT 2 - (SELECT COUNT(*) FROM inst_npl) % 2         OFFSET (SELECT (COUNT(*) - 1) / 2 FROM inst_npl)) ) SELECT institution_name, ROUND(npl_ratio, 6) AS npl_ratio FROM inst_npl, med WHERE npl_ratio > median_ratio ORDER BY npl_ratio DESC, institution_name;	bankreg_main
SELECT cv.collateral_id, cv.valued_on, COUNT(*) AS duplicate_count FROM collateral_valuation cv GROUP BY cv.collateral_id, cv.valued_on HAVING COUNT(*) > 1 ORDER BY cv.collateral_id;	bankreg_main
SELECT DISTINCT sm.staff_id, p.display_name, ou.unit_name FROM staff_member sm JOIN party p ON p.party_id = sm.person_party_id JOIN organization_unit ou ON ou.org_unit_id = sm.home_org_unit_id JOIN credit_agreement a ON a.managing_org_unit_id = sm.home_org_unit_id WHERE a.borrower_party_id = sm.person_party_id ORDER BY sm.staff_id;	bankreg_main
WITH inst_coll AS (     SELECT i.institution_name, SUM(cv.valuation_amount) AS total_valuation     FROM collateral_valuation cv     JOIN collateral_asset ca ON ca.collateral_id = cv.collateral_id     JOIN collateral_link cl ON cl.collateral_id = ca.collateral_id     JOIN security_agreement sa ON sa.security_id = cl.security_id     JOIN institution i ON i.institution_id = sa.institution_id     WHERE cv.valued_on = (SELECT MAX(cv2.valued_on) FROM collateral_valuation cv2                           WHERE cv2.collateral_id = ca.collateral_id)     GROUP BY i.institution_id, i.institution_name ) SELECT institution_name, ROUND(total_valuation, 2) AS total_valuation,        RANK() OVER (ORDER BY total_valuation DESC) AS rnk FROM inst_coll ORDER BY total_valuation DESC LIMIT 3;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(*) AS loan_count,        ROUND(SUM(lbs.principal_balance), 2) AS total_balance,        ROUND(AVG(lbs.principal_balance), 2) AS avg_balance FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id WHERE p.party_type = 'CORPORATE' GROUP BY p.party_id, p.display_name ORDER BY avg_balance DESC, p.party_id LIMIT 5;	bankreg_main
WITH all_records AS (     SELECT institution_id FROM lending_control_event_v3     UNION ALL     SELECT institution_id FROM governance_control_record_v3     UNION ALL     SELECT institution_id FROM regulatory_submission_event_v3 ) SELECT i.institution_name, COUNT(*) AS record_count FROM all_records ar JOIN institution i ON i.institution_id = ar.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY record_count DESC, i.institution_name;	bankreg_main
SELECT pe.from_account_id AS account_id, pe.payment_id, pe.amount,        ROUND((SELECT AVG(pe2.amount) FROM payment_event pe2               WHERE pe2.from_account_id = pe.from_account_id), 2) AS account_avg FROM payment_event pe WHERE pe.amount > 10 * (SELECT AVG(pe3.amount) FROM payment_event pe3                         WHERE pe3.from_account_id = pe.from_account_id) ORDER BY pe.amount DESC, pe.payment_id LIMIT 20;	bankreg_main
WITH cash AS (     SELECT i.institution_id, i.institution_name, COUNT(*) AS cash_count,            AVG(pe.amount) AS avg_amount     FROM payment_event pe     JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id)     JOIN institution i ON i.institution_id = ac.institution_id     WHERE pe.is_cash = 1     GROUP BY i.institution_id, i.institution_name ), top3 AS (     SELECT institution_id FROM cash ORDER BY cash_count DESC, institution_id LIMIT 3 ) SELECT c.institution_name, c.cash_count, ROUND(c.avg_amount, 2) AS avg_amount FROM cash c JOIN top3 t ON t.institution_id = c.institution_id WHERE c.avg_amount > 11500000 ORDER BY c.avg_amount DESC, c.institution_name;	bankreg_main
SELECT ou.unit_name, COUNT(DISTINCT sm.staff_id) AS staff_count,        COUNT(*) AS txn_count FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id JOIN staff_member sm ON sm.staff_id = so.staff_id JOIN organization_unit ou ON ou.org_unit_id = sm.home_org_unit_id WHERE pe.is_cash = 1 GROUP BY ou.org_unit_id, ou.unit_name ORDER BY txn_count DESC, ou.unit_name LIMIT 10;	bankreg_main
SELECT p.customer_segment, COUNT(*) AS customer_count,        ROUND(AVG(pp.annual_income), 2) AS avg_income,        ROUND(SUM(CASE WHEN pp.annual_income > 1000000 THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 6) AS high_income_ratio FROM party p JOIN person_profile pp ON pp.party_id = p.party_id WHERE p.party_type = 'INDIVIDUAL' GROUP BY p.customer_segment ORDER BY p.customer_segment;	bankreg_main
WITH combo AS (     SELECT i.institution_name, lp.product_name_zh,            SUM(lbs.principal_balance) AS total_balance     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN loan_product_catalog lp ON lp.product_code = ld.drawdown_type     GROUP BY i.institution_id, i.institution_name, lp.product_code, lp.product_name_zh ), ranked AS (     SELECT institution_name, product_name_zh, total_balance,            SUM(total_balance) OVER (PARTITION BY institution_name) AS inst_total,            ROW_NUMBER() OVER (PARTITION BY institution_name ORDER BY total_balance DESC) AS rn     FROM combo ) SELECT institution_name, product_name_zh, ROUND(total_balance, 2) AS total_balance,        ROUND(total_balance * 1.0 / inst_total, 6) AS share FROM ranked WHERE rn = 1 ORDER BY share DESC, institution_name;	bankreg_main
WITH txn AS (     SELECT i.institution_id, i.institution_name, pe.amount,            CASE WHEN EXISTS (                SELECT 1 FROM account_holder ah1                JOIN account_holder ah2 ON ah2.account_id = pe.to_account_id AND ah2.holder_role = 'PRIMARY'                JOIN party_relation pr ON pr.source_party_id = ah1.party_id AND pr.target_party_id = ah2.party_id                WHERE ah1.account_id = pe.from_account_id AND pr.relation_type <> 'NON_RELATED'            ) THEN 1 ELSE 0 END AS is_related     FROM payment_event pe     JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id)     JOIN institution i ON i.institution_id = ac.institution_id ) SELECT institution_name,        ROUND(SUM(CASE WHEN is_related = 1 THEN amount ELSE 0 END), 2) AS related_amount,        ROUND(SUM(amount), 2) AS total_amount,        ROUND(SUM(CASE WHEN is_related = 1 THEN amount ELSE 0 END) * 1.0 / SUM(amount), 8) AS related_ratio FROM txn GROUP BY institution_id, institution_name ORDER BY related_ratio DESC, institution_name;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT a.borrower_party_id) AS borrower_count,        COUNT(*) AS loan_count,        ROUND(SUM(lbs.principal_balance) / COUNT(DISTINCT a.borrower_party_id), 2) AS avg_per_borrower FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY avg_per_borrower DESC, i.institution_name;	bankreg_main
SELECT wp.product_id, wp.product_name, COUNT(*) AS asset_count,        ROUND(SUM(CASE WHEN ma.asset_scope = 'NON_STANDARDIZED' THEN phs.fair_value ELSE 0 END)              * 1.0 / SUM(phs.fair_value), 6) AS nonstd_ratio FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id JOIN managed_asset ma ON ma.asset_id = phs.asset_id GROUP BY wp.product_id, wp.product_name HAVING COUNT(*) >= 3    AND SUM(CASE WHEN ma.asset_scope = 'NON_STANDARDIZED' THEN phs.fair_value ELSE 0 END)        * 1.0 / SUM(phs.fair_value) > 0.3 ORDER BY nonstd_ratio DESC, wp.product_id;	bankreg_main
SELECT substr(ld.disbursed_on, 1, 7) AS month, i.institution_name,        COUNT(*) AS loan_count, ROUND(SUM(ld.disbursed_amount), 2) AS total_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ld.disbursed_on BETWEEN '2026-01-01' AND '2026-06-30' GROUP BY month, i.institution_id, i.institution_name ORDER BY month, total_amount DESC, i.institution_name;	bankreg_main
SELECT p.party_id, p.display_name, c.card_count, td.deposit_count FROM party p JOIN (SELECT holder_party_id AS pid, COUNT(*) AS card_count       FROM payment_card       WHERE card_type = 'CREDIT'       GROUP BY holder_party_id) c ON c.pid = p.party_id JOIN (SELECT ah.party_id AS pid, COUNT(DISTINCT t.account_id) AS deposit_count       FROM term_deposit t       JOIN account_holder ah ON ah.account_id = t.account_id       GROUP BY ah.party_id) td ON td.pid = p.party_id ORDER BY td.deposit_count DESC, p.party_id;	bankreg_main
WITH inst_txn AS (     SELECT i.institution_id, i.institution_name,            SUM(CASE WHEN t.name_zh = '现金支取' THEN pe.amount ELSE 0 END) AS cash_out,            SUM(pe.amount) AS total_amount     FROM payment_event pe     JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id)     JOIN institution i ON i.institution_id = ac.institution_id     JOIN payment_type_catalog t ON t.payment_type = pe.payment_type     GROUP BY i.institution_id, i.institution_name ) SELECT institution_name, ROUND(cash_out, 2) AS cash_out_amount,        ROUND(total_amount, 2) AS total_amount,        ROUND(cash_out * 1.0 / total_amount, 6) AS cash_ratio,        RANK() OVER (ORDER BY cash_out * 1.0 / total_amount DESC) AS rnk FROM inst_txn ORDER BY rnk, institution_name;	bankreg_main
SELECT party_id, display_name FROM party WHERE display_name LIKE '%科技%' ORDER BY party_id;	bankreg_main
SELECT record_id, event_date, deadline_date FROM customer_due_diligence_event_v3 WHERE completion_date IS NULL ORDER BY deadline_date, record_id;	bankreg_main
SELECT lbs.loan_id, lbs.principal_balance,        COALESCE(d.principal_overdue_days, 0) AS overdue_days FROM loan_balance_snapshot lbs LEFT JOIN delinquency_snapshot d ON d.loan_id = lbs.loan_id WHERE lbs.principal_balance <> 0 ORDER BY overdue_days DESC, lbs.loan_id LIMIT 30;	bankreg_main
SELECT i.institution_name,        ROUND(AVG(julianday('2026-06-30') - julianday(ld.disbursed_on)), 2) AS avg_age_days FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY avg_age_days DESC, i.institution_name;	bankreg_main
SELECT loan_id, disbursed_on, current_maturity_on,        CAST(julianday(current_maturity_on) - julianday('2026-06-30') AS INTEGER) AS days_left FROM loan_drawdown WHERE status = 'ACTIVE'   AND julianday(current_maturity_on) - julianday('2026-06-30') BETWEEN 0 AND 90 ORDER BY days_left, loan_id;	bankreg_main
SELECT loan_id, principal_balance, quartile FROM (     SELECT loan_id, principal_balance,            NTILE(4) OVER (ORDER BY principal_balance DESC) AS quartile     FROM loan_balance_snapshot ) ORDER BY quartile, principal_balance DESC, loan_id LIMIT 40;	bankreg_main
WITH sector_balance AS (     SELECT s.sector_name_zh, SUM(lbs.principal_balance) AS total_balance     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN organization_profile op ON op.party_id = a.borrower_party_id     JOIN industry_sector s ON s.sector_code = op.industry_code     GROUP BY s.sector_code, s.sector_name_zh ), cumulative AS (     SELECT sector_name_zh, total_balance,            SUM(total_balance) OVER (ORDER BY total_balance DESC, sector_name_zh                                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)            * 1.0 / SUM(total_balance) OVER () AS cum_share     FROM sector_balance ) SELECT sector_name_zh, ROUND(total_balance, 2) AS total_balance,        ROUND(cum_share, 6) AS cumulative_share FROM cumulative WHERE cum_share <= 0.8 ORDER BY cumulative_share;	bankreg_main
SELECT p.party_id, p.display_name, i.institution_name, COUNT(*) AS active_loans FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id WHERE ld.status = 'ACTIVE' GROUP BY p.party_id, p.display_name, i.institution_id, i.institution_name HAVING COUNT(*) >= 2 ORDER BY active_loans DESC, p.party_id;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN p.party_type = 'CORPORATE' THEN lbs.principal_balance ELSE 0 END), 2) AS corp_loan,        ROUND(SUM(CASE WHEN p.party_type = 'INDIVIDUAL' THEN lbs.principal_balance ELSE 0 END), 2) AS retail_loan,        (SELECT ROUND(SUM(abs.ledger_balance), 2)         FROM account_balance_snapshot abs         JOIN account ac ON ac.account_id = abs.account_id         WHERE ac.institution_id = i.institution_id AND ac.account_kind = 'SAVINGS') AS savings FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY corp_loan DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, lp.product_name_zh, COUNT(*) AS loan_count,        ROUND(SUM(ld.disbursed_amount), 2) AS total_disbursed FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id JOIN loan_product_catalog lp ON lp.product_code = ld.drawdown_type GROUP BY i.institution_id, i.institution_name, lp.product_code, lp.product_name_zh ORDER BY i.institution_name, total_disbursed DESC, lp.product_name_zh;	bankreg_main
SELECT p.party_id, p.display_name, s.sector_name_zh, s.risk_category FROM party p JOIN organization_profile op ON op.party_id = p.party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE s.risk_category IN ('RESTRICTED', 'EXIT') ORDER BY s.risk_category, p.party_id;	bankreg_main
SELECT ac.account_id, ac.account_kind, i.institution_name FROM account ac JOIN institution i ON i.institution_id = ac.institution_id WHERE NOT EXISTS (SELECT 1 FROM payment_event pe                   WHERE pe.from_account_id = ac.account_id OR pe.to_account_id = ac.account_id) ORDER BY ac.account_id LIMIT 30;	bankreg_main
SELECT substr(pe.business_date, 1, 7) AS month,        SUM(CASE WHEN t.name_zh IN ('现金存入', '现金支取') THEN 1 ELSE 0 END) AS cash_count,        SUM(CASE WHEN t.name_zh = '转账' THEN 1 ELSE 0 END) AS transfer_count FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type GROUP BY month ORDER BY month;	bankreg_main
SELECT sa.security_id, sa.secured_amount, cl.collateral_id, cv.valuation_amount FROM security_agreement sa JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN collateral_valuation cv ON cv.collateral_id = cl.collateral_id WHERE cv.valued_on = (SELECT MAX(cv2.valued_on) FROM collateral_valuation cv2                       WHERE cv2.collateral_id = cl.collateral_id)   AND cv.valuation_amount > sa.secured_amount * 2 ORDER BY cv.valuation_amount - sa.secured_amount DESC, sa.security_id;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(DISTINCT ac.institution_id) AS inst_count FROM account_holder ah JOIN account ac ON ac.account_id = ah.account_id JOIN party p ON p.party_id = ah.party_id WHERE p.party_type = 'INDIVIDUAL' GROUP BY p.party_id, p.display_name HAVING COUNT(DISTINCT ac.institution_id) >= 2 ORDER BY inst_count DESC, p.party_id;	bankreg_main
SELECT pe.from_account_id AS account_id, pe.business_date, COUNT(*) AS txn_count FROM payment_event pe WHERE pe.from_account_id IS NOT NULL GROUP BY pe.from_account_id, pe.business_date HAVING COUNT(*) >= 3 ORDER BY txn_count DESC, account_id, pe.business_date LIMIT 20;	bankreg_main
WITH monthly AS (     SELECT i.institution_name, substr(pe.business_date, 1, 7) AS month,            SUM(pe.amount) AS month_amount,            ROW_NUMBER() OVER (PARTITION BY i.institution_id                               ORDER BY SUM(pe.amount) DESC, substr(pe.business_date, 1, 7)) AS rn     FROM payment_event pe     JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id)     JOIN institution i ON i.institution_id = ac.institution_id     JOIN payment_type_catalog t ON t.payment_type = pe.payment_type     WHERE t.name_zh = '现金支取'     GROUP BY i.institution_id, i.institution_name, month ) SELECT institution_name, month, ROUND(month_amount, 2) AS month_amount FROM monthly WHERE rn = 1 ORDER BY month_amount DESC, institution_name;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT egm.party_id) AS member_count,        ROUND(SUM(lbs.principal_balance), 2) AS total_balance FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN institution i ON i.institution_id = eg.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY total_balance DESC, i.institution_name;	bankreg_main
SELECT ld.loan_id, ld.disbursed_amount, ROUND(SUM(pi.instruction_amount), 2) AS instructed,        ROUND(ABS(SUM(pi.instruction_amount) - ld.disbursed_amount) * 1.0 / ld.disbursed_amount, 6) AS diff_ratio FROM loan_drawdown ld JOIN payment_instruction pi ON pi.loan_id = ld.loan_id GROUP BY ld.loan_id, ld.disbursed_amount HAVING ABS(SUM(pi.instruction_amount) - ld.disbursed_amount) * 1.0 / ld.disbursed_amount > 0.05 ORDER BY diff_ratio DESC, ld.loan_id LIMIT 20;	bankreg_main
SELECT i.institution_name, COUNT(*) AS product_count,        ROUND(SUM(wp.actual_raise_amount), 2) AS total_raised FROM wealth_product wp JOIN institution i ON i.institution_id = wp.issuer_institution_id WHERE wp.target_investor_type = 'GENERAL' GROUP BY i.institution_id, i.institution_name ORDER BY total_raised DESC, i.institution_name;	bankreg_main
SELECT p.party_id, p.display_name, i.institution_name,        SUM(CASE WHEN ld.payment_mode = 'ENTRUSTED_PAYMENT' THEN 1 ELSE 0 END) AS entrusted,        SUM(CASE WHEN ld.payment_mode = 'SELF_PAYMENT' THEN 1 ELSE 0 END) AS self_pay FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY p.party_id, p.display_name, i.institution_id, i.institution_name HAVING SUM(CASE WHEN ld.payment_mode = 'ENTRUSTED_PAYMENT' THEN 1 ELSE 0 END) > 0    AND SUM(CASE WHEN ld.payment_mode = 'SELF_PAYMENT' THEN 1 ELSE 0 END) > 0 ORDER BY p.party_id;	bankreg_main
SELECT gc.guarantor_party_id, p.display_name, COUNT(DISTINCT gc.security_id) AS security_count,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id GROUP BY gc.guarantor_party_id, p.display_name HAVING COUNT(DISTINCT gc.security_id) >= 2 AND SUM(gc.guaranteed_amount) > 300000000 ORDER BY total_guaranteed DESC, gc.guarantor_party_id;	bankreg_main
SELECT i.institution_name,        COUNT(DISTINCT CASE WHEN p.party_type = 'CORPORATE' THEN p.party_id END) AS corp_count,        COUNT(DISTINCT CASE WHEN p.party_type = 'INDIVIDUAL' THEN p.party_id END) AS retail_count,        ROUND(COUNT(DISTINCT CASE WHEN p.party_type = 'INDIVIDUAL' THEN p.party_id END) * 1.0              / COUNT(DISTINCT p.party_id), 6) AS retail_ratio FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY retail_ratio DESC, i.institution_name;	bankreg_main
WITH combo AS (     SELECT i.institution_name, lp.product_name_zh,            SUM(ps.recognized_amount) AS recognized, SUM(ps.required_amount) AS required,            ROW_NUMBER() OVER (PARTITION BY i.institution_id                               ORDER BY SUM(ps.recognized_amount) * 1.0 / SUM(ps.required_amount),                                        lp.product_name_zh) AS rn     FROM provision_snapshot ps     JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN loan_product_catalog lp ON lp.product_code = ld.drawdown_type     GROUP BY i.institution_id, i.institution_name, lp.product_code, lp.product_name_zh ) SELECT institution_name, product_name_zh, ROUND(recognized, 2) AS recognized,        ROUND(required, 2) AS required_amount,        ROUND(recognized * 1.0 / required, 6) AS coverage FROM combo WHERE rn = 1 ORDER BY coverage, institution_name;	bankreg_main
WITH npl AS (     SELECT a.institution_id,            SUM(CASE WHEN g.is_nonperforming = 1 THEN lbs.principal_balance ELSE 0 END) * 1.0            / SUM(lbs.principal_balance) AS npl_ratio     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN risk_classification rc ON rc.loan_id = ld.loan_id     JOIN classification_grade g ON g.grade_code = rc.grade_code     GROUP BY a.institution_id ), cov AS (     SELECT a.institution_id, SUM(ps.recognized_amount) * 1.0 / SUM(ps.required_amount) AS coverage     FROM provision_snapshot ps     JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     GROUP BY a.institution_id ) SELECT i.institution_name, ROUND(npl.npl_ratio, 6) AS npl_ratio,        ROUND(cov.coverage, 6) AS provision_coverage,        ROUND(cs.net_capital * 1.0 / cs.risk_weighted_assets, 6) AS capital_adequacy FROM npl JOIN cov ON cov.institution_id = npl.institution_id JOIN capital_snapshot cs ON cs.institution_id = npl.institution_id JOIN institution i ON i.institution_id = npl.institution_id WHERE npl.npl_ratio < 0.25   AND cs.net_capital * 1.0 / cs.risk_weighted_assets > 0.1 ORDER BY npl.npl_ratio, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ld.payment_mode = 'ENTRUSTED_PAYMENT' AND ld.status = 'ACTIVE' GROUP BY i.institution_id, i.institution_name ORDER BY cnt DESC, i.institution_name;	bankreg_main
SELECT ld.loan_id, ld.disbursed_amount,        ROUND(SUM(pi.instruction_amount), 2) AS instructed,        ROUND(ld.disbursed_amount - SUM(pi.instruction_amount), 2) AS gap FROM loan_drawdown ld JOIN payment_instruction pi ON pi.loan_id = ld.loan_id GROUP BY ld.loan_id, ld.disbursed_amount HAVING SUM(pi.instruction_amount) < ld.disbursed_amount ORDER BY gap DESC, ld.loan_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE julianday('2026-06-30') - julianday(lbs.overdue_since) >= 90 GROUP BY i.institution_id, i.institution_name ORDER BY cnt DESC, i.institution_name;	bankreg_main
SELECT ld.loan_id, pb.display_name AS borrower, pi.instruction_amount,        pp.display_name AS payee FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party pb ON pb.party_id = a.borrower_party_id JOIN party pp ON pp.party_id = pi.intended_payee_party_id WHERE pi.payment_mode = 'ENTRUSTED_PAYMENT'   AND pi.intended_payee_party_id = a.borrower_party_id ORDER BY pi.instruction_amount DESC, pi.instruction_id LIMIT 200;	bankreg_main
SELECT i.institution_name,        ROUND(AVG(pi.instruction_amount), 2) AS avg_amt,        COUNT(*) AS cnt FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE pi.payment_mode = 'ENTRUSTED_PAYMENT' GROUP BY i.institution_id, i.institution_name ORDER BY avg_amt DESC, i.institution_name;	bankreg_main
SELECT a.agreement_id, p.display_name, a.contract_amount FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE p.party_type = 'CORPORATE' AND p.status = 'FROZEN' AND a.status = 'ACTIVE' ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT f.facility_id, p.display_name, f.facility_type,        ROUND(f.limit_amount,2) AS limit_amount,        ROUND(SUM(a.contract_amount),2) AS signed_total FROM credit_agreement a JOIN credit_facility f ON f.facility_id=a.facility_id JOIN party p ON p.party_id=f.obligor_party_id GROUP BY f.facility_id, p.display_name, f.facility_type, f.limit_amount HAVING SUM(a.contract_amount) > f.limit_amount ORDER BY signed_total DESC, f.facility_id;	bankreg_main
WITH multi_holders AS (   SELECT account_id, COUNT(DISTINCT party_id) AS holder_cnt   FROM account_holder   GROUP BY account_id   HAVING COUNT(DISTINCT party_id) >= 2 ) SELECT a.account_kind,        COUNT(*) AS joint_accts,        SUM(m.holder_cnt) AS total_holder_links FROM account a JOIN multi_holders m ON m.account_id = a.account_id WHERE a.status = 'ACTIVE'   AND a.currency_code = 'CNY' GROUP BY a.account_kind HAVING COUNT(*) > 100 ORDER BY joint_accts DESC, a.account_kind;	bankreg_main
SELECT ld.loan_id, a.contract_amount,        ROUND(SUM(pi.instruction_amount), 2) AS paid,        ROUND(SUM(pi.instruction_amount) - a.contract_amount, 2) AS exceed FROM loan_drawdown ld JOIN payment_instruction pi ON pi.loan_id = ld.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id WHERE ld.payment_mode = 'ENTRUSTED_PAYMENT' GROUP BY ld.loan_id, a.agreement_id, a.contract_amount HAVING SUM(pi.instruction_amount) > a.contract_amount ORDER BY exceed DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, lpc.product_name_zh, s.sector_name_zh, ld.disbursed_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN loan_product_catalog lpc ON lpc.product_code = ld.drawdown_type JOIN industry_sector s ON s.sector_code = a.target_industry_code WHERE lpc.is_working_capital = 1 AND s.risk_category = 'EXIT' AND ld.status = 'ACTIVE' ORDER BY ld.disbursed_amount DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, ld.disbursed_amount, ld.payment_mode FROM loan_drawdown ld WHERE ld.payment_mode = 'SELF_PAYMENT' AND ld.drawdown_type = 'FIXED_ASSET'   AND ld.status = 'ACTIVE' ORDER BY ld.disbursed_amount DESC, ld.loan_id LIMIT 200;	bankreg_main
WITH pi_tot AS (     SELECT loan_id, SUM(instruction_amount) AS instr_amt     FROM payment_instruction     GROUP BY loan_id ) SELECT i.institution_name,        ROUND(SUM(ld.disbursed_amount) - SUM(pi_tot.instr_amt), 2) AS gap FROM loan_drawdown ld JOIN pi_tot ON pi_tot.loan_id = ld.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY gap DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE pi.status = 'PENDING' AND pi.payment_mode = 'ENTRUSTED_PAYMENT' GROUP BY i.institution_id, i.institution_name ORDER BY cnt DESC, i.institution_name;	bankreg_main
WITH dev AS (     SELECT i.institution_id, i.institution_name, ld.loan_id, ld.disbursed_amount,            SUM(pi.instruction_amount) AS paid     FROM loan_drawdown ld     JOIN payment_instruction pi ON pi.loan_id = ld.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id     GROUP BY i.institution_id, i.institution_name, ld.loan_id, ld.disbursed_amount ) SELECT institution_name,        ROUND(AVG(ABS(paid - disbursed_amount) * 1.0 / disbursed_amount), 6) AS avg_dev FROM dev GROUP BY institution_id, institution_name ORDER BY avg_dev DESC, institution_name;	bankreg_main
SELECT a.agreement_id, p.display_name, a.contract_amount FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE a.security_type = 'CREDIT'   AND EXISTS (       SELECT 1 FROM party_relation pr       JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type       WHERE pr.source_party_id = a.borrower_party_id         AND rt.relation_name_zh <> '非关联方'   ) ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
WITH agg AS (   SELECT a.facility_id, SUM(a.contract_amount) AS tot   FROM credit_agreement a GROUP BY a.facility_id ) SELECT f.facility_id, f.facility_type, ROUND(f.limit_amount,2) AS limit_amount,        ROUND(agg.tot,2) AS signed_total,        ROUND(agg.tot * 1.0 / f.limit_amount, 4) AS over_ratio FROM agg JOIN credit_facility f ON f.facility_id=agg.facility_id WHERE f.facility_type='TERM' AND agg.tot > f.limit_amount ORDER BY over_ratio DESC, f.facility_id;	bankreg_main
SELECT p.party_id, p.display_name, ROUND(SUM(a.contract_amount), 2) AS tot FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE EXISTS (     SELECT 1 FROM party_relation pr     JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type     WHERE (pr.source_party_id = a.borrower_party_id OR pr.target_party_id = a.borrower_party_id)       AND rt.relation_name_zh <> '非关联方' ) GROUP BY p.party_id, p.display_name HAVING SUM(a.contract_amount) > 500000000 ORDER BY tot DESC, p.party_id LIMIT 10;	bankreg_main
SELECT ld.loan_id, pb.display_name AS borrower, pp.display_name AS payee,        pi.instruction_amount FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party pb ON pb.party_id = a.borrower_party_id JOIN party pp ON pp.party_id = pi.intended_payee_party_id WHERE EXISTS (     SELECT 1 FROM party_relation pr     WHERE pr.relation_type <> 'NON_RELATED'       AND ((pr.source_party_id = a.borrower_party_id AND pr.target_party_id = pi.intended_payee_party_id)         OR (pr.source_party_id = pi.intended_payee_party_id AND pr.target_party_id = a.borrower_party_id)) ) ORDER BY pi.instruction_amount DESC, pi.instruction_id LIMIT 200;	bankreg_main
SELECT a.agreement_id, f.facility_type,        COUNT(DISTINCT d.loan_id) AS drawdown_cnt,        ROUND(SUM(d.disbursed_amount),2) AS total_disbursed FROM credit_agreement a JOIN credit_facility f ON f.facility_id=a.facility_id JOIN loan_drawdown d ON d.agreement_id=a.agreement_id WHERE f.facility_type <> 'REVOLVING' GROUP BY a.agreement_id, f.facility_type HAVING COUNT(DISTINCT d.loan_id) >= 3 ORDER BY drawdown_cnt DESC, a.agreement_id;	bankreg_main
SELECT a.agreement_id, p.display_name, ROUND(a.contract_amount,2) AS contract_amount,        COUNT(DISTINCT ld.loan_id) AS self_pay_cnt,        ROUND(SUM(ld.disbursed_amount),2) AS self_pay_amount FROM credit_agreement a JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN party p ON p.party_id=a.borrower_party_id WHERE a.payment_mode='ENTRUSTED_PAYMENT' AND ld.payment_mode='SELF_PAYMENT' GROUP BY a.agreement_id, p.display_name, a.contract_amount ORDER BY self_pay_amount DESC, a.agreement_id;	bankreg_main
SELECT i.institution_name, ld.loan_id,        ROUND(lbs.principal_balance,2) AS bal,        ROUND((SELECT AVG(x.principal_balance) FROM loan_balance_snapshot x JOIN loan_drawdown d2 ON d2.loan_id=x.loan_id JOIN credit_agreement a2 ON a2.agreement_id=d2.agreement_id WHERE a2.institution_id=a.institution_id),2) AS inst_avg,        ROUND(lbs.principal_balance - (SELECT AVG(x.principal_balance) FROM loan_balance_snapshot x JOIN loan_drawdown d2 ON d2.loan_id=x.loan_id JOIN credit_agreement a2 ON a2.agreement_id=d2.agreement_id WHERE a2.institution_id=a.institution_id),2) AS gap FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id JOIN credit_agreement a ON a.agreement_id=ld.agreement_id JOIN institution i ON i.institution_id=a.institution_id WHERE lbs.principal_balance > 2*(SELECT AVG(x.principal_balance) FROM loan_balance_snapshot x JOIN loan_drawdown d2 ON d2.loan_id=x.loan_id JOIN credit_agreement a2 ON a2.agreement_id=d2.agreement_id WHERE a2.institution_id=a.institution_id) ORDER BY gap DESC, ld.loan_id;	bankreg_main
SELECT p.party_id, p.display_name, cf.limit_amount FROM credit_facility cf JOIN party p ON p.party_id = cf.obligor_party_id WHERE cf.status = 'ACTIVE' AND EXISTS (     SELECT 1 FROM party_relation pr     JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type     WHERE (pr.source_party_id = cf.obligor_party_id OR pr.target_party_id = cf.obligor_party_id)       AND rt.relation_name_zh <> '非关联方' ) ORDER BY cf.limit_amount DESC, cf.facility_id LIMIT 200;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN NOT EXISTS (            SELECT 1 FROM party_relation pr            WHERE pr.source_party_id = a.borrower_party_id AND pr.relation_type <> 'NON_RELATED'        ) THEN a.contract_amount ELSE 0 END), 2) AS nonrel_amt,        ROUND(SUM(a.contract_amount), 2) AS total_amt,        ROUND(SUM(CASE WHEN NOT EXISTS (            SELECT 1 FROM party_relation pr            WHERE pr.source_party_id = a.borrower_party_id AND pr.relation_type <> 'NON_RELATED'        ) THEN a.contract_amount ELSE 0 END) * 1.0 / SUM(a.contract_amount), 6) AS ratio FROM credit_agreement a JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY ratio DESC, i.institution_name;	bankreg_main
WITH hist AS (   SELECT a.borrower_party_id, a.agreement_id, a.signed_on, a.maturity_on,          LAG(a.maturity_on) OVER (PARTITION BY a.borrower_party_id ORDER BY a.signed_on, a.agreement_id) AS prev_maturity   FROM credit_agreement a ) SELECT p.display_name, h.agreement_id, h.signed_on, h.prev_maturity,        CAST(julianday(h.signed_on) - julianday(h.prev_maturity) AS INTEGER) AS gap_days FROM hist h JOIN party p ON p.party_id = h.borrower_party_id WHERE julianday(h.signed_on) < julianday(h.prev_maturity) ORDER BY gap_days, h.agreement_id LIMIT 300;	bankreg_main
SELECT p1.display_name AS src_name, p2.display_name AS tgt_name, rt.relation_name_zh FROM party_relation pr JOIN party p1 ON p1.party_id = pr.source_party_id JOIN party p2 ON p2.party_id = pr.target_party_id JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type WHERE rt.relation_name_zh = '影子股东' ORDER BY src_name, tgt_name;	bankreg_main
SELECT i.institution_name, p.display_name,        ROUND(SUM(lbs.principal_balance), 2) AS bal,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS ratio FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id WHERE p.party_type = 'CORPORATE' GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.10 ORDER BY ratio DESC, p.party_id LIMIT 200;	bankreg_main
WITH ia AS (   SELECT a.target_industry_code, AVG(a.annual_interest_rate) AS avg_rate   FROM credit_agreement a GROUP BY a.target_industry_code ) SELECT a.agreement_id, p.display_name, ROUND(a.annual_interest_rate,4) AS annual_rate,        ROUND(ia.avg_rate,4) AS industry_avg,        ROUND(a.annual_interest_rate*100 / ia.avg_rate - 100, 2) AS deviation_pct FROM credit_agreement a JOIN ia ON ia.target_industry_code=a.target_industry_code JOIN party p ON p.party_id=a.borrower_party_id WHERE a.annual_interest_rate > 1.1 * ia.avg_rate ORDER BY deviation_pct DESC, a.agreement_id;	bankreg_main
WITH bal AS (     SELECT i.institution_id, i.institution_name, p.party_id, p.display_name,            SUM(lbs.principal_balance) AS b, cs.net_capital     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN party p ON p.party_id = a.borrower_party_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN capital_snapshot cs ON cs.institution_id = i.institution_id     WHERE p.party_type = 'CORPORATE'     GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital ) SELECT institution_name, COUNT(*) AS cnt FROM bal WHERE b * 1.0 / net_capital > 0.10 GROUP BY institution_id, institution_name ORDER BY cnt DESC, institution_name;	bankreg_main
SELECT eg.exposure_group_id, eg.group_name,        ROUND(SUM(lbs.principal_balance), 2) AS bal,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS ratio FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN capital_snapshot cs ON cs.institution_id = eg.institution_id WHERE eg.group_type = 'GROUP_CUSTOMER' GROUP BY eg.exposure_group_id, eg.group_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.10 ORDER BY ratio DESC, eg.exposure_group_id;	bankreg_main
SELECT a.agreement_id, a.maturity_on, ldp.loan_id, ldp.status,        ROUND(a.contract_amount,2) AS contract_amount FROM credit_agreement a JOIN loan_drawdown ldp ON ldp.agreement_id=a.agreement_id WHERE a.status='MATURED' AND ldp.status='ACTIVE' ORDER BY ldp.loan_id;	bankreg_main
SELECT cf.facility_id, p.display_name, cf.limit_amount, cs.net_capital,        ROUND(cf.limit_amount * 1.0 / cs.net_capital, 6) AS ratio FROM credit_facility cf JOIN party p ON p.party_id = cf.obligor_party_id JOIN institution i ON i.institution_id = cf.institution_id JOIN capital_snapshot cs ON cs.institution_id = cf.institution_id WHERE cf.limit_amount * 1.0 / cs.net_capital > 0.10 ORDER BY ratio DESC, cf.facility_id LIMIT 200;	bankreg_main
SELECT i.institution_name, eg.group_name,        ROUND(SUM(lbs.principal_balance), 2) AS bal,        COUNT(DISTINCT egm.party_id) AS members,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS ratio FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN capital_snapshot cs ON cs.institution_id = eg.institution_id JOIN institution i ON i.institution_id = eg.institution_id WHERE eg.group_type = 'CONNECTED_CUSTOMER' GROUP BY i.institution_id, i.institution_name, eg.exposure_group_id, eg.group_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.15 ORDER BY ratio DESC, i.institution_name, eg.group_name;	bankreg_main
SELECT ld.loan_id, ld.disbursement_account_id, ld.disbursed_on, pe.payment_id,        pe.business_date, ROUND(pe.amount,2) AS transferred,        CAST(julianday(pe.business_date)-julianday(ld.disbursed_on) AS INTEGER) AS days_lapse FROM loan_drawdown ld JOIN payment_event pe ON pe.from_account_id=ld.disbursement_account_id WHERE pe.payment_type='TRANSFER' AND pe.status='SETTLED'   AND julianday(pe.business_date)-julianday(ld.disbursed_on) BETWEEN 0 AND 7 ORDER BY days_lapse, transferred DESC, ld.loan_id;	bankreg_main
WITH co AS (     SELECT i.institution_id, i.institution_name, p.party_id, p.display_name,            SUM(lbs.principal_balance) * 1.0 / cs.net_capital AS ratio     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN party p ON p.party_id = a.borrower_party_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN capital_snapshot cs ON cs.institution_id = i.institution_id     WHERE p.party_type = 'CORPORATE'     GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital ), rk AS (     SELECT institution_name, display_name, ratio,            ROW_NUMBER() OVER (PARTITION BY institution_id ORDER BY ratio DESC) AS rn     FROM co ) SELECT institution_name, display_name, ROUND(ratio, 6) AS ratio FROM rk WHERE rn = 1 ORDER BY institution_name;	bankreg_main
SELECT a.agreement_id, p.display_name, s.sector_name_zh, a.contract_amount FROM credit_agreement a JOIN industry_sector s ON s.sector_code = a.target_industry_code JOIN party p ON p.party_id = a.borrower_party_id WHERE s.risk_category = 'EXIT' AND a.status = 'ACTIVE' ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT i.institution_name, s.sector_name_zh, ROUND(SUM(a.contract_amount), 2) AS amt FROM credit_agreement a JOIN institution i ON i.institution_id = a.institution_id JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE s.risk_category = 'EXIT' GROUP BY i.institution_id, i.institution_name, s.sector_code, s.sector_name_zh ORDER BY amt DESC, i.institution_name, s.sector_name_zh;	bankreg_main
SELECT ca.product_family,        COUNT(DISTINCT ca.agreement_id) AS total_agr,        COUNT(DISTINCT CASE WHEN ca.security_type = 'MORTGAGE' THEN ca.agreement_id END) AS secured_agr FROM credit_agreement ca JOIN credit_facility cf ON cf.facility_id = ca.facility_id JOIN institution i ON i.institution_id = ca.institution_id GROUP BY ca.product_family HAVING (100.0 * COUNT(DISTINCT CASE WHEN ca.security_type = 'MORTGAGE' THEN ca.agreement_id END) / COUNT(DISTINCT ca.agreement_id)) < 19.0 ORDER BY total_agr DESC, ca.product_family;	bankreg_main
SELECT loan_id, principal_balance, quartile FROM (     SELECT lbs.loan_id, ROUND(lbs.principal_balance,2) AS principal_balance,            NTILE(4) OVER (PARTITION BY a.institution_id ORDER BY lbs.principal_balance DESC) AS quartile     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id     JOIN credit_agreement a ON a.agreement_id=ld.agreement_id ) ORDER BY quartile ASC, principal_balance DESC LIMIT 300;	bankreg_main
SELECT rs.loan_id, ROUND(SUM(rs.principal_due),2) AS overdue_principal_due,        ROUND(MAX(lb.overdue_principal),2) AS reported_overdue,        COUNT(*) AS overdue_installments FROM repayment_schedule rs JOIN loan_balance_snapshot lb ON lb.loan_id=rs.loan_id WHERE rs.status='OVERDUE' GROUP BY rs.loan_id HAVING MAX(lb.overdue_principal) = 0 ORDER BY overdue_principal_due DESC, rs.loan_id;	bankreg_main
SELECT p.party_id, p.display_name, s.sector_name_zh FROM party p JOIN organization_profile op ON op.party_id = p.party_id JOIN industry_sector s ON s.sector_code = op.industry_code JOIN credit_agreement a ON a.borrower_party_id = p.party_id WHERE s.risk_category = 'EXIT' GROUP BY p.party_id, p.display_name, s.sector_code, s.sector_name_zh ORDER BY s.sector_name_zh, p.party_id;	bankreg_main
SELECT p.party_id,        p.customer_segment FROM party p WHERE p.customer_segment IN ('AFFLUENT','LARGE')   AND p.status = 'ACTIVE'   AND NOT EXISTS (     SELECT 1 FROM party_relation pr     WHERE pr.source_party_id = p.party_id   ) ORDER BY p.customer_segment, p.party_id;	bankreg_main
WITH ranked AS (     SELECT s.sector_name_zh, a.agreement_id, a.contract_amount,            ROW_NUMBER() OVER (PARTITION BY s.sector_code ORDER BY a.contract_amount DESC) AS rnk     FROM credit_agreement a     JOIN industry_sector s ON s.sector_code = a.target_industry_code     WHERE s.risk_category = 'RESTRICTED' ) SELECT sector_name_zh, agreement_id, contract_amount, rnk FROM ranked WHERE rnk <= 5 ORDER BY sector_name_zh, rnk, agreement_id;	bankreg_main
WITH acct AS (   SELECT a.account_id, a.account_kind, a.opened_on,          LAG(a.opened_on) OVER (PARTITION BY a.account_kind ORDER BY a.opened_on) AS prev_open   FROM account a   WHERE a.status = 'ACTIVE' ) SELECT account_kind,        COUNT(*) AS cnt FROM acct WHERE prev_open IS NOT NULL GROUP BY account_kind HAVING COUNT(*) < 900 ORDER BY cnt DESC, account_kind;	bankreg_main
SELECT p.party_id, p.display_name, s.sector_name_zh, ROUND(SUM(a.contract_amount), 2) AS amt FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id JOIN organization_profile op ON op.party_id = p.party_id JOIN industry_sector s ON s.sector_code = op.industry_code JOIN exposure_group_member egm ON egm.party_id = a.borrower_party_id WHERE s.risk_category IN ('RESTRICTED', 'EXIT') GROUP BY p.party_id, p.display_name, s.sector_code, s.sector_name_zh ORDER BY amt DESC, p.party_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt, ROUND(SUM(a.contract_amount), 2) AS amt FROM credit_agreement a JOIN institution i ON i.institution_id = a.institution_id JOIN industry_sector s ON s.sector_code = a.target_industry_code WHERE s.sector_name_zh = '房地产业' GROUP BY i.institution_id, i.institution_name ORDER BY cnt DESC, i.institution_name;	bankreg_main
SELECT q.loan_id, q.inst_name, ROUND(q.principal_balance,2) AS bal,        ROUND(q.principal_balance*100.0/SUM(q.principal_balance) OVER (PARTITION BY q.inst_id),2) AS share FROM (SELECT a.institution_id inst_id, i.institution_name inst_name, ld.loan_id, lbs.principal_balance       FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id       JOIN credit_agreement a ON a.agreement_id=ld.agreement_id       JOIN institution i ON i.institution_id=a.institution_id) q ORDER BY q.inst_name, share DESC, q.loan_id LIMIT 300;	bankreg_main
SELECT ou.org_unit_id, ou.unit_name, COUNT(DISTINCT pr.source_party_id) AS cnt FROM party_relation pr JOIN party p ON p.party_id = pr.source_party_id JOIN organization_unit ou ON ou.org_unit_id = p.home_org_unit_id JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type WHERE rt.relation_name_zh IN ('关键管理人员', '实际控制人') GROUP BY ou.org_unit_id, ou.unit_name ORDER BY cnt DESC, ou.org_unit_id;	bankreg_main
SELECT ld.loan_id, ROUND(ld.disbursed_amount,2) AS disbursed_amount, ld.status,        ROUND(SUM(rs.principal_due),2) AS overdue_principal,        COUNT(*) AS overdue_installments FROM loan_drawdown ld JOIN repayment_schedule rs ON rs.loan_id=ld.loan_id WHERE ld.status='ACTIVE' AND rs.status='OVERDUE' GROUP BY ld.loan_id, ld.disbursed_amount, ld.status HAVING COUNT(*) >= 2 ORDER BY overdue_installments DESC, overdue_principal DESC, ld.loan_id;	bankreg_main
SELECT a.loan_account_id, a.disbursed_on, COUNT(DISTINCT a.loan_id) AS cnt FROM loan_drawdown a JOIN loan_drawdown b   ON b.loan_account_id=a.loan_account_id AND b.disbursed_on=a.disbursed_on AND b.loan_id<>a.loan_id GROUP BY a.loan_account_id, a.disbursed_on HAVING COUNT(DISTINCT a.loan_id)>=2 ORDER BY cnt DESC, a.loan_account_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, ld.closed_on, ld.current_maturity_on FROM loan_drawdown ld WHERE ld.closed_on > ld.current_maturity_on ORDER BY ld.closed_on DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT rc.loan_id, d.principal_overdue_days, d.overdue_principal FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code JOIN delinquency_snapshot d ON d.loan_id = rc.loan_id WHERE g.grade_name_zh = '正常' AND d.principal_overdue_days >= 45 ORDER BY d.principal_overdue_days DESC, rc.loan_id;	bankreg_main
SELECT a.account_subtype,        COUNT(*) AS cnt FROM account a WHERE a.status = 'DORMANT' GROUP BY a.account_subtype HAVING COUNT(*) >= 55 ORDER BY cnt DESC, a.account_subtype;	bankreg_main
SELECT collateral_id, val, prev_val, incr FROM (   SELECT cv.collateral_id,          ROUND(cv.valuation_amount,2) AS val,          ROUND(LAG(cv.valuation_amount) OVER (PARTITION BY cv.collateral_id ORDER BY cv.valued_on),2) AS prev_val,          ROUND(cv.valuation_amount/NULLIF(LAG(cv.valuation_amount) OVER (PARTITION BY cv.collateral_id ORDER BY cv.valued_on),0),2) AS incr   FROM collateral_valuation cv ) WHERE val > 1.5*prev_val ORDER BY incr DESC, collateral_id;	bankreg_main
SELECT ou.unit_name, rc.classification_basis, COUNT(*) AS cnt FROM risk_classification rc JOIN organization_unit ou ON ou.org_unit_id = rc.assessed_org_unit_id GROUP BY ou.org_unit_id, ou.unit_name, rc.classification_basis ORDER BY cnt DESC, ou.unit_name, rc.classification_basis;	bankreg_main
SELECT i.institution_name, ROUND(SUM(lbs.principal_balance), 2) AS bad_balance FROM loan_balance_snapshot lbs JOIN risk_classification rc ON rc.loan_id = lbs.loan_id JOIN classification_grade g ON g.grade_code = rc.grade_code JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE g.is_nonperforming = 1 GROUP BY i.institution_id, i.institution_name ORDER BY bad_balance DESC;	bankreg_main
SELECT ah.party_id AS party_id FROM account_holder ah JOIN term_deposit td ON td.account_id=ah.account_id INTERSECT SELECT a.borrower_party_id AS party_id FROM credit_agreement a ORDER BY party_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS loss_count FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code JOIN loan_drawdown ld ON ld.loan_id = rc.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE g.grade_name_zh = '损失' GROUP BY i.institution_id, i.institution_name ORDER BY loss_count DESC, i.institution_name;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(ps.recognized_amount) * 1.0 / SUM(ps.required_amount), 4) AS coverage FROM provision_snapshot ps JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY coverage ASC, i.institution_name;	bankreg_main
SELECT party_id FROM (     SELECT sm.person_party_id AS party_id     FROM staff_member sm     WHERE sm.employment_status = 'ACTIVE'     EXCEPT     SELECT ah.party_id AS party_id     FROM account_holder ah ) ORDER BY party_id;	bankreg_main
SELECT a.account_id FROM account a WHERE a.account_kind='SAVINGS'   AND NOT EXISTS (SELECT 1 FROM payment_event e WHERE e.from_account_id=a.account_id AND e.is_cash=1) ORDER BY a.account_id LIMIT 300;	bankreg_main
SELECT c.collateral_id, c.asset_label, v.valuation_amount, lk.pledged_amount FROM collateral_asset c JOIN collateral_link lk ON lk.collateral_id = c.collateral_id JOIN collateral_valuation v ON v.collateral_id = c.collateral_id WHERE v.valuation_amount < lk.pledged_amount ORDER BY v.valuation_amount ASC, c.collateral_id;	bankreg_main
SELECT s.security_id, s.secured_amount FROM security_agreement s LEFT JOIN collateral_link lk ON lk.security_id = s.security_id WHERE s.security_type IN ('MORTGAGE', 'PLEDGE')   AND s.status = 'ACTIVE'   AND lk.security_id IS NULL ORDER BY s.secured_amount DESC, s.security_id;	bankreg_main
SELECT a.account_id FROM account a LEFT JOIN account_holder ah ON ah.account_id=a.account_id AND ah.holder_role='PRIMARY' WHERE ah.account_id IS NULL ORDER BY a.account_id LIMIT 300;	bankreg_main
SELECT lk.collateral_id, lk.lien_priority, lk.pledge_ratio FROM collateral_link lk WHERE lk.lien_priority = 1 AND lk.pledge_ratio > 0.7 AND lk.status = 'ACTIVE' ORDER BY lk.pledge_ratio DESC, lk.collateral_id;	bankreg_main
SELECT i.institution_name, s.security_type, ROUND(SUM(s.secured_amount), 2) AS total FROM security_agreement s JOIN institution i ON i.institution_id = s.institution_id WHERE s.status = 'ACTIVE' GROUP BY i.institution_id, i.institution_name, s.security_type ORDER BY total DESC, i.institution_name, s.security_type;	bankreg_main
SELECT s.security_id, c.collateral_id FROM security_agreement s JOIN collateral_link lk ON lk.security_id = s.security_id JOIN collateral_asset c ON c.collateral_id = lk.collateral_id WHERE s.status = 'EXPIRED' AND c.status = 'ACTIVE' ORDER BY s.security_id, c.collateral_id;	bankreg_main
SELECT g.security_id, g.guaranteed_amount FROM guarantor_commitment g WHERE g.status = 'EXPIRED' ORDER BY g.guaranteed_amount DESC, g.security_id;	bankreg_main
SELECT bucket, COUNT(*) AS cnt FROM (   SELECT CASE WHEN julianday(ld.current_maturity_on)-julianday('2026-06-30')<0 THEN '已到期'               WHEN julianday(ld.current_maturity_on)-julianday('2026-06-30')<=90 THEN '临期'               ELSE '常态' END AS bucket   FROM loan_drawdown ld ) GROUP BY bucket ORDER BY CASE bucket WHEN '常态' THEN 1 WHEN '临期' THEN 2 ELSE 3 END;	bankreg_main
SELECT lk.collateral_id, COUNT(*) AS uses FROM collateral_link lk WHERE lk.status = 'ACTIVE' GROUP BY lk.collateral_id HAVING COUNT(*) > 1 ORDER BY uses DESC, lk.collateral_id;	bankreg_main
SELECT c.collateral_type, ROUND(AVG(v.valuation_amount), 2) AS avg_val, COUNT(*) AS cnt FROM collateral_valuation v JOIN collateral_asset c ON c.collateral_id = v.collateral_id WHERE v.appraiser_kind = 'BANK_INTERNAL' GROUP BY c.collateral_type ORDER BY avg_val DESC;	bankreg_main
SELECT ld.loan_id, ROUND(ld.disbursed_amount,2) AS disbursed_amount,        pi.instruction_id, ROUND(pi.instruction_amount,2) AS pending_amount, pi.status FROM loan_drawdown ld JOIN payment_instruction pi ON pi.loan_id=ld.loan_id WHERE pi.status='PENDING' AND ld.status='ACTIVE' ORDER BY pending_amount DESC, ld.loan_id;	bankreg_main
WITH sp AS (   SELECT d.agreement_id, SUM(d.disbursed_amount) AS self_amount   FROM loan_drawdown d   WHERE d.payment_mode='SELF_PAYMENT'   GROUP BY d.agreement_id ) SELECT a.agreement_id, p.display_name, ROUND(a.contract_amount,2) AS contract_amount,        ROUND(sp.self_amount,2) AS self_amount,        ROUND(sp.self_amount * 1.0 / a.contract_amount, 4) AS self_ratio FROM sp JOIN credit_agreement a ON a.agreement_id=sp.agreement_id JOIN party p ON p.party_id=a.borrower_party_id WHERE sp.self_amount > 0.3 * a.contract_amount ORDER BY a.agreement_id;	bankreg_main
WITH rk AS (   SELECT d.loan_id, d.repayment_account_id, d.disbursed_on, d.disbursed_amount,          ROW_NUMBER() OVER (PARTITION BY d.repayment_account_id ORDER BY d.disbursed_on, d.loan_id) AS rn,          COUNT(*) OVER (PARTITION BY d.repayment_account_id) AS loan_cnt   FROM loan_drawdown d ) SELECT r.repayment_account_id, r.loan_id, r.disbursed_on, ROUND(r.disbursed_amount,2) AS amount, r.loan_cnt FROM rk r WHERE r.loan_cnt >= 3 AND r.rn <= 2 ORDER BY r.repayment_account_id, r.disbursed_on;	bankreg_main
SELECT so.operator_id, so.staff_id FROM service_operator so WHERE so.operator_kind = 'TELLER' AND so.authority_level = 'L3' ORDER BY so.operator_id;	bankreg_main
SELECT sa.role_title, COUNT(DISTINCT sa.staff_id) AS staff_count FROM staff_assignment sa GROUP BY sa.role_title ORDER BY staff_count DESC, sa.role_title;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, f.facility_id, f.effective_from, f.approved_on,        ROUND(ld.disbursed_amount,2) AS disbursed_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id=ld.agreement_id JOIN credit_facility f ON f.facility_id=a.facility_id WHERE ld.disbursed_on < f.effective_from ORDER BY f.facility_id, ld.loan_id;	bankreg_main
WITH ds AS (   SELECT d.agreement_id, SUM(d.disbursed_amount) AS total_disbursed, COUNT(DISTINCT d.loan_id) AS drawdown_cnt   FROM loan_drawdown d GROUP BY d.agreement_id ) SELECT a.agreement_id, ROUND(a.contract_amount,2) AS contract_amount,        ROUND(ds.total_disbursed,2) AS total_disbursed,        ROUND(ds.total_disbursed - a.contract_amount,2) AS excess_amount,        ds.drawdown_cnt FROM ds JOIN credit_agreement a ON a.agreement_id=ds.agreement_id WHERE ds.total_disbursed > a.contract_amount ORDER BY a.agreement_id;	bankreg_main
SELECT ld.disbursement_account_id, COUNT(DISTINCT ld.loan_id) AS loan_cnt,        ROUND(SUM(ld.disbursed_amount),2) AS total_disbursed FROM loan_drawdown ld GROUP BY ld.disbursement_account_id HAVING COUNT(DISTINCT ld.loan_id) >= 5 ORDER BY loan_cnt DESC, ld.disbursement_account_id;	bankreg_main
SELECT a.agreement_id, p.display_name, COUNT(DISTINCT ld.loan_id) AS self_installments FROM credit_agreement a JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id AND ld.payment_mode='SELF_PAYMENT' JOIN party p ON p.party_id=a.borrower_party_id GROUP BY a.agreement_id, p.display_name HAVING COUNT(DISTINCT ld.loan_id) >= 5 ORDER BY self_installments DESC, a.agreement_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS frozen_cnt, ROUND(SUM(s.ledger_balance - s.available_balance), 2) AS frozen_amt FROM account_balance_snapshot s JOIN account a ON a.account_id = s.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE (s.ledger_balance - s.available_balance) > 5000000 GROUP BY i.institution_id, i.institution_name ORDER BY frozen_amt DESC;	bankreg_main
SELECT t.account_id, t.opening_principal, t.maturity_on, t.annual_interest_rate FROM term_deposit t JOIN account a ON a.account_id = t.account_id WHERE a.status = 'ACTIVE' AND t.maturity_on < '2026-06-30' ORDER BY t.maturity_on, t.account_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt, ROUND(SUM(pe.amount), 2) AS total FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id) JOIN institution i ON i.institution_id = ac.institution_id WHERE t.name_zh = '现金支取' AND pe.amount > 1000000 AND pe.status = 'SETTLED' GROUP BY i.institution_id, i.institution_name ORDER BY total DESC;	bankreg_main
SELECT pc.card_id,        pc.card_type,        pc.issued_on FROM payment_card pc WHERE pc.card_type = 'DEBIT'   AND pc.status = 'ACTIVE'   AND pc.issued_on <= '2025-01-31' ORDER BY pc.issued_on, pc.card_id;	bankreg_main
WITH ratio AS (   SELECT i.institution_name,          ROUND(SUM(CASE WHEN d.payment_mode='ENTRUSTED_PAYMENT' THEN d.disbursed_amount ELSE 0 END),2) AS entrusted_amt,          ROUND(SUM(CASE WHEN d.payment_mode='SELF_PAYMENT' THEN d.disbursed_amount ELSE 0 END),2) AS self_amt   FROM loan_drawdown d   JOIN credit_agreement a ON a.agreement_id=d.agreement_id   JOIN institution i ON i.institution_id=a.institution_id   GROUP BY i.institution_name ) SELECT institution_name, entrusted_amt, self_amt,        ROUND(entrusted_amt * 1.0 / (entrusted_amt + self_amt), 4) AS entrusted_ratio FROM ratio WHERE entrusted_amt * 1.0 / (entrusted_amt + self_amt) < 0.52 ORDER BY entrusted_ratio, institution_name;	bankreg_main
WITH share AS (   SELECT d.agreement_id, d.loan_id, ROUND(d.disbursed_amount,2) AS amount,          ROUND(SUM(d.disbursed_amount) OVER (PARTITION BY d.agreement_id),2) AS agg_total   FROM loan_drawdown d ) SELECT s.agreement_id, s.loan_id, s.amount, s.agg_total,        ROUND(s.amount * 100.0 / s.agg_total, 2) AS pct_share FROM share s WHERE s.amount * 100.0 / s.agg_total > 90 ORDER BY s.agreement_id, s.loan_id;	bankreg_main
SELECT a.account_id, s.ledger_balance FROM account a JOIN account_balance_snapshot s ON s.account_id = a.account_id WHERE a.status = 'CLOSED' ORDER BY s.ledger_balance DESC, a.account_id;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(wp.actual_raise_amount),2) AS actual,        ROUND(SUM(CASE WHEN wp.status='ON_SALE' THEN wp.planned_raise_amount ELSE 0 END),2) AS planned,        ROUND(SUM(wp.actual_raise_amount)*1.0/NULLIF(SUM(CASE WHEN wp.status='ON_SALE' THEN wp.planned_raise_amount ELSE 0 END),0),4) AS ratio FROM wealth_product wp JOIN institution i ON i.institution_id=wp.issuer_institution_id GROUP BY i.institution_id, i.institution_name HAVING SUM(wp.actual_raise_amount)*1.0/NULLIF(SUM(CASE WHEN wp.status='ON_SALE' THEN wp.planned_raise_amount ELSE 0 END),0)>1.2 ORDER BY ratio DESC, i.institution_name;	bankreg_main
SELECT i.institution_name,        COUNT(DISTINCT CASE WHEN pi.payment_mode='ENTRUSTED_PAYMENT' THEN pi.instruction_id END) AS ent_cnt,        COUNT(DISTINCT CASE WHEN pi.payment_mode='SELF_PAYMENT' THEN pi.instruction_id END) AS self_cnt,        ROUND(SUM(CASE WHEN pi.payment_mode='ENTRUSTED_PAYMENT' THEN pi.instruction_amount ELSE 0 END),2) AS ent_amt FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id=pi.loan_id JOIN credit_agreement a ON a.agreement_id=ld.agreement_id JOIN institution i ON i.institution_id=a.institution_id GROUP BY i.institution_id, i.institution_name HAVING COUNT(DISTINCT CASE WHEN pi.payment_mode='SELF_PAYMENT' THEN pi.instruction_id END)>0 ORDER BY ent_amt DESC, i.institution_name;	bankreg_main
SELECT SUBSTR(e.business_date,1,7) AS ym, a.account_id, ROUND(SUM(e.amount),2) AS tot FROM payment_event e JOIN account a ON a.account_id=e.from_account_id WHERE e.is_cash=1 GROUP BY ym, a.account_id HAVING SUM(e.amount)>5000000 ORDER BY tot DESC, ym, a.account_id LIMIT 200;	bankreg_main
SELECT a.borrower_party_id, p.display_name,        COUNT(DISTINCT CASE WHEN rs.status='OVERDUE' THEN ld.loan_id END) AS overdue_loans,        COUNT(DISTINCT ld.loan_id) AS total_loans FROM credit_agreement a JOIN party p ON p.party_id=a.borrower_party_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN repayment_schedule rs ON rs.loan_id=ld.loan_id GROUP BY a.borrower_party_id, p.display_name HAVING COUNT(DISTINCT CASE WHEN rs.status='OVERDUE' THEN ld.loan_id END) >= 1    AND COUNT(DISTINCT CASE WHEN rs.status='OVERDUE' THEN ld.loan_id END) < COUNT(DISTINCT ld.loan_id) ORDER BY overdue_loans DESC, a.borrower_party_id;	bankreg_main
WITH o AS (   SELECT lb.loan_id, lb.overdue_since, lb.overdue_principal,          CAST(julianday('2026-06-30') - julianday(lb.overdue_since) AS INTEGER) AS overdue_days,          ld.status   FROM loan_balance_snapshot lb   JOIN loan_drawdown ld ON ld.loan_id = lb.loan_id ) SELECT loan_id, overdue_since, ROUND(overdue_principal, 2) AS overdue_principal, overdue_days FROM o WHERE status = 'ACTIVE' AND overdue_principal > 10000000 AND overdue_days > 90 ORDER BY loan_id LIMIT 300;	bankreg_main
SELECT ld.loan_id, ac.account_id, ROUND(ld.disbursed_amount,2) AS disbursed_amount, ac.status AS account_status FROM loan_drawdown ld JOIN account ac ON ac.account_id=ld.loan_account_id WHERE ac.status <> 'ACTIVE' AND ld.status='ACTIVE' ORDER BY ac.status, ld.loan_id;	bankreg_main
SELECT p.loan_id, ROUND(p.required_amount, 2) AS required_amount,        ROUND(p.recognized_amount, 2) AS recognized_amount,        ROUND(p.required_amount - p.recognized_amount, 2) AS shortfall FROM provision_snapshot p JOIN loan_drawdown ld ON ld.loan_id = p.loan_id WHERE p.recognized_amount < p.required_amount   AND EXISTS (SELECT 1 FROM repayment_schedule rs WHERE rs.loan_id = p.loan_id AND rs.status = 'OVERDUE') ORDER BY p.loan_id LIMIT 200;	bankreg_main
SELECT pi.instruction_id, ld.loan_id, p1.display_name AS borrower, p2.display_name AS payee,        ROUND(pi.instruction_amount,2) AS amount FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id=pi.loan_id JOIN credit_agreement a ON a.agreement_id=ld.agreement_id JOIN party p1 ON p1.party_id=a.borrower_party_id JOIN party p2 ON p2.party_id=pi.intended_payee_party_id WHERE pi.intended_payee_party_id <> a.borrower_party_id AND pi.status='EXECUTED' ORDER BY amount DESC, pi.instruction_id;	bankreg_main
WITH seq AS (   SELECT a.borrower_party_id, ld.loan_id, ld.disbursed_on,          LAG(ld.disbursed_on) OVER (PARTITION BY a.borrower_party_id ORDER BY ld.disbursed_on, ld.loan_id) AS prev_disbursed   FROM loan_drawdown ld   JOIN credit_agreement a ON a.agreement_id=ld.agreement_id ) SELECT p.display_name, s.loan_id, s.disbursed_on, s.prev_disbursed,        CAST(julianday(s.disbursed_on)-julianday(s.prev_disbursed) AS INTEGER) AS gap_days FROM seq s JOIN party p ON p.party_id=s.borrower_party_id WHERE julianday(s.disbursed_on)-julianday(s.prev_disbursed) <= 3 ORDER BY gap_days, s.loan_id;	bankreg_main
WITH bal AS (   SELECT ld.agreement_id, SUM(lbs.principal_balance) AS cur_balance   FROM loan_balance_snapshot lbs   JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id   JOIN credit_agreement a ON a.agreement_id=ld.agreement_id   JOIN credit_facility f ON f.facility_id=a.facility_id AND f.facility_type='REVOLVING'   GROUP BY ld.agreement_id ) SELECT a.agreement_id, ROUND(a.contract_amount,2) AS contract_amount,        ROUND(bal.cur_balance,2) AS current_balance,        ROUND(bal.cur_balance - a.contract_amount,2) AS excess FROM bal JOIN credit_agreement a ON a.agreement_id=bal.agreement_id WHERE bal.cur_balance > a.contract_amount ORDER BY excess DESC, a.agreement_id;	bankreg_main
SELECT ld.loan_id, lp.product_name_zh, ld.disbursed_on, ld.original_maturity_on,        CAST((julianday(ld.original_maturity_on)-julianday(ld.disbursed_on))/30.0 AS INTEGER) AS tenor_months,        ROUND(ld.disbursed_amount,2) AS amount FROM loan_drawdown ld JOIN loan_product_catalog lp ON lp.product_code=ld.drawdown_type WHERE lp.is_working_capital=1   AND (julianday(ld.original_maturity_on)-julianday(ld.disbursed_on)) > 730 ORDER BY tenor_months DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, a.agreement_id, a.signed_on, ROUND(ld.disbursed_amount,2) AS amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id=ld.agreement_id WHERE ld.disbursed_on < a.signed_on ORDER BY ld.loan_id;	bankreg_main
SELECT collateral_type, COUNT(*) AS cnt FROM collateral_asset WHERE status = 'ACTIVE' GROUP BY collateral_type ORDER BY cnt DESC, collateral_type;	bankreg_main
WITH base AS (   SELECT loan_id, disbursed_amount FROM loan_drawdown WHERE status IN ('ACTIVE','SETTLED') ), paid AS (   SELECT loan_id, SUM(principal_due) AS tot FROM repayment_schedule WHERE status = 'PAID' GROUP BY loan_id ), ranked AS (   SELECT loan_id, disbursed_amount,          ROW_NUMBER() OVER (ORDER BY disbursed_amount DESC) AS rr   FROM base ) SELECT r.loan_id, r.disbursed_amount, p.tot FROM ranked r JOIN paid p ON p.loan_id = r.loan_id WHERE r.rr <= 30 ORDER BY r.rr;	bankreg_main
SELECT a.agreement_id, d1.loan_id AS old_loan_id, d1.original_maturity_on AS old_maturity,        d2.loan_id AS new_loan_id, d2.disbursed_on AS new_disbursed,        CAST(julianday(d2.disbursed_on)-julianday(d1.original_maturity_on) AS INTEGER) AS gap_days FROM loan_drawdown d1 JOIN credit_agreement a ON a.agreement_id=d1.agreement_id JOIN loan_drawdown d2 ON d2.agreement_id=d1.agreement_id AND d2.loan_id<>d1.loan_id WHERE julianday(d2.disbursed_on)-julianday(d1.original_maturity_on) < 30   AND julianday(d2.disbursed_on)-julianday(d1.original_maturity_on) >= 0 ORDER BY gap_days, a.agreement_id;	bankreg_main
SELECT a.borrower_party_id, p.display_name, COUNT(DISTINCT a.institution_id) AS inst_cnt,        COUNT(DISTINCT ld.loan_id) AS loan_cnt, ROUND(SUM(ld.disbursed_amount),2) AS total_disbursed FROM credit_agreement a JOIN party p ON p.party_id=a.borrower_party_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id WHERE ld.status='ACTIVE' GROUP BY a.borrower_party_id, p.display_name HAVING COUNT(DISTINCT a.institution_id) >= 2 ORDER BY loan_cnt DESC, a.borrower_party_id;	bankreg_main
SELECT rs.loan_id, COUNT(*) AS overdue_cnt,        ROUND(SUM(rs.principal_due),2) AS overdue_principal FROM repayment_schedule rs GROUP BY rs.loan_id HAVING SUM(CASE WHEN rs.status='PAID' THEN 1 ELSE 0 END) = 0 ORDER BY overdue_principal DESC, rs.loan_id LIMIT 200;	bankreg_main
SELECT pe.payment_id, pe.from_account_id, ac2.account_id AS dest_account,        ac2.account_kind AS dest_kind, ROUND(pe.amount, 2) AS amount FROM payment_event pe JOIN account ac2 ON ac2.account_id = pe.to_account_id WHERE pe.payment_type = 'TRANSFER' AND pe.status = 'SETTLED'   AND ac2.account_kind = 'SAVINGS' AND pe.amount > 100000   AND EXISTS (SELECT 1 FROM loan_drawdown ld WHERE ld.disbursement_account_id = pe.from_account_id) ORDER BY pe.payment_id LIMIT 300;	bankreg_main
SELECT lb.loan_id, ROUND(lb.overdue_principal,2) AS overdue_principal FROM loan_balance_snapshot lb WHERE lb.overdue_principal > 0   AND NOT EXISTS (SELECT 1 FROM repayment_schedule rs WHERE rs.loan_id=lb.loan_id AND rs.status='OVERDUE') ORDER BY overdue_principal DESC, lb.loan_id;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, a.agreement_id, ROUND(a.contract_amount,2) AS contract_amount,        ROUND(ld.disbursed_amount,2) AS disbursed_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id=ld.agreement_id WHERE ld.disbursed_amount > a.contract_amount ORDER BY disbursed_amount DESC, ld.loan_id;	bankreg_main
WITH ia AS (   SELECT target_industry_code, AVG(annual_interest_rate) AS avg_rate   FROM credit_agreement GROUP BY target_industry_code ) SELECT a.agreement_id, p.display_name, ROUND(a.annual_interest_rate,4) AS annual_rate,        ROUND(ia.avg_rate,4) AS industry_avg,        ROUND(a.annual_interest_rate*100/ia.avg_rate-100,2) AS discount_pct FROM credit_agreement a JOIN ia ON ia.target_industry_code=a.target_industry_code JOIN party p ON p.party_id=a.borrower_party_id WHERE a.annual_interest_rate < 0.9 * ia.avg_rate ORDER BY discount_pct, a.agreement_id;	bankreg_main
SELECT a.agreement_id, s.sector_name_zh, s.risk_category,        ROUND(a.contract_amount,2) AS contract_amount, p.display_name FROM credit_agreement a JOIN industry_sector s ON s.sector_code=a.target_industry_code JOIN party p ON p.party_id=a.borrower_party_id WHERE s.risk_category IN ('EXIT','RESTRICTED') ORDER BY a.agreement_id;	bankreg_main
SELECT ld.loan_id, ROUND(lbs.principal_balance, 2) AS balance, ROUND(lbs.overdue_principal, 2) AS overdue_principal FROM loan_drawdown ld JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id WHERE ld.status = 'WRITTEN_OFF' AND lbs.principal_balance > 10000000 ORDER BY lbs.principal_balance DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, ac.account_id, ac.opened_on FROM loan_drawdown ld JOIN account ac ON ac.account_id=ld.disbursement_account_id WHERE ld.disbursed_on < ac.opened_on ORDER BY ld.disbursed_on, ld.loan_id;	bankreg_main
SELECT ld.loan_id, ac.account_id, ac.account_kind, ROUND(ld.disbursed_amount,2) AS amount FROM loan_drawdown ld JOIN account ac ON ac.account_id=ld.disbursement_account_id WHERE ac.account_kind='SAVINGS' ORDER BY amount DESC, ld.loan_id;	bankreg_main
SELECT a.agreement_id, a.security_type, ROUND(a.contract_amount,2) AS contract_amount,        p.display_name FROM credit_agreement a JOIN party p ON p.party_id=a.borrower_party_id WHERE a.security_type='CREDIT' AND a.contract_amount > 8000000 ORDER BY contract_amount DESC, a.agreement_id;	bankreg_main
WITH fam_avg AS (   SELECT institution_id, product_family, AVG(annual_interest_rate) AS fam_rate   FROM credit_agreement   GROUP BY institution_id, product_family ) SELECT p.display_name AS 借款人名称, a.borrower_party_id AS 客户编号,        a.annual_interest_rate AS 合同年利率,        ROUND(fa.fam_rate, 4) AS 同类产品平均利率,        ROUND(fa.fam_rate - a.annual_interest_rate, 4) AS 利率价差 FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id JOIN fam_avg fa ON fa.institution_id = a.institution_id AND fa.product_family = a.product_family WHERE a.annual_interest_rate < fa.fam_rate   AND EXISTS (SELECT 1 FROM party_relation pr               JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type               WHERE (pr.source_party_id = a.borrower_party_id OR pr.target_party_id = a.borrower_party_id)                 AND rc.relation_name_zh <> '非关联方') ORDER BY 利率价差 DESC, a.borrower_party_id;	bankreg_main
WITH related AS (   SELECT DISTINCT pr.source_party_id AS pid FROM party_relation pr   JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type   WHERE rc.relation_name_zh <> '非关联方'   UNION   SELECT DISTINCT pr.target_party_id FROM party_relation pr   JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type   WHERE rc.relation_name_zh <> '非关联方' ) SELECT p.display_name AS 借款人名称, a.borrower_party_id AS 客户编号,        COUNT(DISTINCT a.agreement_id) AS 信用贷款笔数,        ROUND(SUM(a.contract_amount), 2) AS 授信金额合计 FROM related r JOIN credit_agreement a ON a.borrower_party_id = r.pid JOIN party p ON p.party_id = a.borrower_party_id WHERE a.security_type = 'CREDIT' GROUP BY p.display_name, a.borrower_party_id ORDER BY 授信金额合计 DESC, a.borrower_party_id;	bankreg_main
WITH scores AS (   SELECT hl.product_id, hl.asset_id, ROUND(hl.fair_value,2) AS fair_value,          RANK() OVER (PARTITION BY hl.product_id ORDER BY hl.fair_value DESC) AS rk,          ROUND(AVG(hl.fair_value) OVER (PARTITION BY hl.product_id),2) AS avg_v   FROM product_holding_snapshot hl ) SELECT p.product_name, hp.asset_id, hp.fair_value, hp.rk, hp.avg_v FROM scores hp JOIN wealth_product p ON p.product_id=hp.product_id WHERE hp.fair_value > 1.5*hp.avg_v ORDER BY hp.rk ASC, hp.product_id;	bankreg_main
WITH borrowers AS (   SELECT DISTINCT borrower_party_id AS pid FROM credit_agreement ) SELECT pr.source_party_id AS 甲方编号, pr.target_party_id AS 乙方编号,        rc.relation_name_zh AS 关联关系名称 FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type JOIN borrowers b1 ON b1.pid = pr.source_party_id JOIN borrowers b2 ON b2.pid = pr.target_party_id WHERE rc.relation_name_zh <> '非关联方' ORDER BY rc.relation_name_zh, pr.relation_id;	bankreg_main
SELECT eg.group_name, COUNT(DISTINCT egm.party_id) AS members,        ROUND(SUM(lbs.principal_balance),2) AS bal, ROUND(cs.net_capital,2) AS cap,        ROUND(SUM(lbs.principal_balance)*1.0/cs.net_capital,6) AS ratio FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id=eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id=egm.party_id AND a.institution_id=eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id=ld.loan_id JOIN capital_snapshot cs ON cs.institution_id=eg.institution_id GROUP BY eg.exposure_group_id, eg.group_name HAVING COUNT(DISTINCT egm.party_id)>=2 AND SUM(lbs.principal_balance)*1.0/cs.net_capital>0.1 ORDER BY ratio DESC, eg.group_name LIMIT 200;	bankreg_main
SELECT pf.display_name AS 付款方姓名, pt.display_name AS 收款方姓名,        COUNT(*) AS 转账笔数,        ROUND(SUM(pe.amount), 2) AS 转账金额合计 FROM payment_event pe JOIN account_holder hf ON hf.account_id = pe.from_account_id AND hf.holder_role = 'PRIMARY' JOIN party pf ON pf.party_id = hf.party_id JOIN account_holder ht ON ht.account_id = pe.to_account_id AND ht.holder_role = 'PRIMARY' JOIN party pt ON pt.party_id = ht.party_id JOIN party_relation pr ON ((pr.source_party_id = hf.party_id AND pr.target_party_id = ht.party_id)                         OR (pr.source_party_id = ht.party_id AND pr.target_party_id = hf.party_id)) JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type WHERE rc.relation_name_zh <> '非关联方' GROUP BY pf.display_name, pt.display_name, hf.party_id, ht.party_id ORDER BY 转账金额合计 DESC, hf.party_id, ht.party_id;	bankreg_main
SELECT rc.relation_name_zh AS 关联关系名称,        COUNT(DISTINCT pr.target_party_id) AS 目标借款客户数 FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type WHERE rc.relation_name_zh <> '非关联方'   AND EXISTS (SELECT 1 FROM credit_agreement a WHERE a.borrower_party_id = pr.target_party_id) GROUP BY rc.relation_name_zh ORDER BY 目标借款客户数 DESC, rc.relation_name_zh;	bankreg_main
SELECT wp.product_id, wp.product_name, ma.asset_name FROM wealth_product wp JOIN product_holding_snapshot ph ON ph.product_id = wp.product_id JOIN managed_asset ma ON ma.asset_id = ph.asset_id WHERE ph.investment_path = 'NESTED_SPV' AND wp.risk_level = 'R5' AND wp.status = 'ON_SALE' ORDER BY wp.product_id, ma.asset_id;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT wp.product_id) AS prod_cnt FROM wealth_product wp JOIN product_holding_snapshot ph ON ph.product_id = wp.product_id JOIN managed_asset ma ON ma.asset_id = ph.asset_id JOIN institution i ON i.institution_id = wp.issuer_institution_id WHERE ma.is_liability = 1 GROUP BY i.institution_id, i.institution_name HAVING COUNT(DISTINCT wp.product_id) >= 20 ORDER BY prod_cnt DESC, i.institution_name;	bankreg_main
SELECT SUBSTR(c.issued_on,1,4) AS yr,        SUM(CASE WHEN t.name_zh='贷记卡' THEN 1 ELSE 0 END) AS credit_cnt,        SUM(CASE WHEN t.name_zh='借记卡' THEN 1 ELSE 0 END) AS debit_cnt FROM payment_card c JOIN card_type_catalog t ON t.card_type=c.card_type GROUP BY SUBSTR(c.issued_on,1,4) ORDER BY yr;	bankreg_main
WITH grp_branch AS (   SELECT egm.exposure_group_id AS gid,          COUNT(DISTINCT a.managing_org_unit_id) AS branch_cnt,          ROUND(SUM(a.contract_amount), 2) AS group_amount   FROM exposure_group_member egm   JOIN credit_agreement a ON a.borrower_party_id = egm.party_id   GROUP BY egm.exposure_group_id ) SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        egt.name_zh AS 敞口类型, g.branch_cnt AS 涉及经办分支行数,        g.group_amount AS 集团授信合计 FROM grp_branch g JOIN exposure_group eg ON eg.exposure_group_id = g.gid JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type WHERE g.branch_cnt >= 5 ORDER BY g.branch_cnt DESC, eg.exposure_group_id;	bankreg_main
SELECT ph.product_id, COUNT(*) AS asset_cnt FROM product_holding_snapshot ph WHERE ph.investment_path = 'NESTED_SPV' GROUP BY ph.product_id ORDER BY asset_cnt DESC, ph.product_id LIMIT 20;	bankreg_main
SELECT lb.loan_id,        lb.principal_balance,        MAX(ds.principal_overdue_days) AS max_days FROM loan_balance_snapshot lb JOIN delinquency_snapshot ds ON ds.loan_id = lb.loan_id WHERE lb.overdue_principal > 0   AND lb.principal_balance > 90000000 GROUP BY lb.loan_id, lb.principal_balance HAVING MAX(ds.principal_overdue_days) >= 200 ORDER BY max_days DESC, lb.loan_id;	bankreg_main
WITH grp_amt AS (   SELECT egm.exposure_group_id AS gid, SUM(a.contract_amount) AS group_amount   FROM exposure_group_member egm   JOIN credit_agreement a ON a.borrower_party_id = egm.party_id   GROUP BY egm.exposure_group_id ) SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        i.institution_name AS 机构名称,        ROUND(g.group_amount, 2) AS 集团授信合计,        ROUND(cs.net_capital, 2) AS 机构资本净额,        ROUND(g.group_amount * 100 / cs.net_capital, 2) AS 集中度占比 FROM grp_amt g JOIN exposure_group eg ON eg.exposure_group_id = g.gid JOIN institution i ON i.institution_id = eg.institution_id JOIN capital_snapshot cs ON cs.institution_id = eg.institution_id WHERE g.group_amount * 100 > cs.net_capital ORDER BY 集中度占比 DESC, eg.exposure_group_id;	bankreg_main
SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        COUNT(DISTINCT a.institution_id) AS 涉及机构数,        COUNT(DISTINCT egm.party_id) AS 授信成员数 FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id GROUP BY eg.exposure_group_id, eg.group_name HAVING COUNT(DISTINCT a.institution_id) >= 2 ORDER BY 涉及机构数 DESC, eg.exposure_group_id;	bankreg_main
SELECT egt.name_zh AS 集团类型, eg.group_name AS 集团名称,        COUNT(DISTINCT egm.party_id) AS 成员数,        COUNT(DISTINCT a.agreement_id) AS 借款合同数 FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type LEFT JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id LEFT JOIN credit_agreement a ON a.borrower_party_id = egm.party_id GROUP BY egt.name_zh, eg.exposure_group_id, eg.group_name ORDER BY 借款合同数 DESC, eg.exposure_group_id LIMIT 15;	bankreg_main
WITH grp_ovd AS (   SELECT egm.exposure_group_id AS gid,          COUNT(DISTINCT egm.party_id) AS ovd_members,          ROUND(SUM(lbs.overdue_principal), 2) AS ovd_amount   FROM exposure_group_member egm   JOIN credit_agreement a ON a.borrower_party_id = egm.party_id   JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id   JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id   WHERE lbs.overdue_principal > 0   GROUP BY egm.exposure_group_id ) SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        g.ovd_members AS 逾期成员数, g.ovd_amount AS 逾期本金合计 FROM grp_ovd g JOIN exposure_group eg ON eg.exposure_group_id = g.gid ORDER BY g.ovd_amount DESC, eg.exposure_group_id;	bankreg_main
SELECT p.display_name AS 保证人名称, gc.guarantor_party_id AS 客户编号,        COUNT(DISTINCT gc.commitment_id) AS 集团内担保笔数,        ROUND(SUM(gc.guaranteed_amount), 2) AS 担保金额合计 FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id WHERE EXISTS (     SELECT 1     FROM security_agreement sa     JOIN secured_obligation so ON so.security_id = sa.security_id     JOIN credit_agreement a ON a.agreement_id = so.agreement_id     JOIN exposure_group_member egm1 ON egm1.party_id = gc.guarantor_party_id     JOIN exposure_group_member egm2 ON egm2.party_id = a.borrower_party_id     WHERE sa.security_id = gc.security_id       AND egm1.exposure_group_id = egm2.exposure_group_id ) GROUP BY p.display_name, gc.guarantor_party_id ORDER BY 担保金额合计 DESC, gc.guarantor_party_id;	bankreg_main
WITH grp AS (   SELECT eg.exposure_group_id AS gid, eg.group_name AS gname,          COUNT(DISTINCT egm.party_id) AS members,          SUM(a.contract_amount) AS amount   FROM exposure_group eg   JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id   JOIN credit_agreement a ON a.borrower_party_id = egm.party_id   GROUP BY eg.exposure_group_id, eg.group_name ) SELECT ROW_NUMBER() OVER (ORDER BY grp.amount DESC, grp.gid) AS 名次,        grp.gname AS 集团名称, ROUND(grp.amount, 2) AS 集团授信合计,        grp.members AS 成员数 FROM grp ORDER BY 集团授信合计 DESC, grp.gid LIMIT 8;	bankreg_main
WITH gs AS (   SELECT gc.guarantor_party_id AS pid, SUM(gc.guaranteed_amount) AS g_total   FROM guarantor_commitment gc   GROUP BY gc.guarantor_party_id ), bs AS (   SELECT a.borrower_party_id AS pid, SUM(a.contract_amount) AS b_total   FROM credit_agreement a   GROUP BY a.borrower_party_id ) SELECT p.display_name AS 企业名称, g.pid AS 客户编号,        ROUND(g.g_total, 2) AS 对外担保合计,        ROUND(bs.b_total, 2) AS 自身借款合计,        ROUND(g.g_total - bs.b_total, 2) AS 担保负债差额 FROM gs g JOIN bs ON bs.pid = g.pid JOIN party p ON p.party_id = g.pid WHERE p.party_type = 'CORPORATE' AND g.g_total > bs.b_total ORDER BY 担保负债差额 DESC, g.pid;	bankreg_main
SELECT p.display_name, sm.staff_id, COUNT(a.agreement_id) AS cnt FROM staff_member sm JOIN party p ON p.party_id=sm.person_party_id JOIN credit_agreement a ON a.borrower_party_id=p.party_id GROUP BY p.party_id ORDER BY cnt DESC, sm.staff_id;	bankreg_main
SELECT a.agreement_id AS 合同编号, a.borrower_party_id AS 借款人编号,        a.security_type AS 担保方式,        ROUND(SUM(so.covered_amount), 2) AS 担保覆盖合计 FROM credit_agreement a JOIN secured_obligation so ON so.agreement_id = a.agreement_id WHERE a.security_type = 'NONE' GROUP BY a.agreement_id, a.borrower_party_id, a.security_type HAVING SUM(so.covered_amount) > 0 ORDER BY 担保覆盖合计 DESC, a.agreement_id;	bankreg_main
SELECT pg.display_name AS 保证人名称, pb.display_name AS 借款人名称,        ROUND(a.contract_amount, 2) AS 合同金额,        ROUND(so.covered_amount, 2) AS 担保覆盖金额 FROM secured_obligation so JOIN security_agreement sa ON sa.security_id = so.security_id JOIN credit_agreement a ON a.agreement_id = so.agreement_id JOIN party pb ON pb.party_id = a.borrower_party_id JOIN guarantor_commitment gc ON gc.security_id = sa.security_id JOIN party pg ON pg.party_id = gc.guarantor_party_id WHERE so.covered_amount > a.contract_amount   AND gc.status = 'ACTIVE' ORDER BY so.covered_amount DESC, so.secured_obligation_id;	bankreg_main
SELECT p.display_name, p.party_id, ROUND(SUM(lbs.principal_balance),2) AS bal, pp.annual_income,        ROUND(SUM(lbs.principal_balance)*1.0/pp.annual_income,2) AS multiple FROM person_profile pp JOIN party p ON p.party_id=pp.party_id JOIN credit_agreement a ON a.borrower_party_id=p.party_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id=ld.loan_id GROUP BY p.party_id, pp.annual_income HAVING SUM(lbs.principal_balance)*1.0/pp.annual_income>2 ORDER BY multiple DESC, p.party_id LIMIT 200;	bankreg_main
WITH staff_acct AS (   SELECT ah.account_id AS aid FROM account_holder ah   JOIN party p ON p.party_id = ah.party_id   WHERE p.party_type = 'STAFF' AND ah.holder_role = 'PRIMARY' ), corp_acct AS (   SELECT ah.account_id AS aid FROM account_holder ah   JOIN party p ON p.party_id = ah.party_id   WHERE p.party_type = 'CORPORATE' AND ah.holder_role = 'PRIMARY' ) SELECT pf.display_name AS 员工姓名, pt.display_name AS 收款企业名称,        COUNT(*) AS 转账笔数,        ROUND(SUM(pe.amount), 2) AS 转账金额合计 FROM payment_event pe JOIN staff_acct sf ON sf.aid = pe.from_account_id JOIN corp_acct co ON co.aid = pe.to_account_id JOIN account_holder hf ON hf.account_id = pe.from_account_id AND hf.holder_role = 'PRIMARY' JOIN party pf ON pf.party_id = hf.party_id JOIN account_holder ht ON ht.account_id = pe.to_account_id AND ht.holder_role = 'PRIMARY' JOIN party pt ON pt.party_id = ht.party_id GROUP BY pf.display_name, pt.display_name, hf.party_id, ht.party_id ORDER BY 转账金额合计 DESC, hf.party_id, ht.party_id LIMIT 20;	bankreg_main
SELECT p.display_name AS 员工姓名, so.operator_id AS 操作员编号,        so.authority_level AS 权限级别, COUNT(DISTINCT a.agreement_id) AS 自贷合同数 FROM service_operator so JOIN staff_member sm ON sm.staff_id = so.staff_id JOIN party p ON p.party_id = sm.person_party_id JOIN credit_agreement a ON a.borrower_party_id = p.party_id WHERE so.operator_kind = 'CREDIT_OFFICER' GROUP BY p.display_name, so.operator_id, sm.person_party_id, so.authority_level ORDER BY 自贷合同数 DESC, so.operator_id;	bankreg_main
SELECT p.display_name AS 员工姓名, p.party_id AS 员工客户编号,        i.institution_name AS 机构名称,        COUNT(DISTINCT ah.account_id) AS 涉事对公账户数 FROM account_holder ah JOIN party p ON p.party_id = ah.party_id AND p.party_type = 'STAFF' JOIN account a ON a.account_id = ah.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE EXISTS (SELECT 1 FROM account_holder ah2               JOIN party p2 ON p2.party_id = ah2.party_id               WHERE ah2.account_id = ah.account_id AND p2.party_type = 'CORPORATE') GROUP BY p.display_name, p.party_id, i.institution_name ORDER BY 涉事对公账户数 DESC, p.party_id;	bankreg_main
SELECT p.display_name AS 员工姓名, ld.loan_id AS 借据编号,        ROUND(ld.disbursed_amount, 2) AS 放款金额, ld.disbursed_on AS 放款日期 FROM loan_drawdown ld JOIN account ac ON ac.account_id = ld.disbursement_account_id JOIN account_holder ah ON ah.account_id = ac.account_id AND ah.holder_role = 'PRIMARY' JOIN party p ON p.party_id = ah.party_id AND p.party_type = 'STAFF' ORDER BY ld.disbursed_amount DESC, ld.loan_id;	bankreg_main
SELECT p.display_name AS 借款人姓名, pp.party_id AS 客户编号,        ROUND(pp.annual_income, 2) AS 年收入,        ROUND(SUM(lbs.principal_balance), 2) AS 贷款本金余额,        ROUND(SUM(lbs.principal_balance) / pp.annual_income, 2) AS 债务收入倍数 FROM person_profile pp JOIN party p ON p.party_id = pp.party_id JOIN credit_agreement a ON a.borrower_party_id = pp.party_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id GROUP BY p.display_name, pp.party_id, pp.annual_income HAVING SUM(lbs.principal_balance) > 2 * pp.annual_income ORDER BY 债务收入倍数 DESC, pp.party_id;	bankreg_main
WITH borrower_due AS (   SELECT a.borrower_party_id, SUM(rs.principal_due + rs.interest_due) AS total_due   FROM repayment_schedule rs   JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id   JOIN credit_agreement a ON a.agreement_id = ld.agreement_id   GROUP BY a.borrower_party_id ) SELECT p.display_name AS 借款人姓名, pp.party_id AS 客户编号,        ROUND(pp.annual_income, 2) AS 年收入,        ROUND(bd.total_due, 2) AS 应还本息总额,        ROUND(bd.total_due / pp.annual_income, 2) AS 占年收入倍数 FROM borrower_due bd JOIN person_profile pp ON pp.party_id = bd.borrower_party_id JOIN party p ON p.party_id = pp.party_id ORDER BY 占年收入倍数 DESC, pp.party_id LIMIT 50;	bankreg_main
SELECT lpc.product_name_zh AS 产品类别名称,        COUNT(rs.installment_id) AS 逾期期数,        ROUND(SUM(rs.principal_due), 2) AS 逾期本金合计 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN loan_product_catalog lpc ON lpc.product_code = ld.drawdown_type WHERE rs.status = 'OVERDUE' GROUP BY lpc.product_name_zh ORDER BY 逾期本金合计 DESC, lpc.product_name_zh;	bankreg_main
SELECT ym, kind, COUNT(*) AS cnt, ROUND(SUM(amount),2) AS tot FROM (   SELECT SUBSTR(e.business_date,1,7) AS ym, '现金' AS kind, e.amount FROM payment_event e WHERE e.is_cash=1   UNION ALL   SELECT SUBSTR(e.business_date,1,7), '转账', e.amount FROM payment_event e WHERE e.payment_type='TRANSFER' ) GROUP BY ym, kind ORDER BY ym, kind;	bankreg_main
SELECT i.institution_name,        SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30')<0 THEN 1 ELSE 0 END) AS expired_cnt,        SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30') BETWEEN 0 AND 90 THEN 1 ELSE 0 END) AS soon_cnt,        SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30')>90 THEN 1 ELSE 0 END) AS far_cnt FROM term_deposit td JOIN account a ON a.account_id = td.account_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name HAVING SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30')<0 THEN 1 ELSE 0 END) >= 20 ORDER BY expired_cnt DESC, i.institution_name;	bankreg_main
WITH multi AS (   SELECT account_id FROM account_holder GROUP BY account_id HAVING COUNT(*) > 1 ) SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT m.account_id) AS 联合账户数量 FROM multi m JOIN account a ON a.account_id = m.account_id JOIN organization_unit ou ON ou.org_unit_id = a.org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 联合账户数量 DESC, ou.org_unit_id;	bankreg_main
WITH inflow AS (   SELECT to_account_id AS aid, COUNT(*) AS c, SUM(amount) AS amt   FROM payment_event GROUP BY to_account_id ), outflow AS (   SELECT from_account_id AS aid, SUM(amount) AS amt   FROM payment_event GROUP BY from_account_id ) SELECT i.aid AS 账户编号, i.c AS 流入笔数,        ROUND(i.amt, 2) AS 流入金额合计,        ROUND(o.amt, 2) AS 流出金额合计,        ROUND(i.amt - o.amt, 2) AS 净流入金额 FROM inflow i JOIN outflow o ON o.aid = i.aid ORDER BY 净流入金额 DESC, i.aid LIMIT 20;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT ld.loan_id) AS 逾期笔数,        ROUND(SUM(lbs.overdue_principal), 2) AS 逾期本金合计 FROM credit_agreement a JOIN organization_unit ou ON ou.org_unit_id = a.managing_org_unit_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id WHERE lbs.overdue_principal > 0 GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 逾期本金合计 DESC, ou.org_unit_id;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(rs.installment_id) AS 逾期分期期数 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN organization_unit ou ON ou.org_unit_id = a.managing_org_unit_id WHERE rs.status = 'OVERDUE' GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 逾期分期期数 DESC, ou.org_unit_id;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT ld.loan_id) AS 发放笔数,        ROUND(SUM(ld.disbursed_amount), 2) AS 发放金额合计 FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN organization_unit ou ON ou.org_unit_id = a.managing_org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 发放金额合计 DESC, ou.org_unit_id;	bankreg_main
SELECT CASE WHEN td.annual_interest_rate >= 3.0 THEN 'HIGH'             WHEN td.annual_interest_rate >= 2.4 THEN 'MID'             ELSE 'LOW' END AS band,        COUNT(*) AS cnt,        ROUND(AVG(td.opening_principal), 2) AS avg_principal FROM term_deposit td JOIN account a ON a.account_id = td.account_id WHERE a.status = 'ACTIVE' GROUP BY band HAVING COUNT(*) < 120 ORDER BY avg_principal DESC, band;	bankreg_main
SELECT r.loan_id, COUNT(*) AS 逾期期数, ROUND(SUM(r.principal_due), 2) AS 逾期本金合计 FROM repayment_schedule r WHERE r.status = 'OVERDUE' GROUP BY r.loan_id HAVING SUM(r.principal_due) > 120000000 ORDER BY 逾期本金合计 DESC, r.loan_id;	bankreg_main
SELECT i.institution_name, COUNT(rs.installment_id) AS 逾期期数, ROUND(SUM(rs.interest_due), 2) AS 利息合计 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = ca.institution_id WHERE rs.status = 'OVERDUE' GROUP BY i.institution_id, i.institution_name HAVING COUNT(rs.installment_id) >= 30 ORDER BY 逾期期数 DESC, i.institution_name;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(rs.installment_id) AS 逾期期数, ROUND(SUM(rs.principal_due), 2) AS 本金合计 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode WHERE rs.status = 'OVERDUE' GROUP BY pm.payment_mode_name_zh HAVING COUNT(rs.installment_id) > 450 ORDER BY 本金合计 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT cl.collateral_id,        MAX(cv.valuation_amount) AS latest_val,        MAX(cl.pledged_amount) AS pledged FROM collateral_link cl JOIN collateral_valuation cv ON cv.collateral_id = cl.collateral_id JOIN collateral_asset bc ON bc.collateral_id = cl.collateral_id WHERE bc.status = 'ACTIVE'   AND cv.valuation_type = 'EXTERNAL' GROUP BY cl.collateral_id HAVING (MAX(cl.pledged_amount) / MAX(cv.valuation_amount)) BETWEEN 0.5 AND 0.98 ORDER BY latest_val DESC;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT rs.loan_id) AS 逾期贷款数 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = ca.institution_id WHERE rs.status = 'OVERDUE' GROUP BY i.institution_id, i.institution_name HAVING COUNT(DISTINCT rs.loan_id) >= 240 ORDER BY 逾期贷款数 DESC, i.institution_name;	bankreg_main
SELECT rs.loan_id, rs.installment_no, rs.principal_due, rs.interest_due FROM repayment_schedule rs WHERE rs.status = 'OVERDUE' AND rs.principal_due > 90000000 ORDER BY rs.principal_due DESC, rs.loan_id;	bankreg_main
WITH cnte AS (   SELECT r.loan_id, COUNT(*) AS n   FROM repayment_schedule r   WHERE r.status = 'OVERDUE'   GROUP BY r.loan_id   HAVING COUNT(*) >= 2 ) SELECT c.loan_id, c.n AS 逾期期数, ROUND(lbs.principal_balance, 2) AS 当前本金余额 FROM cnte c JOIN loan_balance_snapshot lbs ON lbs.loan_id = c.loan_id WHERE lbs.principal_balance <= 50000000 ORDER BY 当前本金余额 DESC, c.loan_id;	bankreg_main
SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        COUNT(DISTINCT CASE WHEN lb.pid IS NOT NULL THEN lb.pid END) AS 已贷款成员数,        COUNT(DISTINCT egm.party_id) - COUNT(DISTINCT CASE WHEN lb.pid IS NOT NULL THEN lb.pid END) AS 未贷款成员数 FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id LEFT JOIN (   SELECT DISTINCT a.borrower_party_id AS pid FROM credit_agreement a ) lb ON lb.pid = egm.party_id GROUP BY eg.exposure_group_id, eg.group_name ORDER BY 已贷款成员数 DESC, eg.exposure_group_id;	bankreg_main
SELECT e.payment_id, e.business_date, e.amount, i.institution_name FROM payment_event e JOIN account ha ON ha.account_id=e.from_account_id JOIN institution i ON i.institution_id=ha.institution_id WHERE e.payment_type='TRANSFER'   AND EXISTS (SELECT 1 FROM account_holder ah JOIN party p ON p.party_id=ah.party_id WHERE ah.account_id=e.from_account_id AND p.party_type='STAFF' AND ah.holder_role='PRIMARY')   AND EXISTS (SELECT 1 FROM account_holder ah2 JOIN party p2 ON p2.party_id=ah2.party_id WHERE ah2.account_id=e.to_account_id AND p2.party_type='CORPORATE' AND ah2.holder_role='PRIMARY') ORDER BY e.amount DESC, e.payment_id LIMIT 200;	bankreg_main
SELECT sm.staff_id AS 员工编号, p.display_name AS 员工姓名,        COUNT(DISTINCT sa.security_id) AS 管理担保合同笔数,        ROUND(SUM(sa.secured_amount), 2) AS 管理担保金额合计 FROM security_agreement sa JOIN staff_member sm ON sm.staff_id = sa.manager_staff_id JOIN party p ON p.party_id = sm.person_party_id WHERE sa.status = 'ACTIVE' GROUP BY sm.staff_id, p.display_name ORDER BY 管理担保金额合计 DESC, sm.staff_id;	bankreg_main
WITH fac AS (SELECT cf.institution_id, SUM(cf.limit_amount) AS tl, COUNT(cf.facility_id) AS n FROM credit_facility cf GROUP BY cf.institution_id), drawn AS (SELECT a.institution_id, SUM(ld.disbursed_amount) AS td FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id=ld.agreement_id GROUP BY a.institution_id), cap AS (SELECT cs.institution_id, cs.net_capital AS nc FROM capital_snapshot cs) SELECT i.institution_name, ROUND(f.tl,2) AS tl, ROUND(d.td,2) AS td, ROUND(c.nc,2) AS nc,        ROUND(d.td*1.0/c.nc,4) AS ratio FROM fac f JOIN drawn d ON d.institution_id=f.institution_id JOIN cap c ON c.institution_id=f.institution_id JOIN institution i ON i.institution_id=f.institution_id WHERE d.td > c.nc ORDER BY ratio DESC, i.institution_name;	bankreg_main
SELECT sa.security_id AS 担保合同编号,        ROUND(sa.secured_amount, 2) AS 设定担保金额,        COUNT(DISTINCT gc.commitment_id) AS 保证人个数,        ROUND(SUM(gc.guaranteed_amount), 2) AS 保证金额合计 FROM security_agreement sa JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE gc.status = 'ACTIVE' AND sa.security_type = 'GUARANTEE' GROUP BY sa.security_id, sa.secured_amount HAVING SUM(gc.guaranteed_amount) < sa.secured_amount ORDER BY 保证金额合计 DESC, sa.security_id;	bankreg_main
SELECT cf.facility_id, cf.limit_amount, sc.name_zh AS 额度状态名称 FROM credit_facility cf JOIN status_catalog sc ON sc.status_code = cf.status AND sc.entity = 'credit_agreement' WHERE cf.facility_type = 'REVOLVING' ORDER BY cf.limit_amount DESC, cf.facility_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS 记录数, ROUND(SUM(cf.limit_amount), 2) AS 限额合计 FROM credit_facility cf JOIN institution i ON i.institution_id = cf.institution_id WHERE cf.facility_type = 'REVOLVING' AND cf.limit_amount > 500000000 GROUP BY i.institution_id, i.institution_name ORDER BY 限额合计 DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS 记录数, ROUND(SUM(cf.limit_amount), 2) AS 限额合计 FROM credit_facility cf JOIN institution i ON i.institution_id = cf.institution_id WHERE cf.facility_type = 'REVOLVING' GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) > 12 ORDER BY 限额合计 DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, cf.facility_type, ROUND(SUM(cf.limit_amount), 2) AS 授信限额合计 FROM credit_facility cf JOIN institution i ON i.institution_id = cf.institution_id GROUP BY i.institution_id, i.institution_name, cf.facility_type HAVING SUM(cf.limit_amount) > 2000000000 ORDER BY 授信限额合计 DESC, i.institution_name;	bankreg_main
SELECT cf.facility_type, COUNT(*) AS 记录数 FROM credit_facility cf WHERE cf.limit_amount > 300000000 GROUP BY cf.facility_type ORDER BY 记录数 DESC, cf.facility_type;	bankreg_main
WITH per_org AS (   SELECT ca.institution_id, COUNT(DISTINCT cf.facility_id) AS cnt   FROM credit_facility cf   JOIN credit_agreement ca ON ca.facility_id = cf.facility_id   GROUP BY ca.institution_id ) SELECT i.institution_name, p.cnt AS 授信额度记录数 FROM per_org p JOIN institution i ON i.institution_id = p.institution_id ORDER BY 授信额度记录数 DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, ROUND(SUM(cf.limit_amount), 2) AS 总限额 FROM credit_facility cf JOIN institution i ON i.institution_id = cf.institution_id WHERE cf.facility_type = 'REVOLVING' GROUP BY i.institution_id, i.institution_name HAVING SUM(cf.limit_amount) > 5000000000 ORDER BY 总限额 DESC, i.institution_name;	bankreg_main
WITH ranked AS (     SELECT cf.obligor_party_id, ROUND(cf.limit_amount, 2) AS max_limit, cf.facility_type,            ROW_NUMBER() OVER (PARTITION BY cf.obligor_party_id ORDER BY cf.limit_amount DESC, cf.facility_id ASC) AS rn     FROM credit_facility cf ) SELECT obligor_party_id, max_limit, facility_type FROM ranked WHERE rn = 1 ORDER BY max_limit DESC, obligor_party_id LIMIT 200;	bankreg_main
SELECT RANK() OVER (ORDER BY tsum DESC) AS rk, i.institution_name, tsum, avg_amt FROM (   SELECT a.institution_id, ROUND(SUM(td.opening_principal),2) AS tsum, ROUND(AVG(td.opening_principal),2) AS avg_amt   FROM term_deposit td JOIN account a ON a.account_id=td.account_id   GROUP BY a.institution_id ) t JOIN institution i ON i.institution_id=t.institution_id ORDER BY rk, i.institution_name;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(*) AS 记录数 FROM loan_drawdown ld JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode GROUP BY pm.payment_mode_name_zh ORDER BY 记录数 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, ROUND(SUM(lbs.principal_balance), 2) AS 本金余额合计 FROM loan_drawdown ld JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode GROUP BY pm.payment_mode_name_zh ORDER BY 本金余额合计 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(*) AS 发放笔数, ROUND(SUM(ld.disbursed_amount), 2) AS 发放金额合计 FROM loan_drawdown ld JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode GROUP BY pm.payment_mode_name_zh HAVING COUNT(*) > 1100 ORDER BY 发放金额合计 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(*) AS 指令笔数, ROUND(SUM(pi.instruction_amount), 2) AS 指令金额合计 FROM payment_instruction pi JOIN payment_mode_catalog pm ON pm.payment_mode = pi.payment_mode GROUP BY pm.payment_mode_name_zh HAVING SUM(pi.instruction_amount) < 1000000000000 ORDER BY 指令金额合计 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, pi.instruction_amount, pi.status FROM payment_instruction pi JOIN payment_mode_catalog pm ON pm.payment_mode = pi.payment_mode WHERE pi.instruction_amount > 220000000 ORDER BY pi.instruction_amount DESC, pi.instruction_id;	bankreg_main
SELECT p.customer_segment,        COUNT(*) AS cnt FROM party p WHERE p.party_type = 'INDIVIDUAL'   AND NOT EXISTS (     SELECT 1 FROM account_holder ah     WHERE ah.party_id = p.party_id AND ah.holder_role = 'PRIMARY'   ) GROUP BY p.customer_segment HAVING COUNT(*) < 50 ORDER BY cnt DESC, p.customer_segment;	bankreg_main
SELECT o.unit_name, COUNT(DISTINCT a.account_id) AS acct_cnt, COUNT(ah.account_holder_id) AS holder_cnt FROM organization_unit o JOIN account a ON a.org_unit_id=o.org_unit_id LEFT JOIN account_holder ah ON ah.account_id=a.account_id GROUP BY o.org_unit_id, o.unit_name ORDER BY holder_cnt DESC, o.unit_name LIMIT 200;	bankreg_main
WITH wp AS (   SELECT product_id, minimum_holding_days,          NTILE(4) OVER (ORDER BY actual_raise_amount DESC) AS quartile   FROM wealth_product WHERE status = 'ON_SALE' ) SELECT q.quartile,        COUNT(*) AS cnt FROM wp q WHERE q.minimum_holding_days > 0 GROUP BY q.quartile HAVING COUNT(*) BETWEEN 31 AND 33 ORDER BY q.quartile;	bankreg_main
SELECT ROUND(SUM(cf.limit_amount), 2) AS 循环授信限额合计, COUNT(DISTINCT ld.loan_id) AS 发放笔数 FROM credit_facility cf JOIN credit_agreement ca ON ca.facility_id = cf.facility_id JOIN loan_drawdown ld ON ld.agreement_id = ca.agreement_id JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode WHERE cf.facility_type = 'REVOLVING' AND pm.payment_mode_name_zh = '受托支付' ORDER BY 循环授信限额合计 DESC;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(*) AS 待执行指令数量 FROM payment_instruction pi JOIN payment_mode_catalog pm ON pm.payment_mode = pi.payment_mode WHERE pi.status = 'PENDING' GROUP BY pm.payment_mode_name_zh ORDER BY 待执行指令数量 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT it.instrument_type, it.name_zh FROM instrument_type_catalog it ORDER BY it.name_zh;	bankreg_main
SELECT sc.status_code, sc.name_zh FROM status_catalog sc WHERE sc.entity = 'loan_drawdown' ORDER BY sc.status_code;	bankreg_main
SELECT sc.name_zh AS 状态中文名称, COUNT(DISTINCT ld.loan_id) AS 借据数量 FROM loan_drawdown ld JOIN status_catalog sc ON sc.status_code = ld.status AND sc.entity = 'loan_drawdown' GROUP BY sc.name_zh ORDER BY 借据数量 DESC, sc.name_zh;	bankreg_main
SELECT it.name_zh AS 融资工具中文名称, sc.name_zh AS 实体状态中文名称 FROM instrument_type_catalog it CROSS JOIN status_catalog sc WHERE sc.entity = 'loan_drawdown' ORDER BY it.name_zh, sc.name_zh;	bankreg_main
SELECT sc.name_zh AS 状态中文名称, COUNT(*) AS 借据笔数 FROM loan_drawdown ld JOIN status_catalog sc ON sc.status_code = ld.status AND sc.entity = 'loan_drawdown' WHERE sc.name_zh = '已核销' GROUP BY sc.name_zh ORDER BY 借据笔数 DESC, sc.name_zh;	bankreg_main
SELECT pe.channel,        COUNT(*) AS n FROM payment_event pe WHERE pe.amount >= 30000000 GROUP BY pe.channel HAVING COUNT(*) < 1200 ORDER BY n DESC, pe.channel;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, ROUND(SUM(ld.disbursed_amount), 2) AS 发放金额合计, ROUND(AVG(ld.disbursed_amount), 2) AS 平均金额 FROM loan_drawdown ld JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode JOIN status_catalog sc ON sc.status_code = ld.status AND sc.entity = 'loan_drawdown' WHERE pm.payment_mode_name_zh = '受托支付' AND sc.name_zh = '已结清' GROUP BY pm.payment_mode_name_zh ORDER BY 发放金额合计 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT cf.obligor_party_id, COUNT(*) AS 授信记录数, ROUND(SUM(cf.limit_amount), 2) AS 授信限额合计 FROM credit_facility cf GROUP BY cf.obligor_party_id HAVING COUNT(*) > 3 ORDER BY 授信限额合计 DESC, cf.obligor_party_id;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT so.operator_id) AS 操作员数量,        COUNT(DISTINCT CASE WHEN so.authority_level = 'L3' THEN so.operator_id END) AS 高级权限人数 FROM service_operator so JOIN organization_unit ou ON ou.org_unit_id = so.org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 高级权限人数 DESC, ou.org_unit_id;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT sa.staff_id) AS 信贷客户经理人数 FROM staff_assignment sa JOIN organization_unit ou ON ou.org_unit_id = sa.org_unit_id WHERE sa.role_code = 'CREDIT_OFFICER' GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 信贷客户经理人数 DESC, ou.org_unit_id;	bankreg_main
with cl as (   select a.borrower_party_id, g.is_nonperforming, ld.loan_id   from risk_classification rc   join classification_grade g on g.grade_code = rc.grade_code   join loan_drawdown ld on ld.loan_id = rc.loan_id   join credit_agreement a on a.agreement_id = ld.agreement_id ) select cl.borrower_party_id, p.display_name, count(*) as 借据数,   sum(case when cl.is_nonperforming = 1 then 1 else 0 end) as 不良借据数 from cl join party p on p.party_id = cl.borrower_party_id group by cl.borrower_party_id, p.display_name having count(*) > sum(case when cl.is_nonperforming = 1 then 1 else 0 end)    and sum(case when cl.is_nonperforming = 1 then 1 else 0 end) > 0 order by 借据数 desc, cl.borrower_party_id	bankreg_main
select rc.loan_id, ld.disbursed_amount, d.principal_overdue_days, g.grade_name_zh from risk_classification rc join classification_grade g on g.grade_code = rc.grade_code join delinquency_snapshot d on d.loan_id = rc.loan_id join loan_drawdown ld on ld.loan_id = rc.loan_id where d.principal_overdue_days > 90 and g.is_nonperforming = 0 order by d.principal_overdue_days desc, rc.loan_id	bankreg_main
select rc.loan_id, g.grade_name_zh, d.principal_overdue_days, d.overdue_principal from risk_classification rc join classification_grade g on g.grade_code = rc.grade_code join delinquency_snapshot d on d.loan_id = rc.loan_id where g.grade_name_zh = '正常' and d.principal_overdue_days > 30 order by d.principal_overdue_days desc, rc.loan_id	bankreg_main
with mix as (   select a.borrower_party_id, a.institution_id,     max(g.is_nonperforming) as mx, min(g.is_nonperforming) as mn   from risk_classification rc   join classification_grade g on g.grade_code = rc.grade_code   join loan_drawdown ld on ld.loan_id = rc.loan_id   join credit_agreement a on a.agreement_id = ld.agreement_id   group by a.borrower_party_id, a.institution_id   having max(g.is_nonperforming) = 1 and min(g.is_nonperforming) = 0 ) select i.institution_name, count(*) as 交叉违约客户数 from mix join institution i on i.institution_id = mix.institution_id group by i.institution_name order by 交叉违约客户数 desc, i.institution_name	bankreg_main
with np as (   select rc.loan_id,     max(case when g.is_nonperforming = 1 then 1 else 0 end) as nonp   from risk_classification rc   join classification_grade g on g.grade_code = rc.grade_code   group by rc.loan_id ) select ps.loan_id, round(ps.recognized_amount / ps.required_amount, 4) as 拨备覆盖率 from provision_snapshot ps join np on np.loan_id = ps.loan_id where np.nonp = 1 order by 拨备覆盖率 asc, ps.loan_id	bankreg_main
select i.institution_name, count(*) as 覆盖不足笔数 from provision_snapshot ps join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where ps.provision_stage = 'STAGE_2'   and ps.recognized_amount / ps.required_amount < 0.5 group by i.institution_name order by 覆盖不足笔数 desc, i.institution_name	bankreg_main
select ps.loan_id, ps.provision_stage, round(ps.required_amount - ps.recognized_amount, 2) as 拨备缺口 from provision_snapshot ps where ps.provision_stage = 'STAGE_3' and ps.required_amount > ps.recognized_amount order by 拨备缺口 desc, ps.loan_id	bankreg_main
select i.institution_name, round(sum(ps.required_amount - ps.recognized_amount), 2) as 拨备缺口合计 from provision_snapshot ps join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where ps.required_amount > ps.recognized_amount group by i.institution_name order by 拨备缺口合计 desc, i.institution_name	bankreg_main
SELECT a.account_id,        a.account_subtype,        ab.ledger_balance FROM account a JOIN account_balance_snapshot ab ON ab.account_id = a.account_id WHERE a.account_kind = 'SAVINGS'   AND a.status = 'DORMANT'   AND NOT EXISTS (     SELECT 1 FROM account_holder h2     WHERE h2.account_id = a.account_id AND h2.holder_role = 'SECONDARY'   ) ORDER BY ab.ledger_balance DESC;	bankreg_main
SELECT sga.role_code,        COUNT(*) AS cnt FROM staff_assignment sga JOIN staff_member sm ON sm.staff_id = sga.staff_id WHERE sm.employment_type = 'PERMANENT'   AND sga.role_code <> 'RELATIONSHIP_MANAGER' GROUP BY sga.role_code HAVING COUNT(*) >= 2 ORDER BY cnt DESC, sga.role_code;	bankreg_main
SELECT p.customer_segment AS seg, COUNT(*) AS cnt FROM person_profile pp JOIN party p ON p.party_id = pp.party_id WHERE pp.annual_income > 1000000 GROUP BY p.customer_segment ORDER BY cnt DESC, p.customer_segment;	bankreg_main
SELECT ma.asset_category_primary,        COUNT(*) AS cnt FROM managed_asset ma JOIN industry_sector isec ON isec.sector_code = ma.industry_code WHERE isec.risk_category = 'RESTRICTED' GROUP BY ma.asset_category_primary HAVING COUNT(*) < 33 ORDER BY cnt DESC, ma.asset_category_primary;	bankreg_main
SELECT pp.party_id, pp.annual_income,        ROUND(SUM(f.limit_amount), 2) AS tot_credit,        ROUND(SUM(f.limit_amount) / pp.annual_income, 2) AS ratio FROM person_profile pp JOIN credit_facility f ON f.obligor_party_id = pp.party_id GROUP BY pp.party_id, pp.annual_income HAVING SUM(f.limit_amount) / pp.annual_income > 3 ORDER BY ratio DESC, pp.party_id LIMIT 10;	bankreg_main
SELECT pp.employment_sector AS sector, COUNT(*) AS cnt FROM person_profile pp WHERE pp.is_public_official = 1 GROUP BY pp.employment_sector ORDER BY cnt DESC, pp.employment_sector;	bankreg_main
SELECT ld.loan_id FROM loan_drawdown ld WHERE NOT EXISTS (SELECT 1 FROM repayment_schedule rs WHERE rs.loan_id=ld.loan_id AND rs.status='PAID') ORDER BY ld.loan_id LIMIT 200;	bankreg_main
SELECT pp.party_id,        ROUND(SUM(a.contract_amount), 2) AS tot_contract,        pp.annual_income,        ROUND(SUM(a.contract_amount) / pp.annual_income, 2) AS ratio FROM person_profile pp JOIN credit_agreement a ON a.borrower_party_id = pp.party_id GROUP BY pp.party_id, pp.annual_income HAVING SUM(a.contract_amount) > 5 * pp.annual_income ORDER BY ratio DESC, pp.party_id LIMIT 10;	bankreg_main
SELECT pp.occupation_code AS occ, pp.employment_sector AS sector, COUNT(*) AS cnt FROM person_profile pp GROUP BY pp.occupation_code, pp.employment_sector ORDER BY cnt DESC, pp.occupation_code, pp.employment_sector;	bankreg_main
SELECT o.org_unit_id, o.unit_name, COUNT(*) AS cnt FROM person_profile pp JOIN party p ON p.party_id = pp.party_id JOIN party_type_catalog t ON t.party_type = p.party_type JOIN organization_unit o ON o.org_unit_id = p.home_org_unit_id WHERE t.name_zh = '个人客户' AND pp.annual_income < 150000 GROUP BY o.org_unit_id, o.unit_name ORDER BY cnt DESC, o.unit_name;	bankreg_main
SELECT RANK() OVER (ORDER BY SUM(f.limit_amount) DESC) AS rnk,        pp.party_id,        ROUND(SUM(f.limit_amount), 2) AS tot_credit,        ROUND(SUM(f.limit_amount) / pp.annual_income, 2) AS ratio FROM person_profile pp JOIN credit_facility f ON f.obligor_party_id = pp.party_id GROUP BY pp.party_id, pp.annual_income ORDER BY tot_credit DESC LIMIT 5;	bankreg_main
SELECT pp.employment_sector AS sector, COUNT(*) AS cnt, ROUND(AVG(pp.annual_income), 0) AS avg_income FROM person_profile pp WHERE pp.employment_sector IN ('FINANCE', 'SECURITIES') GROUP BY pp.employment_sector ORDER BY avg_income DESC, pp.employment_sector;	bankreg_main
SELECT i.institution_type,        COUNT(*) AS inst_cnt,        MAX(cs.total_capital) AS max_cap FROM institution i LEFT JOIN capital_snapshot cs ON cs.institution_id = i.institution_id GROUP BY i.institution_type HAVING MAX(cs.total_capital) > 20000000000 ORDER BY inst_cnt DESC, i.institution_type;	bankreg_main
SELECT c.status AS card_status, COUNT(*) AS cnt FROM payment_card c JOIN card_type_catalog t ON t.card_type = c.card_type WHERE t.name_zh = '借记卡' GROUP BY c.status ORDER BY cnt DESC, c.status;	bankreg_main
SELECT o.org_unit_id, o.unit_name, COUNT(*) AS n,        ROUND(SUM(e.amount), 2) AS tot FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type JOIN party h ON h.party_id = c.holder_party_id JOIN organization_unit o ON o.org_unit_id = h.home_org_unit_id WHERE t.name_zh = '贷记卡' AND e.is_cash = 1 GROUP BY o.org_unit_id, o.unit_name ORDER BY tot DESC, o.unit_name;	bankreg_main
SELECT e.payment_id, c.card_id, h.party_id, e.business_date, e.amount FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type JOIN party h ON h.party_id = c.holder_party_id WHERE t.name_zh = '贷记卡' AND e.is_cash = 1 ORDER BY e.amount DESC, e.payment_id, c.card_id LIMIT 10;	bankreg_main
SELECT ds.loan_id,        MAX(ds.principal_overdue_days) AS max_days,        MAX(ds.overdue_principal) AS overdue_amt FROM delinquency_snapshot ds JOIN provision_snapshot ps ON ps.loan_id = ds.loan_id WHERE ds.principal_overdue_days BETWEEN 150 AND 250   AND ps.provision_stage = 'STAGE_3' GROUP BY ds.loan_id HAVING AVG(ds.overdue_principal) > 2000000 ORDER BY max_days DESC;	bankreg_main
SELECT h.party_id, COUNT(*) AS n, ROUND(SUM(e.amount), 2) AS tot FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type JOIN party h ON h.party_id = c.holder_party_id WHERE t.name_zh = '贷记卡' AND e.is_cash = 1 GROUP BY h.party_id HAVING COUNT(*) > 5 ORDER BY n DESC, tot DESC;	bankreg_main
SELECT p.customer_segment, ROUND(SUM(abb.ledger_balance),2) AS tot,        DENSE_RANK() OVER (ORDER BY SUM(abb.ledger_balance) DESC) AS rk FROM account_balance_snapshot abb JOIN account a ON a.account_id=abb.account_id JOIN account_holder ah ON ah.account_id=a.account_id AND ah.holder_role='PRIMARY' JOIN party p ON p.party_id=ah.party_id GROUP BY p.customer_segment ORDER BY rk;	bankreg_main
SELECT sa.security_id,        sa.secured_amount,        SUM(COALESCE(gc.guaranteed_amount, 0)) AS guaranteed_total FROM security_agreement sa LEFT JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE sa.security_type = 'GUARANTEE' GROUP BY sa.security_id, sa.secured_amount HAVING SUM(COALESCE(gc.guaranteed_amount, 0)) < sa.secured_amount ORDER BY guaranteed_total ASC;	bankreg_main
SELECT c.holder_party_id, COUNT(*) AS cnt FROM payment_card c GROUP BY c.holder_party_id HAVING COUNT(*) > 3 ORDER BY cnt DESC, c.holder_party_id;	bankreg_main
SELECT t.name_zh AS card_type_name, COUNT(*) AS n,        ROUND(AVG(e.amount), 2) AS avg_amt FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type WHERE t.name_zh IN ('贷记卡', '借记卡') AND e.is_cash = 1 GROUP BY t.card_type, t.name_zh ORDER BY avg_amt DESC, t.name_zh;	bankreg_main
SELECT pe.channel,        COUNT(*) AS n,        ROUND(AVG(pe.amount), 2) AS avg_amt FROM payment_event pe WHERE pe.is_cash = 0   AND pe.status = 'SETTLED' GROUP BY pe.channel HAVING AVG(pe.amount) > 11780000 ORDER BY avg_amt DESC, pe.channel;	bankreg_main
WITH iavg AS (SELECT a.institution_id, AVG(abb.ledger_balance) AS av FROM account_balance_snapshot abb JOIN account a ON a.account_id=abb.account_id GROUP BY a.institution_id) SELECT i.institution_name, a.account_id, ROUND(abb.ledger_balance,2) AS bal, ROUND(ia.av,2) AS avgbal, ROUND(abb.ledger_balance-ia.av,2) AS gap FROM account_balance_snapshot abb JOIN account a ON a.account_id=abb.account_id JOIN iavg ia ON ia.institution_id=a.institution_id JOIN institution i ON i.institution_id=a.institution_id WHERE abb.ledger_balance > 3*ia.av ORDER BY gap DESC, a.account_id;	bankreg_main
SELECT td.account_id, td.maturity_on, a.status FROM term_deposit td JOIN account a ON a.account_id=td.account_id WHERE julianday(td.maturity_on)<julianday('2026-06-30') AND a.status='ACTIVE' ORDER BY td.maturity_on DESC, td.account_id LIMIT 200;	bankreg_main
SELECT td.account_id, td.opening_principal, td.booked_on, td.maturity_on,        CAST(julianday(td.maturity_on)-julianday(td.booked_on) AS INTEGER) AS days FROM term_deposit td JOIN account a ON a.account_id=td.account_id WHERE a.status='ACTIVE' AND CAST(julianday(td.maturity_on)-julianday(td.booked_on) AS INTEGER) BETWEEN 30 AND 366 ORDER BY days DESC, td.account_id LIMIT 200;	bankreg_main
WITH ranked AS (   SELECT cv.collateral_id, cv.valuation_amount,          ROW_NUMBER() OVER (PARTITION BY cv.collateral_id ORDER BY cv.valuation_amount DESC) AS rn,          COUNT(*) OVER (PARTITION BY cv.collateral_id) AS n   FROM collateral_valuation cv ) SELECT ca.collateral_id, ca.asset_label, ROUND(r.valuation_amount,2) AS val FROM ranked r JOIN collateral_asset ca ON ca.collateral_id=r.collateral_id WHERE r.rn=1 AND r.n>=2 ORDER BY val DESC, ca.collateral_id;	bankreg_main
SELECT wp.product_name,        ROUND(wp.actual_raise_amount, 2) AS actual_amt,        ROUND(wp.planned_raise_amount, 2) AS planned_amt FROM wealth_product wp WHERE wp.actual_raise_amount < wp.planned_raise_amount * 0.5   AND wp.status = 'ON_SALE' ORDER BY wp.actual_raise_amount DESC, wp.product_name;	bankreg_main
SELECT p.party_id, COUNT(DISTINCT a.account_id) AS dormant_cnt FROM party p JOIN account_holder ah ON ah.party_id=p.party_id JOIN account a ON a.account_id=ah.account_id AND a.status='DORMANT' WHERE p.party_type='INDIVIDUAL' GROUP BY p.party_id HAVING COUNT(DISTINCT a.account_id)>=2 ORDER BY dormant_cnt DESC, p.party_id LIMIT 200;	bankreg_main
SELECT so.authority_level AS auth_level,        COUNT(*) AS total_ops,        SUM(CASE WHEN so.operator_kind = 'CREDIT_OFFICER' THEN 1 ELSE 0 END) AS credit_ops,        SUM(CASE WHEN so.operator_kind = 'SUPERVISOR' THEN 1 ELSE 0 END) AS supervisor_ops FROM service_operator so GROUP BY so.authority_level HAVING COUNT(*) >= 2 ORDER BY total_ops DESC, so.authority_level;	bankreg_main
WITH dep AS (     SELECT ah.party_id AS party_id,            ROUND(SUM(td.opening_principal), 2) AS deposit_principal,            COUNT(*) AS deposit_count     FROM term_deposit td     JOIN account ac ON ac.account_id = td.account_id     JOIN account_holder ah ON ah.account_id = ac.account_id AND ah.holder_role = 'PRIMARY'     GROUP BY ah.party_id ) SELECT a.borrower_party_id AS party_id, p.display_name,        ROUND(SUM(lbs.principal_balance), 2) AS loan_balance,        d.deposit_principal,        ROUND(d.deposit_principal * 1.0 / NULLIF(SUM(lbs.principal_balance), 0), 2) AS coverage FROM credit_agreement a JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN party p ON p.party_id = a.borrower_party_id JOIN dep d ON d.party_id = a.borrower_party_id WHERE d.deposit_principal >= 10000000 GROUP BY a.borrower_party_id, p.display_name, d.deposit_principal ORDER BY coverage DESC, a.borrower_party_id;	bankreg_main
WITH loan_tot AS (     SELECT a.borrower_party_id AS party_id,            ROUND(SUM(lbs.principal_balance), 2) AS loan_balance,            COUNT(DISTINCT ld.loan_id) AS loan_cnt     FROM credit_agreement a     JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id     JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id     GROUP BY a.borrower_party_id ) SELECT p.party_id, p.display_name,        ROUND(SUM(ab.ledger_balance), 2) AS deposit_balance,        lt.loan_balance FROM party p JOIN account_holder ah ON ah.party_id = p.party_id AND ah.holder_role = 'PRIMARY' JOIN account ac ON ac.account_id = ah.account_id JOIN account_balance_snapshot ab ON ab.account_id = ac.account_id JOIN loan_tot lt ON lt.party_id = p.party_id WHERE p.party_type = 'CORPORATE'   AND ac.account_kind IN ('CURRENT', 'SAVINGS') GROUP BY p.party_id, p.display_name, lt.loan_balance HAVING SUM(ab.ledger_balance) > lt.loan_balance    AND lt.loan_balance > 0 ORDER BY deposit_balance DESC, p.party_id;	bankreg_main
with od as (   select distinct a.borrower_party_id   from credit_agreement a   join loan_drawdown ld on ld.agreement_id = a.agreement_id   join delinquency_snapshot d on d.loan_id = ld.loan_id and d.principal_overdue_days > 0 ) select od.borrower_party_id, p.display_name,   round(sum(td.opening_principal), 2) as 定期存单金额, count(*) as 存单笔数 from od join party p on p.party_id = od.borrower_party_id join account_holder ah on ah.party_id = od.borrower_party_id and ah.holder_role = 'PRIMARY' join account ac on ac.account_id = ah.account_id join term_deposit td on td.account_id = ac.account_id group by od.borrower_party_id, p.display_name order by 定期存单金额 desc, od.borrower_party_id	bankreg_main
with dep as (   select ah.party_id, sum(td.opening_principal) as dep_total   from term_deposit td   join account ac on ac.account_id = td.account_id   join account_holder ah on ah.account_id = ac.account_id and ah.holder_role = 'PRIMARY'   group by ah.party_id ), lob as (   select a.borrower_party_id, a.institution_id, sum(lbs.principal_balance) as loan_bal   from credit_agreement a   join loan_drawdown ld on ld.agreement_id = a.agreement_id   join loan_balance_snapshot lbs on lbs.loan_id = ld.loan_id   group by a.borrower_party_id, a.institution_id ) select i.institution_name, count(distinct lob.borrower_party_id) as 挂钩客户数,   round(sum(lob.loan_bal), 2) as 挂钩贷款余额合计 from lob join dep on dep.party_id = lob.borrower_party_id join institution i on i.institution_id = lob.institution_id group by i.institution_name order by 挂钩贷款余额合计 desc, i.institution_name	bankreg_main
select so.secured_obligation_id, a.agreement_id, sa.security_id,   sa.effective_to, a.maturity_on from secured_obligation so join security_agreement sa on sa.security_id = so.security_id join credit_agreement a on a.agreement_id = so.agreement_id where sa.effective_to < a.maturity_on and a.status = 'ACTIVE' order by a.maturity_on asc, so.secured_obligation_id	bankreg_main
select i.institution_name, sa.security_type, count(*) as 错配合同数 from secured_obligation so join security_agreement sa on sa.security_id = so.security_id join credit_agreement a on a.agreement_id = so.agreement_id join institution i on i.institution_id = a.institution_id where sa.effective_to < a.maturity_on group by i.institution_name, sa.security_type order by 错配合同数 desc, i.institution_name, sa.security_type	bankreg_main
with latest_val as (   select collateral_id, valuation_amount,     row_number() over (partition by collateral_id order by valued_on desc, valuation_id desc) as rn   from collateral_valuation ), pt as (   select collateral_id, round(sum(pledged_amount), 2) as total_pledged   from collateral_link where status = 'ACTIVE'   group by collateral_id ) select ca.collateral_id, ca.asset_label, lv.valuation_amount as 最新评估值,   pt.total_pledged as 质押合计, round(pt.total_pledged - lv.valuation_amount, 2) as 超押金额 from collateral_asset ca join latest_val lv on lv.collateral_id = ca.collateral_id and lv.rn = 1 join pt on pt.collateral_id = ca.collateral_id where lv.valuation_amount < pt.total_pledged order by 超押金额 desc, ca.collateral_id	bankreg_main
with mv as (   select collateral_id, min(valuation_amount) as min_val, max(valuation_amount) as max_val   from collateral_valuation group by collateral_id ) select cl.collateral_id, round(sum(cl.pledged_amount), 2) as 质押合计, mv.min_val as 最低评估值,   round(sum(cl.pledged_amount) - mv.min_val, 2) as 超押 from collateral_link cl join mv on mv.collateral_id = cl.collateral_id where cl.status = 'ACTIVE' group by cl.collateral_id, mv.min_val having sum(cl.pledged_amount) > mv.min_val order by 超押 desc, cl.collateral_id	bankreg_main
select cl.collateral_id, ca.asset_label, count(*) as 押品使用次数,   count(distinct cl.security_id) as 关联担保数 from collateral_link cl join collateral_asset ca on ca.collateral_id = cl.collateral_id where cl.status = 'ACTIVE' group by cl.collateral_id, ca.asset_label having count(*) >= 2 order by 押品使用次数 desc, cl.collateral_id	bankreg_main
WITH agr_loan AS (   SELECT agreement_id, ROUND(SUM(disbursed_amount), 2) AS total_disbursed   FROM loan_drawdown   GROUP BY agreement_id ) SELECT gmt.guarantor_party_id, p.display_name, so.agreement_id,        gmt.guaranteed_amount, al.total_disbursed FROM guarantor_commitment gmt JOIN party p ON p.party_id = gmt.guarantor_party_id JOIN security_agreement sa ON sa.security_id = gmt.security_id JOIN secured_obligation so ON so.security_id = sa.security_id JOIN agr_loan al ON al.agreement_id = so.agreement_id WHERE gmt.status = 'ACTIVE' AND gmt.guaranteed_amount > al.total_disbursed ORDER BY gmt.guaranteed_amount DESC, gmt.guarantor_party_id, so.agreement_id;	bankreg_main
select distinct a.borrower_party_id, p.display_name, pc.card_id, pe.payment_id, pe.amount from credit_agreement a join loan_drawdown ld on ld.agreement_id = a.agreement_id join delinquency_snapshot d on d.loan_id = ld.loan_id and d.principal_overdue_days > 0 join party p on p.party_id = a.borrower_party_id join payment_card pc on pc.holder_party_id = a.borrower_party_id and pc.status = 'ACTIVE' and pc.card_type = 'CREDIT' join payment_event pe on pe.from_account_id = pc.settlement_account_id   and pe.payment_type in ('CARD_PURCHASE','CASH_WITHDRAWAL') order by pe.amount desc, a.borrower_party_id, pc.card_id, pe.payment_id limit 100	bankreg_main
select pc.holder_party_id, count(*) as 有效贷记卡数 from payment_card pc where pc.card_type = 'CREDIT' and pc.status = 'ACTIVE'   and pc.holder_party_id in (     select distinct a.borrower_party_id     from credit_agreement a     join loan_drawdown ld on ld.agreement_id = a.agreement_id     join delinquency_snapshot d on d.loan_id = ld.loan_id   ) group by pc.holder_party_id order by 有效贷记卡数 desc, pc.holder_party_id	bankreg_main
with odl as (   select distinct a.borrower_party_id, a.institution_id   from credit_agreement a   join loan_drawdown ld on ld.agreement_id = a.agreement_id   join delinquency_snapshot d on d.loan_id = ld.loan_id and d.principal_overdue_days > 0 ) select i.institution_name,   round(sum(pe.amount), 2) as 逾期客户卡消费金额, count(*) as 交易笔数 from odl join institution i on i.institution_id = odl.institution_id join payment_card pc on pc.holder_party_id = odl.borrower_party_id and pc.status = 'ACTIVE' and pc.card_type = 'CREDIT' join payment_event pe on pe.from_account_id = pc.settlement_account_id   and pe.payment_type in ('CARD_PURCHASE','CASH_WITHDRAWAL') group by i.institution_name order by 逾期客户卡消费金额 desc, i.institution_name	bankreg_main
select a.agreement_id, a.borrower_party_id, a.contract_amount,   round(sum(so.covered_amount), 2) as 担保覆盖合计,   round(a.contract_amount - sum(so.covered_amount), 2) as 保障缺口 from credit_agreement a join secured_obligation so on so.agreement_id = a.agreement_id join security_agreement sa on sa.security_id = so.security_id where a.status = 'ACTIVE' and sa.status = 'ACTIVE' group by a.agreement_id, a.borrower_party_id, a.contract_amount having sum(so.covered_amount) < a.contract_amount order by 保障缺口 desc, a.agreement_id limit 100	bankreg_main
select a.agreement_id, a.borrower_party_id, a.contract_amount from credit_agreement a where a.status = 'ACTIVE'   and not exists (     select 1 from secured_obligation so     join security_agreement sa on sa.security_id = so.security_id     where so.agreement_id = a.agreement_id and sa.status = 'ACTIVE'   ) order by a.contract_amount desc, a.agreement_id limit 100	bankreg_main
select i.institution_name, g.grade_name_zh, count(*) as 拨备不足借据数 from provision_snapshot ps join risk_classification rc on rc.loan_id = ps.loan_id join classification_grade g on g.grade_code = rc.grade_code join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where g.grade_name_zh = '次级' and ps.required_amount > ps.recognized_amount group by i.institution_name, g.grade_name_zh order by 拨备不足借据数 desc, i.institution_name	bankreg_main
select a.borrower_party_id, l.loan_id, l.principal_balance as 贷款余额,   a.contract_amount as 授信金额, round(l.principal_balance / a.contract_amount, 2) as 余额倍数 from loan_balance_snapshot l join loan_drawdown ld on ld.loan_id = l.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id where l.principal_balance >= 4.0 * a.contract_amount order by 余额倍数 desc, l.loan_id	bankreg_main
select g.grade_name_zh, count(*) as 借据数, round(sum(lbs.principal_balance), 2) as 本金合计 from risk_classification rc join classification_grade g on g.grade_code = rc.grade_code join loan_balance_snapshot lbs on lbs.loan_id = rc.loan_id where g.is_nonperforming = 1 group by g.grade_name_zh order by 借据数 desc, g.grade_name_zh	bankreg_main
with dd as (   select ld.loan_id, a.institution_id   from loan_drawdown ld   join credit_agreement a on a.agreement_id = ld.agreement_id   join (select loan_id from delinquency_snapshot where principal_overdue_days > 90) d on d.loan_id = ld.loan_id ) select i.institution_name, count(*) as 逾期未下调借据数 from risk_classification rc join classification_grade g on g.grade_code = rc.grade_code join dd on dd.loan_id = rc.loan_id join institution i on i.institution_id = dd.institution_id where g.is_nonperforming = 0 group by i.institution_name order by 逾期未下调借据数 desc, i.institution_name	bankreg_main
select i.institution_name, g.grade_name_zh, count(*) as 多计提笔数,   round(sum(ps.recognized_amount - ps.required_amount), 2) as 多计提金额 from provision_snapshot ps join risk_classification rc on rc.loan_id = ps.loan_id join classification_grade g on g.grade_code = rc.grade_code join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where g.is_nonperforming = 1 and ps.recognized_amount > ps.required_amount group by i.institution_name, g.grade_name_zh order by 多计提金额 desc, i.institution_name, g.grade_name_zh	bankreg_main
SELECT sa.security_id, so.agreement_id, so.covered_amount, a.contract_amount,        ROUND(a.contract_amount - so.covered_amount, 2) AS gap FROM secured_obligation so JOIN security_agreement sa ON sa.security_id = so.security_id JOIN credit_agreement a ON a.agreement_id = so.agreement_id WHERE so.covered_amount < a.contract_amount ORDER BY gap DESC, sa.security_id, so.agreement_id;	bankreg_main
SELECT a.agreement_id, a.borrower_party_id, a.contract_amount,        ROUND(SUM(so.covered_amount), 2) AS covered_total,        ROUND(a.contract_amount - SUM(so.covered_amount), 2) AS gap FROM credit_agreement a JOIN secured_obligation so ON so.agreement_id = a.agreement_id JOIN security_agreement sa ON sa.security_id = so.security_id WHERE sa.status = 'ACTIVE' GROUP BY a.agreement_id, a.borrower_party_id, a.contract_amount HAVING SUM(so.covered_amount) < a.contract_amount ORDER BY a.contract_amount - SUM(so.covered_amount) DESC, a.agreement_id;	bankreg_main
SELECT a.borrower_party_id, p.display_name,        ROUND(SUM(so.covered_amount), 2) AS covered_total FROM secured_obligation so JOIN security_agreement sa ON sa.security_id = so.security_id JOIN credit_agreement a ON a.agreement_id = so.agreement_id JOIN party p ON p.party_id = a.borrower_party_id WHERE sa.status = 'ACTIVE' GROUP BY a.borrower_party_id, p.display_name HAVING SUM(so.covered_amount) > 400000000 ORDER BY SUM(so.covered_amount) DESC, a.borrower_party_id;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT so.security_id) AS sec_count,        ROUND(SUM(so.covered_amount), 2) AS covered_total FROM secured_obligation so JOIN credit_agreement a ON a.agreement_id = so.agreement_id JOIN institution i ON i.institution_id = a.institution_id JOIN security_agreement sa ON sa.security_id = so.security_id WHERE sa.status = 'ACTIVE' GROUP BY i.institution_id, i.institution_name ORDER BY SUM(so.covered_amount) DESC, i.institution_name;	bankreg_main
SELECT a.agreement_id, a.contract_amount, COUNT(so.security_id) AS sec_count FROM credit_agreement a JOIN secured_obligation so ON so.agreement_id = a.agreement_id GROUP BY a.agreement_id, a.contract_amount HAVING COUNT(so.security_id) >= 2 ORDER BY COUNT(so.security_id) DESC, a.agreement_id;	bankreg_main
SELECT ca.collateral_id, ca.asset_label, ca.collateral_type FROM collateral_asset ca LEFT JOIN collateral_link cl ON cl.collateral_id = ca.collateral_id WHERE cl.collateral_link_id IS NULL ORDER BY ca.collateral_id;	bankreg_main
SELECT ca.collateral_id, ca.asset_label,        MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) AS internal_val,        MIN(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) AS external_val,        ROUND(MIN(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END)            - MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END), 2) AS diff FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valuation_type IN ('INTERNAL', 'EXTERNAL') GROUP BY ca.collateral_id, ca.asset_label HAVING MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) IS NOT NULL    AND MIN(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) IS NOT NULL ORDER BY MIN(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END)         - MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) DESC, ca.collateral_id;	bankreg_main
SELECT ca.collateral_id, ca.asset_label,        MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) AS internal_val,        MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) AS external_val,        ROUND(MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END)            - MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END), 2) AS under_diff FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valuation_type IN ('INTERNAL', 'EXTERNAL') GROUP BY ca.collateral_id, ca.asset_label HAVING MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) IS NOT NULL    AND MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) IS NOT NULL    AND MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END)      < MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) ORDER BY MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END)         - MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) DESC, ca.collateral_id;	bankreg_main
SELECT ca.collateral_type,        ROUND(AVG(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END), 2) AS avg_int,        ROUND(AVG(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END), 2) AS avg_ext,        ROUND(AVG(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END)            * 1.0 / AVG(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END), 4) AS ratio FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valuation_type IN ('INTERNAL', 'EXTERNAL') GROUP BY ca.collateral_type HAVING AVG(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) IS NOT NULL    AND AVG(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) IS NOT NULL ORDER BY ratio DESC, ca.collateral_type;	bankreg_main
WITH cnt AS (     SELECT ca.collateral_id AS collateral_id, ca.asset_label AS label,            COUNT(cv.valuation_id) AS val_count     FROM collateral_asset ca     JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id     GROUP BY ca.collateral_id, ca.asset_label ) SELECT collateral_id, label, val_count,        DENSE_RANK() OVER (ORDER BY val_count DESC) AS rank_by_freq FROM cnt WHERE val_count >= 3 ORDER BY val_count DESC, collateral_id;	bankreg_main
WITH pledged_tot AS (     SELECT collateral_id AS collateral_id, ROUND(SUM(pledged_amount), 2) AS total_pledged,            COUNT(*) AS links     FROM collateral_link     WHERE status = 'ACTIVE'     GROUP BY collateral_id ) SELECT ca.collateral_id AS collateral_id, ca.asset_label AS label,        (SELECT cv.valuation_amount FROM collateral_valuation cv          WHERE cv.collateral_id = ca.collateral_id          ORDER BY cv.valued_on DESC, cv.valuation_id DESC LIMIT 1) AS latest_val,        pt.total_pledged,        ROUND(pt.total_pledged - (SELECT cv.valuation_amount FROM collateral_valuation cv                WHERE cv.collateral_id = ca.collateral_id                ORDER BY cv.valued_on DESC, cv.valuation_id DESC LIMIT 1), 2) AS gap FROM collateral_asset ca JOIN pledged_tot pt ON pt.collateral_id = ca.collateral_id WHERE (SELECT cv.valuation_amount FROM collateral_valuation cv          WHERE cv.collateral_id = ca.collateral_id          ORDER BY cv.valued_on DESC, cv.valuation_id DESC LIMIT 1) < pt.total_pledged ORDER BY gap DESC, ca.collateral_id;	bankreg_main
SELECT ca.collateral_type, COUNT(cv.valuation_id) AS ext_count,        ROUND(SUM(cv.valuation_amount), 2) AS ext_total FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valuation_type = 'EXTERNAL' GROUP BY ca.collateral_type ORDER BY SUM(cv.valuation_amount) DESC, ca.collateral_type;	bankreg_main
SELECT gc.guarantor_party_id, p.display_name,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE' GROUP BY gc.guarantor_party_id, p.display_name ORDER BY SUM(gc.guaranteed_amount) DESC, gc.guarantor_party_id LIMIT 10;	bankreg_main
SELECT gmt.guarantor_party_id, p.display_name,        ROUND((SELECT SUM(a.contract_amount) FROM credit_agreement a               WHERE a.borrower_party_id = gmt.guarantor_party_id), 2) AS own_borrow,        ROUND(SUM(gmt.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gmt JOIN party p ON p.party_id = gmt.guarantor_party_id WHERE gmt.status = 'ACTIVE'   AND EXISTS (SELECT 1 FROM credit_agreement ca               WHERE ca.borrower_party_id = gmt.guarantor_party_id) GROUP BY gmt.guarantor_party_id, p.display_name HAVING SUM(gmt.guaranteed_amount) > (SELECT SUM(a.contract_amount) FROM credit_agreement a                                      WHERE a.borrower_party_id = gmt.guarantor_party_id) ORDER BY SUM(gmt.guaranteed_amount) DESC, gmt.guarantor_party_id;	bankreg_main
SELECT sa.security_id, sa.secured_amount, COUNT(gc.commitment_id) AS guarantor_count,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM security_agreement sa JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE gc.status = 'ACTIVE' GROUP BY sa.security_id, sa.secured_amount HAVING SUM(gc.guaranteed_amount) < sa.secured_amount ORDER BY SUM(gc.guaranteed_amount) DESC, sa.security_id;	bankreg_main
SELECT gc.security_id, sa.secured_amount, gc.guarantor_party_id, gc.guaranteed_amount,        ROUND(gc.guaranteed_amount - sa.secured_amount, 2) AS excess FROM guarantor_commitment gc JOIN security_agreement sa ON sa.security_id = gc.security_id WHERE gc.status = 'ACTIVE'   AND gc.guaranteed_amount > sa.secured_amount ORDER BY gc.guaranteed_amount - sa.secured_amount DESC, gc.security_id;	bankreg_main
SELECT p.customer_segment,        COUNT(*) AS cnt FROM person_profile pp JOIN party p ON p.party_id = pp.party_id WHERE pp.is_public_official = 1   AND pp.annual_income >= 300000 GROUP BY p.customer_segment ORDER BY cnt DESC, p.customer_segment;	bankreg_main
SELECT eg.exposure_group_id, eg.group_name, egt.name_zh,        COUNT(DISTINCT egm.party_id) AS member_count FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id GROUP BY eg.exposure_group_id, eg.group_name, egt.name_zh ORDER BY COUNT(DISTINCT egm.party_id) DESC, eg.exposure_group_id;	bankreg_main
SELECT egt.name_zh,        COUNT(DISTINCT eg.exposure_group_id) AS group_count,        COUNT(DISTINCT egm.party_id) AS member_count FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id GROUP BY egt.name_zh ORDER BY COUNT(DISTINCT egm.party_id) DESC, egt.name_zh;	bankreg_main
SELECT i.institution_name, egt.name_zh, COUNT(DISTINCT egm.party_id) AS member_count FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN institution i ON i.institution_id = eg.institution_id GROUP BY i.institution_name, egt.name_zh HAVING COUNT(DISTINCT egm.party_id) >= 6 ORDER BY COUNT(DISTINCT egm.party_id) DESC, i.institution_name;	bankreg_main
WITH grp_bal AS (     SELECT eg.institution_id, egt.name_zh,            SUM(lbs.principal_balance) AS bal_total     FROM exposure_group eg     JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type     JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id     JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id     JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id     JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id     GROUP BY eg.institution_id, egt.name_zh ) SELECT i.institution_name, gb.name_zh,        ROUND(gb.bal_total, 2) AS bal_total,        ROUND(cs.net_capital, 2) AS net_capital,        ROUND(gb.bal_total * 1.0 / cs.net_capital, 6) AS ratio FROM grp_bal gb JOIN institution i ON i.institution_id = gb.institution_id JOIN capital_snapshot cs ON cs.institution_id = gb.institution_id ORDER BY ratio DESC, i.institution_name, gb.name_zh;	bankreg_main
SELECT egm.party_id, p.display_name, COUNT(DISTINCT egm.exposure_group_id) AS group_count FROM exposure_group_member egm JOIN party p ON p.party_id = egm.party_id GROUP BY egm.party_id, p.display_name HAVING COUNT(DISTINCT egm.exposure_group_id) >= 2 ORDER BY COUNT(DISTINCT egm.exposure_group_id) DESC, egm.party_id;	bankreg_main
SELECT rc.relation_name_zh, COUNT(pr.relation_id) AS rel_count FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type GROUP BY rc.relation_name_zh ORDER BY COUNT(pr.relation_id) DESC, rc.relation_name_zh;	bankreg_main
SELECT p.party_id, p.display_name, rel.rel_count, ag.agreement_count FROM party p JOIN (SELECT source_party_id AS pid, COUNT(*) AS rel_count       FROM party_relation JOIN relation_type_catalog rc ON rc.relation_type = party_relation.relation_type       WHERE rc.relation_name_zh <> '非关联方'       GROUP BY source_party_id) rel ON rel.pid = p.party_id JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count       FROM credit_agreement GROUP BY borrower_party_id) ag ON ag.pid = p.party_id ORDER BY rel.rel_count DESC, p.party_id;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(DISTINCT egm.exposure_group_id) AS group_count FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type JOIN party p ON p.party_id = pr.source_party_id JOIN exposure_group_member egm ON egm.party_id = p.party_id WHERE rc.relation_name_zh = '影子股东' GROUP BY p.party_id, p.display_name ORDER BY COUNT(DISTINCT egm.exposure_group_id) DESC, p.party_id;	bankreg_main
SELECT pr.source_party_id, p.display_name,        COUNT(DISTINCT pr.target_party_id) AS target_count FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type JOIN party p ON p.party_id = pr.source_party_id WHERE rc.relation_name_zh = '实际控制人' GROUP BY pr.source_party_id, p.display_name ORDER BY COUNT(DISTINCT pr.target_party_id) DESC, pr.source_party_id;	bankreg_main
SELECT pr.relation_id, pr.source_party_id, pr.target_party_id,        CASE WHEN sb.agreement_count IS NULL THEN 0 ELSE sb.agreement_count END AS src_agr,        CASE WHEN tb.agreement_count IS NULL THEN 0 ELSE tb.agreement_count END AS tgt_agr FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type LEFT JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count            FROM credit_agreement GROUP BY borrower_party_id) sb ON sb.pid = pr.source_party_id LEFT JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count            FROM credit_agreement GROUP BY borrower_party_id) tb ON tb.pid = pr.target_party_id WHERE rc.relation_name_zh <> '非关联方'   AND sb.agreement_count IS NOT NULL AND tb.agreement_count IS NOT NULL ORDER BY COALESCE(sb.agreement_count, 0) + COALESCE(tb.agreement_count, 0) DESC, pr.relation_id;	bankreg_main
with earliest as (   select a.agreement_id, min(sa.effective_to) as earliest_expiry   from credit_agreement a   join secured_obligation so on so.agreement_id = a.agreement_id   join security_agreement sa on sa.security_id = so.security_id   group by a.agreement_id ) select e.agreement_id, a.borrower_party_id, a.maturity_on, e.earliest_expiry,   round(julianday(a.maturity_on) - julianday(e.earliest_expiry), 0) as 脱保天数 from earliest e join credit_agreement a on a.agreement_id = e.agreement_id where e.earliest_expiry < a.maturity_on order by a.maturity_on asc, e.agreement_id	bankreg_main
select ca.collateral_id, ca.asset_label,   max(case when cv.valuation_type = 'EXTERNAL' then cv.valuation_amount end) as 外部评估,   max(case when cv.valuation_type = 'INTERNAL' then cv.valuation_amount end) as 内部评估,   round(max(case when cv.valuation_type = 'EXTERNAL' then cv.valuation_amount end) * 100.0 /     max(case when cv.valuation_type = 'INTERNAL' then cv.valuation_amount end), 2) as 外部占比 from collateral_asset ca join collateral_valuation cv on cv.collateral_id = ca.collateral_id where cv.valuation_type in ('EXTERNAL','INTERNAL') group by ca.collateral_id, ca.asset_label having max(case when cv.valuation_type = 'EXTERNAL' then cv.valuation_amount end) <        max(case when cv.valuation_type = 'INTERNAL' then cv.valuation_amount end) order by 外部占比 asc, ca.collateral_id	bankreg_main
select ca.collateral_id, ca.asset_label, ca.collateral_type from collateral_asset ca where ca.status = 'ACTIVE'   and not exists (     select 1 from collateral_link cl     where cl.collateral_id = ca.collateral_id and cl.status = 'ACTIVE'   ) order by ca.collateral_id	bankreg_main
WITH own AS (     SELECT a.borrower_party_id AS party_id, ROUND(SUM(lbs.principal_balance), 2) AS own_loan     FROM credit_agreement a     JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id     JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id     GROUP BY a.borrower_party_id ) SELECT gc.guarantor_party_id AS party_id, p.display_name,        ROUND(SUM(gc.guaranteed_amount), 2) AS guaranteed_total,        COALESCE(o.own_loan, 0) AS own_loan_bal,        ROUND(SUM(gc.guaranteed_amount) - COALESCE(o.own_loan, 0), 2) AS excess FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id LEFT JOIN own o ON o.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE' GROUP BY gc.guarantor_party_id, p.display_name, o.own_loan HAVING SUM(gc.guaranteed_amount) > COALESCE(o.own_loan, 0) ORDER BY excess DESC, gc.guarantor_party_id;	bankreg_main
select pc.holder_party_id, p.display_name, pc.card_id, pc.expires_on from payment_card pc join party p on p.party_id = pc.holder_party_id where pc.card_type = 'CREDIT' and pc.status = 'ACTIVE'   and exists (     select 1 from credit_agreement a     join loan_drawdown ld on ld.agreement_id = a.agreement_id     join delinquency_snapshot d on d.loan_id = ld.loan_id     where a.borrower_party_id = pc.holder_party_id and d.principal_overdue_days > 90   ) order by pc.expires_on asc, pc.card_id	bankreg_main
select pe.payment_id, pe.from_account_id, pe.to_account_id, pe.amount, pe.business_date from payment_event pe where pe.payment_type = 'LOAN_REPAYMENT'   and pe.from_account_id in (     select ld.disbursement_account_id     from loan_drawdown ld   ) order by pe.amount desc, pe.payment_id limit 100	bankreg_main
SELECT gc.guarantor_party_id AS party_id, p.display_name,        gc.guaranteed_amount AS guaranteed_amount,        gc.status AS guarantor_status FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE'   AND EXISTS (     SELECT 1     FROM credit_agreement a     JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id     JOIN delinquency_snapshot d ON d.loan_id = ld.loan_id AND d.principal_overdue_days > 0     WHERE a.borrower_party_id = gc.guarantor_party_id   ) ORDER BY gc.guaranteed_amount DESC, gc.guarantor_party_id;	bankreg_main
with su as (   select ps.loan_id, ps.recognized_amount, ps.required_amount   from provision_snapshot ps   where ps.provision_stage = 'STAGE_3' and ps.required_amount > ps.recognized_amount ) select g.grade_name_zh, count(*) as 缺口借据数,   round(sum(su.required_amount - su.recognized_amount), 2) as 缺口合计 from su join risk_classification rc on rc.loan_id = su.loan_id join classification_grade g on g.grade_code = rc.grade_code group by g.grade_name_zh order by 缺口合计 desc, g.grade_name_zh	bankreg_main
SELECT o.org_unit_id, o.unit_name,        COUNT(DISTINCT a.borrower_party_id) AS 逾期借款人户数,        ROUND(SUM(lbs.principal_balance), 2) AS 逾期借据本金余额合计 FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id = d.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN organization_unit o ON o.org_unit_id = a.managing_org_unit_id GROUP BY o.org_unit_id, o.unit_name ORDER BY 逾期借据本金余额合计 DESC, o.org_unit_id;	bankreg_main
select d.loan_id, d.principal_overdue_days,   round(d.overdue_principal, 2) as 逾期本金,   round(lbs.principal_balance, 2) as 本金余额,   round(d.overdue_principal / lbs.principal_balance, 2) as 逾期占比 from delinquency_snapshot d join loan_balance_snapshot lbs on lbs.loan_id = d.loan_id where lbs.principal_balance > 0   and d.overdue_principal > lbs.principal_balance order by 逾期占比 desc, d.loan_id	bankreg_main
WITH sec AS (     SELECT institution_id AS institution_id, ROUND(SUM(secured_amount), 2) AS secured_total,            COUNT(DISTINCT security_id) AS n_agreements     FROM security_agreement     WHERE status = 'ACTIVE'     GROUP BY institution_id ), cov AS (     SELECT sa.institution_id AS institution_id, ROUND(SUM(so.covered_amount), 2) AS covered_total     FROM secured_obligation so     JOIN security_agreement sa ON sa.security_id = so.security_id     GROUP BY sa.institution_id ) SELECT i.institution_name, sc.secured_total, cv.covered_total,        ROUND(cv.covered_total * 100.0 / sc.secured_total, 2) AS utilization_pct FROM sec sc JOIN cov cv ON cv.institution_id = sc.institution_id JOIN institution i ON i.institution_id = sc.institution_id ORDER BY utilization_pct, i.institution_name;	bankreg_main
with cov as (   select rc.loan_id, g.is_nonperforming   from risk_classification rc   join classification_grade g on g.grade_code = rc.grade_code ) select o.org_unit_id, o.unit_name,   count(*) as 不良借据数,   round(sum(ps.recognized_amount) / nullif(sum(ps.required_amount), 0), 4) as 拨备覆盖率 from cov join loan_drawdown ld on ld.loan_id = cov.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join organization_unit o on o.org_unit_id = a.managing_org_unit_id join provision_snapshot ps on ps.loan_id = cov.loan_id where cov.is_nonperforming = 1 group by o.org_unit_id, o.unit_name order by 拨备覆盖率 asc, o.unit_name	bankreg_main
WITH dlq AS (SELECT ca.borrower_party_id AS party, ca.institution_id AS inst, SUM(d.overdue_principal) AS overdue FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id GROUP BY ca.borrower_party_id, ca.institution_id) SELECT wp.product_name, ma.asset_name, ma.obligor_party_id, ROUND(dlq.overdue,2) AS sum_overdue FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id JOIN managed_asset ma ON ma.asset_id=ph.asset_id JOIN dlq ON dlq.party=ma.obligor_party_id AND dlq.overdue>0 AND dlq.inst=wp.issuer_institution_id JOIN party pc ON pc.party_id=ma.obligor_party_id AND pc.party_type='CORPORATE' WHERE ph.lookthrough_depth>=2 ORDER BY wp.product_name, sum_overdue DESC;	bankreg_main
SELECT ma.internal_rating,        COUNT(*) AS cnt FROM managed_asset ma WHERE ma.is_liability = 1 GROUP BY ma.internal_rating HAVING COUNT(*) BETWEEN 25 AND 30 ORDER BY cnt DESC, ma.internal_rating;	bankreg_main
WITH rated AS (   SELECT ma.asset_id, ma.asset_name, ma.internal_rating, ma.external_rating,          CASE ma.internal_rating WHEN 'AAA' THEN 1 WHEN 'AA+' THEN 2 WHEN 'AA' THEN 3 WHEN 'A+' THEN 4 WHEN 'A' THEN 5 WHEN 'BBB' THEN 6 ELSE 7 END AS in_score,          CASE ma.external_rating WHEN 'AAA' THEN 1 WHEN 'AA+' THEN 2 WHEN 'AA' THEN 3 WHEN 'A+' THEN 4 WHEN 'A' THEN 5 WHEN 'BBB' THEN 6 ELSE 7 END AS ex_score   FROM managed_asset ma   WHERE ma.asset_scope = 'NON_STANDARDIZED' AND ma.valuation_method = 'AMORTIZED_COST' ) SELECT asset_id, asset_name, internal_rating, external_rating FROM rated WHERE ex_score > in_score ORDER BY asset_id;	bankreg_main
SELECT sa.security_type, COUNT(DISTINCT sa.security_id) AS sec_count,        ROUND(SUM(so.covered_amount), 2) AS covered_total FROM secured_obligation so JOIN security_agreement sa ON sa.security_id = so.security_id JOIN credit_agreement a ON a.agreement_id = so.agreement_id WHERE a.status = 'ACTIVE' GROUP BY sa.security_type ORDER BY SUM(so.covered_amount) DESC, sa.security_type;	bankreg_main
WITH latest AS (     SELECT collateral_id AS collateral_id, valuation_amount AS valuation_amount,            ROW_NUMBER() OVER (PARTITION BY collateral_id ORDER BY valued_on DESC, valuation_id DESC) AS rn     FROM collateral_valuation ), pledged_tot AS (     SELECT collateral_id AS collateral_id, ROUND(SUM(pledged_amount), 2) AS total_pledged     FROM collateral_link     WHERE status = 'ACTIVE'     GROUP BY collateral_id ) SELECT ca.collateral_id AS collateral_id, ca.asset_label AS label,        lv.valuation_amount AS latest_val, pt.total_pledged AS total_pledged,        ROUND(lv.valuation_amount - pt.total_pledged, 2) AS excess FROM collateral_asset ca JOIN latest lv ON lv.collateral_id = ca.collateral_id AND lv.rn = 1 JOIN pledged_tot pt ON pt.collateral_id = ca.collateral_id WHERE lv.valuation_amount > pt.total_pledged * 2 ORDER BY excess DESC, ca.collateral_id;	bankreg_main
SELECT a.agreement_id, p.display_name, a.contract_amount,        COUNT(DISTINCT cl.collateral_id) AS collateral_count,        COUNT(DISTINCT gc.guarantor_party_id) AS guarantor_count FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id JOIN secured_obligation so ON so.agreement_id = a.agreement_id JOIN security_agreement sa ON sa.security_id = so.security_id JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE sa.status = 'ACTIVE' GROUP BY a.agreement_id, p.display_name, a.contract_amount ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT egm.party_id) AS member_count,        ROUND(SUM(a.contract_amount), 2) AS total_amount FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN institution i ON i.institution_id = eg.institution_id WHERE egt.name_zh = '关联客户群' GROUP BY i.institution_id, i.institution_name HAVING COUNT(DISTINCT egm.party_id) >= 5 ORDER BY SUM(a.contract_amount) DESC, i.institution_name;	bankreg_main
SELECT wp.product_id, wp.product_name, SUM(ph.carrying_amount-ph.fair_value) AS inv_diff, COUNT(*) AS cnt FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id WHERE ph.carrying_amount > ph.fair_value GROUP BY wp.product_id, wp.product_name HAVING SUM(ph.carrying_amount-ph.fair_value)>0 ORDER BY inv_diff DESC, wp.product_id;	bankreg_main
WITH dlq AS (SELECT ca.borrower_party_id AS party, ca.institution_id AS inst, SUM(d.overdue_principal) AS overdue, COUNT(DISTINCT ld.loan_id) AS nln FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id GROUP BY ca.borrower_party_id, ca.institution_id) SELECT wp.product_name, ma.asset_name, ph.lookthrough_depth, ROUND(ph.carrying_amount,2) AS carry, ROUND(dlq.overdue,2) AS overdue FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id JOIN managed_asset ma ON ma.asset_id=ph.asset_id JOIN dlq ON dlq.party=ma.issuer_party_id AND dlq.overdue>0 AND dlq.inst=wp.issuer_institution_id WHERE ph.lookthrough_depth>=3 ORDER BY ph.lookthrough_depth DESC, ph.holding_id;	bankreg_main
SELECT cl.collateral_id,        SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' THEN 1 ELSE 0 END) AS first_lien_count,        SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' AND cl.pledge_ratio > 0.6 THEN 1 ELSE 0 END) AS high_ratio_count FROM collateral_link cl GROUP BY cl.collateral_id HAVING SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' AND cl.pledge_ratio > 0.6 THEN 1 ELSE 0 END) >= 2 ORDER BY SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' AND cl.pledge_ratio > 0.6 THEN 1 ELSE 0 END) DESC, cl.collateral_id;	bankreg_main
SELECT ca.collateral_id AS collateral_id, ca.asset_label AS label,        MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) AS internal_max,        MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) AS external_max,        ROUND(MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) * 1.0              / MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END), 4) AS ratio_val FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id GROUP BY ca.collateral_id, ca.asset_label HAVING MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END)      > MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) ORDER BY ratio_val DESC, ca.collateral_id;	bankreg_main
SELECT i.institution_name, f.total_assets, f.total_liabilities, f.net_assets, f.annual_revenue FROM institution i JOIN financial_snapshot f ON f.party_id = 'PTY-'||i.institution_id ORDER BY f.annual_revenue DESC;	bankreg_main
SELECT i.institution_name, ROUND(f.total_liabilities/f.total_assets,4) AS ratio_val FROM institution i JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id ORDER BY ratio_val DESC;	bankreg_main
SELECT i.institution_name, ROUND(c.tier1_capital/c.risk_weighted_assets,4) AS ratio_val FROM capital_snapshot c JOIN institution i ON i.institution_id=c.institution_id ORDER BY ratio_val DESC;	bankreg_main
SELECT i.institution_name, ROUND(c.net_capital/f.total_assets,6) AS leverage_val FROM institution i JOIN capital_snapshot c ON c.institution_id=i.institution_id JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id ORDER BY leverage_val DESC;	bankreg_main
SELECT i.institution_name, ROUND(f.net_assets/f.annual_revenue,4) AS margin FROM institution i JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id WHERE f.net_assets/f.annual_revenue < 0.85 ORDER BY margin;	bankreg_main
SELECT i.institution_name, f.total_assets, RANK() OVER (ORDER BY f.total_assets DESC) AS rank_val FROM institution i JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id ORDER BY rank_val;	bankreg_main
SELECT i.institution_name, f.annual_revenue, ROUND(f.annual_revenue*100.0/t.agg_rev,2) AS share FROM institution i JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id CROSS JOIN (SELECT SUM(annual_revenue) AS agg_rev FROM financial_snapshot) t WHERE f.annual_revenue*100.0/t.agg_rev > 15 ORDER BY share DESC;	bankreg_main
SELECT valuation_method, COUNT(*) AS asset_cnt FROM managed_asset GROUP BY valuation_method ORDER BY asset_cnt DESC;	bankreg_main
SELECT sa.security_type,        ROUND(AVG(CASE WHEN gc.guaranteed_amount < sa.secured_amount THEN 1.0 ELSE 0.0 END), 4) AS short_ratio FROM security_agreement sa JOIN guarantor_commitment gc ON gc.security_id = sa.security_id GROUP BY sa.security_type HAVING AVG(CASE WHEN gc.guaranteed_amount < sa.secured_amount THEN 1.0 ELSE 0.0 END) > 0.8 ORDER BY short_ratio DESC, sa.security_type;	bankreg_main
SELECT i.institution_name, COUNT(*) AS mismatch_cnt FROM managed_asset m JOIN institution i ON i.institution_id=m.originator_institution_id WHERE m.internal_rating<>m.external_rating GROUP BY i.institution_name ORDER BY mismatch_cnt DESC;	bankreg_main
SELECT m.valuation_method, ROUND(SUM(h.carrying_amount),2) AS carrying_total FROM product_holding_snapshot h JOIN managed_asset m ON m.asset_id=h.asset_id GROUP BY m.valuation_method ORDER BY carrying_total DESC;	bankreg_main
SELECT ph.investment_path,        COUNT(*) AS cnt FROM product_holding_snapshot ph WHERE ph.remaining_term_days > 200 GROUP BY ph.investment_path HAVING COUNT(*) < 352 ORDER BY cnt DESC, ph.investment_path;	bankreg_main
SELECT i.institution_name,        COUNT(*) AS asset_count,        ROUND(AVG(m.annual_yield_rate), 4) AS avg_yield,        ROUND(SUM(m.issued_amount), 2) AS issued_total FROM managed_asset m JOIN institution i ON i.institution_id = m.originator_institution_id WHERE m.external_rating = 'NR'   AND m.valuation_method = 'FVTPL' GROUP BY i.institution_name HAVING COUNT(*) >= 10 ORDER BY issued_total DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS deposit_cnt, ROUND(SUM(td.opening_principal),2) AS principal_total FROM term_deposit td JOIN account a ON a.account_id=td.account_id JOIN institution i ON i.institution_id=a.institution_id GROUP BY i.institution_name ORDER BY principal_total DESC;	bankreg_main
SELECT i.institution_name, COUNT(*) AS high_rate_cnt FROM term_deposit td JOIN account a ON a.account_id=td.account_id JOIN institution i ON i.institution_id=a.institution_id WHERE td.annual_interest_rate>3.0 GROUP BY i.institution_name ORDER BY high_rate_cnt DESC;	bankreg_main
SELECT so.authority_level,        COUNT(DISTINCT so.operator_id) AS ops,        COUNT(DISTINCT so.staff_id) AS staffs FROM service_operator so JOIN staff_member sm ON sm.staff_id = so.staff_id WHERE sm.employment_type = 'PERMANENT' GROUP BY so.authority_level HAVING COUNT(DISTINCT so.staff_id) >= 10 ORDER BY ops DESC, so.authority_level;	bankreg_main
SELECT i.institution_name, COUNT(*) AS due_cnt FROM term_deposit td JOIN account a ON a.account_id = td.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE julianday(td.maturity_on) - julianday('2026-06-30') BETWEEN 0 AND 30 GROUP BY i.institution_id, i.institution_name ORDER BY due_cnt DESC, i.institution_name;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(td.opening_principal), 2) AS principal_total,        COUNT(*) AS deposit_count,        ROW_NUMBER() OVER (ORDER BY SUM(td.opening_principal) DESC) AS rnk FROM term_deposit td JOIN account a ON a.account_id = td.account_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_name, i.institution_id HAVING COUNT(*) >= 15 ORDER BY rnk, i.institution_name;	bankreg_main
WITH tot AS (     SELECT product_id AS product_id, SUM(converted_amount) AS gross, COUNT(*) AS n     FROM product_holding_snapshot     GROUP BY product_id ) SELECT wp.product_name,        ma.obligor_party_id AS obligor_party_id,        ROUND(SUM(ph.converted_amount), 2) AS exposed_amount,        ROUND(SUM(ph.converted_amount) * 100.0 / tot.gross, 2) AS conc_pct FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id = ph.product_id JOIN managed_asset ma ON ma.asset_id = ph.asset_id JOIN tot ON tot.product_id = ph.product_id GROUP BY wp.product_id, wp.product_name, ma.obligor_party_id, tot.gross HAVING SUM(ph.converted_amount) * 100.0 / tot.gross > 30 ORDER BY conc_pct DESC, wp.product_name;	bankreg_main
WITH ps AS (SELECT ca.institution_id AS institution_id, SUM(pv.required_amount-pv.recognized_amount) AS shortage FROM provision_snapshot pv JOIN loan_drawdown ld ON ld.loan_id=pv.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id GROUP BY ca.institution_id) SELECT ps.institution_id, ROUND(ps.shortage,2) AS shortage, ROUND(ps.shortage/f.annual_revenue*100,2) AS ratio FROM ps JOIN financial_snapshot f ON f.party_id='PTY-'||ps.institution_id WHERE ps.shortage/f.annual_revenue>0.05 ORDER BY ratio DESC;	bankreg_main
WITH short AS (     SELECT ca.institution_id AS institution_id,            ROUND(SUM(ps.required_amount - ps.recognized_amount), 2) AS shortage     FROM provision_snapshot ps     JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id     JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id     WHERE ps.recognized_amount < ps.required_amount     GROUP BY ca.institution_id ) SELECT s.institution_id AS institution_id,        i.institution_name,        s.shortage AS shortage,        f.net_assets AS net_assets,        ROUND(s.shortage * 100.0 / f.net_assets, 2) AS pct_net_assets FROM short s JOIN institution i ON i.institution_id = s.institution_id JOIN financial_snapshot f ON f.party_id = 'PTY-' || s.institution_id ORDER BY pct_net_assets DESC, s.institution_id;	bankreg_main
WITH bad AS (SELECT ca.institution_id AS institution_id, SUM(d.overdue_principal) AS bad_bal FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id GROUP BY ca.institution_id) SELECT cs.institution_id, ROUND(cs.risk_weighted_assets/f.total_assets*100,2) AS rwa_density, ROUND(bad.bad_bal/100000000.0,2) AS bad_yi FROM capital_snapshot cs JOIN financial_snapshot f ON f.party_id='PTY-'||cs.institution_id JOIN bad ON bad.institution_id=cs.institution_id ORDER BY rwa_density DESC;	bankreg_main
SELECT g.grade_name_zh,        COUNT(*) AS cnt FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code WHERE rc.classification_basis = 'MANUAL_REVIEW' GROUP BY g.grade_name_zh HAVING COUNT(*) BETWEEN 60 AND 105 ORDER BY cnt DESC, g.grade_name_zh;	bankreg_main
SELECT s.sector_name_zh AS sector_name,        COUNT(*) AS asset_count,        ROUND(AVG(m.annual_yield_rate), 4) AS avg_yield FROM managed_asset m JOIN industry_sector s ON s.sector_code = m.industry_code WHERE s.risk_category = 'EXIT' GROUP BY s.sector_code, s.sector_name_zh HAVING COUNT(*) >= 5 ORDER BY asset_count DESC, sector_name;	bankreg_main
WITH sh AS (SELECT ca.institution_id AS institution_id, COUNT(DISTINCT ld.loan_id) AS npl_loan, SUM(d.overdue_principal) AS tot_od FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id WHERE d.principal_overdue_days>=90 GROUP BY ca.institution_id) SELECT cs.institution_id, sh.npl_loan, ROUND(sh.tot_od,2) AS tot_od FROM capital_snapshot cs JOIN sh ON sh.institution_id=cs.institution_id JOIN financial_snapshot f ON f.party_id='PTY-'||cs.institution_id WHERE sh.tot_od/f.annual_revenue>0.5 ORDER BY tot_od DESC;	bankreg_main
SELECT wp.product_name, ROUND(AVG(ph.carrying_amount-ph.fair_value),2) AS avg_diff, COUNT(*) AS holdings FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id WHERE ph.carrying_amount>ph.fair_value GROUP BY wp.product_name ORDER BY avg_diff DESC, holdings DESC;	bankreg_main
SELECT a.account_id,        a.account_subtype,        ab.available_balance FROM account a JOIN account_balance_snapshot ab ON ab.account_id = a.account_id WHERE a.status = 'ACTIVE'   AND ab.available_balance >= (SELECT AVG(available_balance) FROM account_balance_snapshot)   AND a.account_subtype = 'SPECIAL' ORDER BY ab.available_balance DESC;	bankreg_main
WITH dq AS (SELECT ca.borrower_party_id AS party, COUNT(DISTINCT ld.loan_id) AS cnt, MAX(d.overdue_principal) AS mx FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id WHERE d.principal_overdue_days>90 GROUP BY ca.borrower_party_id) SELECT wp.product_name, ma.asset_name, dq.mx AS max_od FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id JOIN managed_asset ma ON ma.asset_id=ph.asset_id JOIN dq ON dq.party=ma.obligor_party_id WHERE dq.cnt>=2 ORDER BY max_od DESC, wp.product_name;	bankreg_main
SELECT i.institution_name, ROUND(cs.tier1_capital/cs.risk_weighted_assets*100,2) AS t1_car FROM capital_snapshot cs JOIN institution i ON i.institution_id=cs.institution_id WHERE cs.tier1_capital/cs.risk_weighted_assets<0.09 ORDER BY t1_car;	bankreg_main
WITH d AS (     SELECT ph.product_id AS product_id, COUNT(*) AS deep_cnt     FROM product_holding_snapshot ph     WHERE ph.lookthrough_depth >= 3     GROUP BY ph.product_id ) SELECT wp.product_name AS product_name, d.deep_cnt AS deep_cnt,        RANK() OVER (ORDER BY d.deep_cnt DESC) AS depth_rank FROM d JOIN wealth_product wp ON wp.product_id = d.product_id ORDER BY depth_rank, wp.product_name;	bankreg_main
WITH lb AS (     SELECT ca.institution_id AS institution_id,            ROUND(SUM(lbs.principal_balance), 2) AS gross_loan     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id     WHERE ld.status = 'ACTIVE'     GROUP BY ca.institution_id ) SELECT i.institution_name AS institution_name,        lb.gross_loan AS gross_loan,        cs.risk_weighted_assets AS rwa,        ROUND(lb.gross_loan * 100.0 / cs.risk_weighted_assets, 2) AS loan_pct_rwa FROM lb JOIN institution i ON i.institution_id = lb.institution_id JOIN capital_snapshot cs ON cs.institution_id = lb.institution_id ORDER BY loan_pct_rwa DESC, i.institution_name;	bankreg_main
SELECT ma.asset_id AS asset_id, ma.asset_name AS asset_name,        ma.issuer_party_id AS issuer_party_id,        (SELECT ROUND(SUM(d.overdue_principal), 2) FROM delinquency_snapshot d          JOIN loan_drawdown ld ON ld.loan_id = d.loan_id          JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id          WHERE ca.borrower_party_id = ma.issuer_party_id) AS overdue_total FROM managed_asset ma WHERE ma.asset_scope = 'NON_STANDARDIZED'   AND EXISTS (SELECT 1 FROM delinquency_snapshot d                JOIN loan_drawdown ld ON ld.loan_id = d.loan_id                JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id                WHERE ca.borrower_party_id = ma.issuer_party_id) ORDER BY overdue_total DESC, ma.asset_id;	bankreg_main
SELECT ma.industry_code, is_.sector_name_zh, COUNT(*) AS cnt, ROUND(SUM(ma.issued_amount/100000000.0),2) AS amt_yi FROM managed_asset ma JOIN industry_sector is_ ON is_.sector_code=ma.industry_code WHERE is_.risk_category IN ('RESTRICTED','EXIT') GROUP BY ma.industry_code, is_.sector_name_zh ORDER BY amt_yi DESC, ma.industry_code;	bankreg_main
SELECT pi.payment_mode,        COUNT(*) AS cnt FROM payment_instruction pi JOIN loan_drawdown dd ON dd.loan_id = pi.loan_id WHERE pi.status = 'PENDING'   AND dd.status = 'ACTIVE' GROUP BY pi.payment_mode HAVING COUNT(*) > 45 ORDER BY cnt DESC, pi.payment_mode;	bankreg_main
WITH dlq AS (     SELECT ca.borrower_party_id AS party_id, SUM(d.overdue_principal) AS overdue,        SUM(d.overdue_interest) AS overdue_int     FROM delinquency_snapshot d     JOIN loan_drawdown ld ON ld.loan_id = d.loan_id     JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id     GROUP BY ca.borrower_party_id ) SELECT wp.issuer_institution_id AS issuer_inst,        ma.industry_code AS industry_code,        COUNT(*) AS holding_count,        ROUND(SUM(ph.converted_amount), 2) AS funded_amount,        ROUND(SUM(ph.converted_amount) OVER (PARTITION BY wp.issuer_institution_id), 2) AS issuer_funded FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id = ph.product_id JOIN managed_asset ma ON ma.asset_id = ph.asset_id JOIN dlq ON dlq.party_id = ma.obligor_party_id AND dlq.overdue > 0 WHERE ph.lookthrough_depth >= 2 GROUP BY wp.issuer_institution_id, ma.industry_code ORDER BY funded_amount DESC, ma.industry_code;	bankreg_main
SELECT i.institution_name,        COUNT(*) AS exception_cnt,        ROUND(SUM(q.amount_value), 2) AS exception_amount,        cs.net_capital,        f.total_assets,        ROUND(SUM(q.amount_value) * 100.0 / cs.net_capital, 4) AS pct_of_capital FROM prudential_metric_snapshot_v3 q JOIN institution i ON i.institution_id = q.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id JOIN financial_snapshot f ON f.party_id = 'PTY-' || i.institution_id WHERE q.exception_flag = 1 GROUP BY i.institution_id, i.institution_name, cs.net_capital, f.total_assets HAVING COUNT(*) >= 8 ORDER BY pct_of_capital DESC, i.institution_name;	bankreg_main
WITH prov AS (     SELECT a.institution_id AS institution_id,            COUNT(DISTINCT ld.loan_id) AS shortfall_loans,            ROUND(SUM(ps.required_amount - ps.recognized_amount), 2) AS shortfall_amount     FROM provision_snapshot ps     JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     WHERE ps.recognized_amount < ps.required_amount     GROUP BY a.institution_id ) SELECT i.institution_name,        COUNT(*) AS overdue_submissions,        ROUND(AVG(r.amount_value), 2) AS avg_ledger_amount,        p.shortfall_loans,        p.shortfall_amount FROM regulatory_submission_event_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN prov p ON p.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_name, p.shortfall_loans, p.shortfall_amount HAVING COUNT(*) >= 25 ORDER BY p.shortfall_amount DESC, i.institution_name;	bankreg_main
WITH instal AS (     SELECT a.institution_id AS institution_id,            COUNT(DISTINCT rs.loan_id) AS overdue_loans,            ROUND(SUM(CASE WHEN rs.status = 'OVERDUE' THEN rs.principal_due ELSE 0 END), 2) AS overdue_principal     FROM repayment_schedule rs     JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     WHERE rs.status = 'OVERDUE'     GROUP BY a.institution_id ) SELECT i.institution_name, COUNT(*) AS overdue_control,        ROUND(SUM(r.amount_value), 2) AS control_amount,        iv.overdue_loans, iv.overdue_principal FROM lending_control_event_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN instal iv ON iv.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_name, iv.overdue_loans, iv.overdue_principal HAVING COUNT(*) >= 25 ORDER BY iv.overdue_principal DESC, i.institution_name;	bankreg_main
WITH fac AS (     SELECT institution_id AS institution_id, COUNT(*) AS active_facilities     FROM credit_facility     GROUP BY institution_id ) SELECT i.institution_name, f.active_facilities,        ROUND(SUM(CASE WHEN r.exception_flag = 1 THEN r.amount_value ELSE 0 END), 2) AS except_amount,        ROUND(AVG(r.ratio_value), 4) AS avg_ratio FROM governance_control_record_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN fac f ON f.institution_id = i.institution_id GROUP BY i.institution_id, i.institution_name, f.active_facilities HAVING SUM(CASE WHEN r.exception_flag = 1 THEN 1 ELSE 0 END) >= 5 ORDER BY except_amount DESC, i.institution_name;	bankreg_main
SELECT p.display_name,        COUNT(DISTINCT pr.target_party_id) AS counterparties,        COUNT(DISTINCT pr.relation_type) AS relation_kinds,        SUM(CASE WHEN rt.relation_name_zh <> '非关联方' THEN 1 ELSE 0 END) AS vetted_edges FROM related_transaction_record_v3 r JOIN party p ON p.party_id = r.subject_id JOIN party_relation pr ON pr.source_party_id = r.subject_id JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type WHERE r.exception_flag = 1 GROUP BY p.party_id, p.display_name ORDER BY counterparties DESC, relation_kinds DESC, p.display_name;	bankreg_main
WITH dep AS (     SELECT ah.party_id AS party_id,            COUNT(*) AS term_count,            ROUND(SUM(td.opening_principal), 2) AS term_principal     FROM term_deposit td     JOIN account a ON a.account_id = td.account_id     JOIN account_holder ah ON ah.account_id = a.account_id AND ah.holder_role = 'PRIMARY'     GROUP BY ah.party_id ) SELECT p.display_name, d.term_count, d.term_principal,        ROUND(SUM(r.amount_value), 2) AS protect_amount FROM deposit_protection_record_v3 r JOIN party p ON p.party_id = r.subject_id JOIN dep d ON d.party_id = r.subject_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY p.party_id, p.display_name, d.term_count, d.term_principal ORDER BY d.term_principal DESC, p.display_name;	bankreg_main
WITH bal AS (     SELECT ah.party_id AS party_id,            ROUND(SUM(ab.ledger_balance), 2) AS deposit_balance     FROM account_balance_snapshot ab     JOIN account a ON a.account_id = ab.account_id     JOIN account_holder ah ON ah.account_id = a.account_id AND ah.holder_role = 'PRIMARY'     WHERE a.account_kind IN ('SAVINGS', 'CURRENT')     GROUP BY ah.party_id ) SELECT p.display_name, b.deposit_balance,        COUNT(*) AS cdd_records,        ROUND(AVG(r.observed_value), 4) AS avg_obs FROM customer_due_diligence_event_v3 r JOIN party p ON p.party_id = r.subject_id JOIN bal b ON b.party_id = r.subject_id WHERE r.exception_flag = 1 GROUP BY p.party_id, p.display_name, b.deposit_balance ORDER BY b.deposit_balance DESC, p.display_name;	bankreg_main
WITH card_stat AS (     SELECT a.institution_id,            COUNT(DISTINCT pc.card_id) AS active_cards,            COUNT(DISTINCT pc.holder_party_id) AS card_holders     FROM payment_card pc     JOIN account a ON a.account_id = pc.settlement_account_id     WHERE pc.status = 'ACTIVE'     GROUP BY a.institution_id ), op_stat AS (     SELECT institution_id,            COUNT(*) AS active_op_records,            ROUND(SUM(CASE WHEN exception_flag = 1 THEN amount_value ELSE 0 END), 2) AS except_amount     FROM operational_risk_event_v3     WHERE status_code = 'ACTIVE'     GROUP BY institution_id     HAVING COUNT(*) >= 43 ) SELECT i.institution_name, c.active_cards, c.card_holders,        o.except_amount, o.active_op_records FROM op_stat o JOIN card_stat c ON c.institution_id = o.institution_id JOIN institution i ON i.institution_id = o.institution_id ORDER BY o.except_amount DESC, i.institution_name;	bankreg_main
SELECT s.sector_name_zh AS sector_name,        o.operating_status AS operating_status,        ROUND(SUM(CASE WHEN r.exception_flag = 1 THEN r.amount_value ELSE 0 END), 2) AS except_amount,        ROUND(AVG(r.count_value), 2) AS avg_count FROM data_security_event_v3 r JOIN organization_profile o ON o.party_id = r.subject_id JOIN industry_sector s ON s.sector_code = o.industry_code WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY s.sector_code, s.sector_name_zh, o.operating_status HAVING COUNT(*) >= 8 ORDER BY except_amount DESC, s.sector_name_zh;	bankreg_main
WITH prod AS (     SELECT issuer_institution_id AS institution_id,            COUNT(*) AS product_cnt,            ROUND(SUM(actual_raise_amount), 2) AS raised     FROM wealth_product     WHERE status = 'ON_SALE'     GROUP BY issuer_institution_id ) SELECT i.institution_name, pr.product_cnt, pr.raised,        COUNT(*) AS conduct_records,        ROUND(AVG(r.ratio_value), 4) AS avg_ratio FROM product_conduct_event_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN prod pr ON pr.institution_id = i.institution_id WHERE r.exception_flag = 1 GROUP BY i.institution_id, i.institution_name, pr.product_cnt, pr.raised HAVING COUNT(*) >= 2 ORDER BY pr.raised DESC, i.institution_name;	bankreg_main
SELECT g.group_name, t.name_zh AS group_kind,        COUNT(DISTINCT egm.party_id) AS member_cnt,        ROUND(SUM(CASE WHEN r.exception_flag = 1 THEN r.observed_value ELSE 0 END), 4) AS except_obs,        COUNT(*) AS ubo_records FROM beneficial_owner_record_v3 r JOIN exposure_group_member egm ON egm.party_id = r.subject_id JOIN exposure_group g ON g.exposure_group_id = egm.exposure_group_id JOIN exposure_group_type_catalog t ON t.group_type = g.group_type WHERE r.status_code = 'ACTIVE' GROUP BY g.exposure_group_id, g.group_name, t.group_type, t.name_zh HAVING COUNT(DISTINCT egm.party_id) >= 3 ORDER BY member_cnt DESC, g.group_name;	bankreg_main
WITH staff_stat AS (     SELECT ou.institution_id AS institution_id,            COUNT(DISTINCT ou.org_unit_id) AS unit_cnt,            COUNT(DISTINCT s.staff_id) AS total_staff     FROM staff_member s     JOIN organization_unit ou ON ou.org_unit_id = s.home_org_unit_id     GROUP BY ou.institution_id ) SELECT i.institution_name,        COUNT(DISTINCT r.subject_id) AS licensed_people,        ss.unit_cnt,        ss.total_staff,        ROUND(AVG(r.observed_value), 4) AS avg_obs FROM license_record_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN staff_stat ss ON ss.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_id, i.institution_name, ss.unit_cnt, ss.total_staff HAVING COUNT(*) >= 25 ORDER BY licensed_people DESC, i.institution_name;	bankreg_main
WITH asset AS (     SELECT originator_institution_id AS institution_id,            COUNT(*) AS asset_cnt,            ROUND(SUM(issued_amount), 2) AS issued     FROM managed_asset     GROUP BY originator_institution_id ), custody AS (     SELECT institution_id,            COUNT(*) AS custody_records,            ROUND(SUM(CASE WHEN exception_flag = 1 THEN amount_value ELSE 0 END), 2) AS except_amount     FROM custody_operation_event_v3     WHERE status_code = 'ACTIVE'     GROUP BY institution_id     HAVING SUM(CASE WHEN exception_flag = 1 THEN 1 ELSE 0 END) >= 2 ) SELECT i.institution_name, a.asset_cnt, a.issued,        c.custody_records, c.except_amount FROM asset a JOIN institution i ON i.institution_id = a.institution_id JOIN custody c ON c.institution_id = i.institution_id ORDER BY a.issued DESC, i.institution_name;	bankreg_main
WITH pi AS (     SELECT a.institution_id AS institution_id,            COUNT(*) AS inst_cnt,            ROUND(SUM(CASE WHEN pm.payment_mode_name_zh = '受托支付' THEN pi.instruction_amount ELSE 0 END), 2) AS entrusted     FROM payment_instruction pi     JOIN payment_mode_catalog pm ON pm.payment_mode = pi.payment_mode     JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     GROUP BY a.institution_id ) SELECT i.institution_name, p.inst_cnt, p.entrusted,        COUNT(*) AS fx_records,        ROUND(AVG(r.ratio_value), 4) AS avg_ratio FROM fx_business_event_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN pi p ON p.institution_id = r.institution_id WHERE r.status_code = 'ACTIVE' GROUP BY i.institution_id, i.institution_name, p.inst_cnt, p.entrusted HAVING COUNT(*) >= 41 ORDER BY p.entrusted DESC, i.institution_name;	bankreg_main
WITH overdue_borrowers AS (   SELECT DISTINCT a.borrower_party_id   FROM delinquency_snapshot d   JOIN loan_drawdown ld ON ld.loan_id = d.loan_id   JOIN credit_agreement a ON a.agreement_id = ld.agreement_id ) SELECT i.institution_name, rec.rule_family,        COUNT(DISTINCT r.subject_id) AS overdue_party_cnt,        ROUND(SUM(r.amount_value), 2) AS total_ledger_amt FROM ai_system_record_v3 r JOIN regulatory_event_catalog rec ON rec.event_code = r.event_code JOIN overdue_borrowers ob ON ob.borrower_party_id = r.subject_id JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL GROUP BY i.institution_id, i.institution_name, rec.rule_family ORDER BY total_ledger_amt DESC, i.institution_name;	bankreg_main
